def _paper_replay_candles_fetcher(symbol, asset_type, resolution="D", from_ts=None, to_ts=None):
    end_ts = int(to_ts or time.time())
    start_ts = int(from_ts or (end_ts - (90 * 86400)))
    try:
        return candles(
            symbol=str(symbol or "").upper(),
            asset_type="crypto" if str(asset_type) == "crypto" else "stock",
            resolution=str(resolution or "D"),
            lookback_days=max(1, int((end_ts - start_ts) / 86400)),
            from_ts=start_ts,
            to_ts=end_ts,
        )
    except Exception as e:
        return {"candles": [], "data_unavailable": f"replay_candle_error:{str(e)[:80]}"}


