def _hhmm_from_str(value, default_hhmm):
    try:
        raw = str(value or "").strip()
        if ":" in raw:
            hh, mm = raw.split(":", 1)
            hh = max(0, min(23, int(hh)))
            mm = max(0, min(59, int(mm)))
            return (hh * 100) + mm
    except Exception:
        pass
    return int(default_hhmm)


def _market_session_type_et(dt_utc=None):
    try:
        dt = (dt_utc or datetime.now(UTC)).astimezone(_ET_TZ)
        hhmm = (dt.hour * 100) + dt.minute
        if 930 <= hhmm < 1600:
            return "regular_hours"
        if 400 <= hhmm < 930:
            return "premarket_learning"
        if 1600 <= hhmm < 2000:
            return "after_hours_learning"
        return "overnight_learning"
    except Exception:
        return "overnight_learning"


def _session_learning_weight(session_type):
    st = str(session_type or "").strip().lower()
    if st == "regular_hours":
        return float(SESSION_REGULAR_HOURS_WEIGHT)
    if st == "premarket_learning":
        return float(SESSION_PREMARKET_WEIGHT)
    if st == "after_hours_learning":
        return float(SESSION_AFTER_HOURS_WEIGHT)
    return float(SESSION_OVERNIGHT_WEIGHT)


def _session_hold_limit_minutes(session_type):
    st = str(session_type or "").strip().lower()
    if st == "regular_hours":
        return int(SESSION_REGULAR_MAX_HOLD_MINUTES)
    if st == "premarket_learning":
        return int(SESSION_PREMARKET_MAX_HOLD_MINUTES)
    if st == "after_hours_learning":
        return int(SESSION_AFTER_HOURS_MAX_HOLD_MINUTES)
    return int(SESSION_OVERNIGHT_MAX_HOLD_MINUTES)


def _paper_trade_close_price_from_position(pos):
    if not isinstance(pos, dict):
        return 0.0
    for key in ("current_price", "current", "price", "last_price", "mark_price", "latest_price", "quote_price"):
        v = _to_float(pos.get(key), 0.0)
        if v > 0:
            return float(v)
    return float(_to_float(pos.get("entry_price"), 0.0))


def _paper_position_holding_minutes(pos, now_utc):
    if not isinstance(pos, dict):
        return 0.0
    for key in ("entry_timestamp", "opened_at", "created_at", "timestamp"):
        raw = pos.get(key)
        if not raw:
            continue
        try:
            dt = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
            return max(0.0, (now_utc - dt.astimezone(UTC)).total_seconds() / 60.0)
        except Exception:
            continue
    return 0.0


def _day_lane_owned_positions_v1(rows):
    """Return only explicit DAY positions eligible for same-session management."""
    return [
        pos for pos in (rows or [])
        if isinstance(pos, dict)
        and str(pos.get("lane_id") or "").upper() == "DAY"
        and pos.get("same_session_exit_required") is True
    ]


def _apply_day_trading_lifecycle_rules_v1():
    now_utc = datetime.now(UTC)
    now_et = now_utc.astimezone(_ET_TZ)
    hhmm = (now_et.hour * 100) + now_et.minute
    session_type = _market_session_type_et(now_utc)
    cutoff_hhmm = _hhmm_from_str(NO_NEW_ENTRIES_AFTER_ET, 1515)
    force_close_hhmm = _hhmm_from_str(FORCE_CLOSE_TIME_ET, 1555)
    force_close_window = bool(
        FORCE_CLOSE_ALL_PAPER_POSITIONS_BEFORE_MARKET_CLOSE
        and session_type == "regular_hours"
        and hhmm >= force_close_hhmm
    )
    entry_cutoff_active = bool(session_type == "regular_hours" and hhmm >= cutoff_hhmm)
    weekday = int(now_et.weekday())
    out = {
        "day_trade_mode_enabled": bool(DAY_TRADING_LIFECYCLE_MODE_ENABLED),
        "same_day_exit_required": bool(FORCE_CLOSE_ALL_PAPER_POSITIONS_BEFORE_MARKET_CLOSE),
        "entry_cutoff_time_et": str(NO_NEW_ENTRIES_AFTER_ET),
        "force_close_time_et": str(FORCE_CLOSE_TIME_ET),
        "max_day_trade_hold_minutes": int(MAX_DAY_TRADE_HOLD_MINUTES),
        "session_type": str(session_type),
        "session_learning_weight": float(_session_learning_weight(session_type)),
        "session_hold_limit_minutes": int(_session_hold_limit_minutes(session_type)),
        "entry_cutoff_active": bool(entry_cutoff_active),
        "force_close_window_active": bool(force_close_window),
        "forced_end_of_day_exit": False,
        "forced_end_of_day_exit_reason": "",
        "holding_minutes": 0.0,
        "overnight_hold_blocked": False,
        "day_trade_lifecycle_status": "disabled",
        "same_session_exit_state": "DISABLED",
        "forced_close_count_last_cycle": 0,
        "last_forced_symbols": [],
        "last_update_utc": _now_utc_iso(),
        "last_error": "",
    }
    if not DAY_TRADING_LIFECYCLE_MODE_ENABLED:
        return out
    out["day_trade_lifecycle_status"] = "active"
    # Natural exits remain the global default.  Explicit DAY-owned positions
    # are the narrow exception: their ownership contract already requires a
    # same-session broker exit, which PaperAutopilot alone may submit.
    out["natural_exit_preservation_active"] = bool(PAPER_THROUGHPUT_PRESERVE_NATURAL_EXITS)
    if weekday >= 5:
        out["day_trade_lifecycle_status"] = "weekend_idle"
        return out
    try:
        all_open_positions = list(POSITION_TRACKER.get_open_positions() or [])
    except Exception as e:
        out["last_error"] = str(e)[:180]
        out["day_trade_lifecycle_status"] = "error"
        return out
    # The DAY worker may only manage positions explicitly owned by the DAY
    # lane. Legacy or SWING/CRYPTO rows are observed but never force-closed.
    open_positions = _day_lane_owned_positions_v1(all_open_positions)
    out["non_day_positions_ignored"] = max(0, len(all_open_positions) - len(open_positions))
    if not open_positions:
        out["same_session_exit_state"] = "NOT_APPLICABLE_NO_DAY_POSITION"
        out["session_exit_reason"] = "no_day_owned_position"
        return out
    out["same_session_exit_state"] = "CLOSING_WINDOW" if force_close_window else "MONITORING"
    max_holding = 0.0
    forced_symbols = []
    forced_count = 0
    for pos in open_positions:
        holding_minutes = _paper_position_holding_minutes(pos, now_utc)
        max_holding = max(max_holding, holding_minutes)
        entry_session = str(pos.get("market_session_at_entry") or pos.get("session_type") or session_type)
        entry_session = entry_session.strip().lower() or session_type
        hold_limit = int(_session_hold_limit_minutes(entry_session))
        should_close = False
        close_reason = ""
        entry_same_day = False
        try:
            entry_raw = pos.get("entry_timestamp") or pos.get("opened_at") or pos.get("created_at")
            if entry_raw:
                entry_dt = datetime.fromisoformat(str(entry_raw).replace("Z", "+00:00")).astimezone(_ET_TZ)
                entry_same_day = bool(entry_dt.date() == now_et.date())
        except Exception:
            entry_same_day = False
        if force_close_window:
            should_close = True
            close_reason = "end_of_day_close"
            out["forced_end_of_day_exit"] = True
            out["overnight_hold_blocked"] = True
            out["same_session_exit_state"] = "CLOSING_WINDOW"
        elif holding_minutes >= float(hold_limit):
            should_close = True
            close_reason = "session_hold_limit_exceeded"
            out["overnight_hold_blocked"] = True
        elif FORCE_CLOSE_ALL_PAPER_POSITIONS_BEFORE_MARKET_CLOSE and session_type == "regular_hours" and not entry_same_day:
            should_close = True
            close_reason = "overnight_hold_blocked"
            out["overnight_hold_blocked"] = True
        if not should_close:
            continue
        # The paper-autopilot is the sole DAY exit submitter.  This observer
        # intentionally never closes an internal row because strict truth
        # requires the matching broker exit fill first.
        sym = str(pos.get("symbol") or "").upper()
        if sym:
            forced_symbols.append(sym)
        out["day_exit_submission_owner"] = "PaperAutopilot.authorized_lane_exit_pending"
        out["broker_fill_required_before_local_close"] = True
        out["same_session_exit_state"] = "ARMED"
    out["holding_minutes"] = round(max_holding, 2)
    out["forced_close_count_last_cycle"] = int(forced_count)
    out["last_forced_symbols"] = list(dict.fromkeys(forced_symbols))[:16]
    if force_close_window:
        out["forced_end_of_day_exit_reason"] = "force_close_time_reached"
    elif forced_symbols:
        out["forced_end_of_day_exit_reason"] = "lane_exit_requested_broker_fill_pending"
    else:
        out["forced_end_of_day_exit_reason"] = ""
    out["session_exit_reason"] = str(out["forced_end_of_day_exit_reason"] or "")
    return out


def _day_trading_lifecycle_loop():
    _DAY_TRADING_LIFECYCLE_THREAD_STATE["running"] = True
    base_max_new = int(_to_float(getattr(PAPER_AUTOPILOT, "max_new_positions_per_cycle", 0), 0.0))
    while True:
        try:
            lifecycle_state = dict(_apply_day_trading_lifecycle_rules_v1() or {})
            _DAY_TRADING_LIFECYCLE_STATE.update(lifecycle_state)
            _DAY_TRADING_LIFECYCLE_THREAD_STATE["last_run_utc"] = _now_utc_iso()
            if hasattr(PAPER_AUTOPILOT, "max_new_positions_per_cycle"):
                session_type = str(lifecycle_state.get("session_type") or "regular_hours").strip().lower()
                if bool(lifecycle_state.get("entry_cutoff_active", False)):
                    setattr(PAPER_AUTOPILOT, "max_new_positions_per_cycle", 0)
                elif session_type in {"premarket_learning", "after_hours_learning"}:
                    off_hours_cap = 2 if PAPER_THROUGHPUT_EXPANSION_ENABLED else 1
                    setattr(PAPER_AUTOPILOT, "max_new_positions_per_cycle", max(0, min(int(base_max_new), off_hours_cap)))
                elif session_type == "overnight_learning":
                    overnight_cap = 2 if PAPER_THROUGHPUT_EXPANSION_ENABLED else 1
                    setattr(PAPER_AUTOPILOT, "max_new_positions_per_cycle", max(0, min(int(base_max_new), overnight_cap)))
                else:
                    setattr(PAPER_AUTOPILOT, "max_new_positions_per_cycle", int(base_max_new))
        except Exception as e:
            _DAY_TRADING_LIFECYCLE_THREAD_STATE["last_error"] = str(e)[:180]
        time.sleep(30)


def _ensure_paper_autopilot_started():
    global _PAPER_AUTOPILOT_STARTED
    role = str(os.getenv("ASTRA_PROCESS_ROLE", "api")).strip().lower()
    # API routes, startup hooks, and GET handlers are forbidden from owning
    # mutable cycles.  The dedicated module entrypoint owns ``run_cycle``.
    if role != "worker":
        PAPER_AUTOPILOT._runtime_state["worker_start_blocked_at"] = _now_utc_iso()
        PAPER_AUTOPILOT._runtime_state["worker_start_blocked_reason"] = "api_role_cannot_start_mutable_worker"
        return {"ok": False, "started": False, "blocked": True, "reason": "api_role_cannot_start_mutable_worker"}
    if _PAPER_AUTOPILOT_STARTED:
        return {"ok": True, "started": False, "already_owned_by_worker": True}
    PAPER_AUTOPILOT._runtime_state["worker_start_attempted_at"] = _now_utc_iso()
    PAPER_AUTOPILOT._runtime_state["worker_start_result"] = {"ok": True, "started": False, "owner": "engine.paper_autopilot_worker"}
    PAPER_AUTOPILOT._runtime_state["worker_start_liveness"] = {"running": True, "owner": "engine.paper_autopilot_worker"}
    _PAPER_AUTOPILOT_STARTED = True
    if DAY_TRADING_LIFECYCLE_MODE_ENABLED:
        with _DAY_TRADING_LIFECYCLE_LOCK:
            if not bool(_DAY_TRADING_LIFECYCLE_THREAD_STATE.get("started", False)):
                threading.Thread(target=_day_trading_lifecycle_loop, daemon=True).start()
                _DAY_TRADING_LIFECYCLE_THREAD_STATE["started"] = True
    return {"ok": True, "started": False, "owner": "engine.paper_autopilot_worker"}


@router.on_event("startup")
def _paper_autopilot_worker_startup_v1():
    """API startup deliberately records, but never starts, mutable worker work."""
    PAPER_AUTOPILOT._runtime_state["worker_start_blocked_at"] = _now_utc_iso()
    PAPER_AUTOPILOT._runtime_state["worker_start_blocked_reason"] = "uvicorn_api_process_is_read_only"


def _paper_autopilot_sync_worker_artifacts():
    # Deprecated heartbeat/PID compatibility files are never written.  The
    # isolated worker is the sole owner of the atomic canonical snapshot.
    return None


def _is_buy_direction(item):
    action = str(item.get("action") or "").strip().lower()
    prediction = str(item.get("prediction") or "").strip().lower()
    majority = str(item.get("majority_signal") or "").strip().lower()
    return action in {"buy", "strong buy"} or prediction in {"buy", "strong buy"} or majority == "buy"


def _to_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        if default is None:
            return None
        return float(default)


def _iso_age_seconds(value):
    if not value:
        return None
    try:
        s = str(value).replace("Z", "+00:00")
        dt = datetime.fromisoformat(s)
        return max(0.0, (datetime.now(UTC) - dt).total_seconds())
    except Exception:
        return None


def _update_provider_quality_memory(snapshot):
    if not isinstance(snapshot, dict):
        return
    try:
        ts = time.time()
        sample = dict(snapshot)
        sample["ts"] = ts
        _PROVIDER_QUALITY_MEMORY.append(sample)
    except Exception:
        pass


def _provider_quality_rolling_summary(now_ts=None):
    if now_ts is None:
        now_ts = time.time()
    windows = {
        "recent_1h_provider_quality": 3600.0,
        "recent_6h_provider_quality": 21600.0,
        "recent_24h_provider_quality": 86400.0,
    }
    out = {}
    data = list(_PROVIDER_QUALITY_MEMORY)
    for label, seconds in windows.items():
        rows = [r for r in data if isinstance(r, dict) and (now_ts - _to_float(r.get("ts"), 0.0)) <= seconds]
        if not rows:
            out[label] = {
                "samples": 0,
                "provider_quality_score": None,
                "quote_freshness_score": None,
                "cache_rescue_rate_percent": None,
                "data_degradation_pressure": None,
                "usable": False,
            }
            continue
        n = float(len(rows))
        avg_provider = sum(_to_float(r.get("provider_quality_score"), 0.0) for r in rows) / n
        avg_fresh = sum(_to_float(r.get("quote_freshness_score"), 0.0) for r in rows) / n
        avg_cache = sum(_to_float(r.get("cache_rescue_rate_percent"), 0.0) for r in rows) / n
        avg_degrade = sum(_to_float(r.get("data_degradation_pressure"), 0.0) for r in rows) / n
        out[label] = {
            "samples": int(len(rows)),
            "provider_quality_score": round(avg_provider, 2),
            "quote_freshness_score": round(avg_fresh, 2),
            "cache_rescue_rate_percent": round(avg_cache, 2),
            "data_degradation_pressure": round(avg_degrade, 2),
            "usable": bool(len(rows) >= 3),
        }
    return out


def _evaluate_buy_candidate(row):
    return _evaluate_buy_candidate_with_thresholds(
        row=row,
        min_probability=TOP_BUY_MIN_PROBABILITY,
        max_disagreement=TOP_BUY_MAX_DISAGREEMENT,
    )


def _evaluate_buy_candidate_with_thresholds(row, min_probability, max_disagreement):
    failed = []
    warnings = []

    if not bool(row.get("trusted_quote_for_buys", False)):
        failed.append("untrusted_quote")
    if not bool(row.get("valid_quote", False)):
        failed.append("invalid_quote")
    if not _is_buy_direction(row):
        failed.append("not_buy_direction")
    if not bool(row.get("signal_quality_gate_passed", False)):
        failed.append("gate_failed")
    prob = _to_float(row.get("predicted_win_probability"), 0.0)
    if prob < float(min_probability):
        failed.append("probability_below_min")
    disagreement = _to_float(row.get("persona_disagreement_index"), 100.0)
    if disagreement > float(max_disagreement):
        failed.append("disagreement_above_max")

    quote_quality = str(row.get("quote_quality") or "").strip().lower()
    if quote_quality in {"snapshot", "placeholder"}:
        warnings.append(f"quote_degraded:{quote_quality}")
        failed.append("quote_not_live")
    reason = str(row.get("data_unavailable_reason") or "").strip()
    if reason:
        warnings.append(f"data_unavailable:{reason}")
    agreement = _to_float(row.get("provider_agreement"), 1.0)
    if agreement < 0.6:
        warnings.append("low_provider_agreement")

    qualified = len(failed) == 0
    return qualified, failed, warnings


def _build_trade_plan(item):
    price = _to_float(item.get("price"), 0.0)
    if price <= 0:
        return {
            "entry_type": "market",
            "entry_price_suggested": 0.0,
            "stop_loss_suggested": None,
            "take_profit_suggested": None,
            "time_horizon": "swing",
            "confidence_note": "No live price available; wait for refreshed quote before entry.",
        }
    volatility_factor = _to_float(item.get("decision_breakdown", {}).get("values", {}).get("volatility_factor"), 0.0)
    base_stop_pct = 0.02 + min(0.015, max(0.0, volatility_factor * 0.01))
    base_stop_pct = min(0.035, max(0.015, base_stop_pct))

    stop_loss = item.get("stop_loss")
    stop_loss = _to_float(stop_loss, 0.0) if stop_loss is not None else 0.0
    if stop_loss <= 0:
        stop_loss = round(price * (1.0 - base_stop_pct), 4)

    risk = max(price - stop_loss, price * 0.01)
    take_profit = item.get("take_profit")
    take_profit = _to_float(take_profit, 0.0) if take_profit is not None else 0.0
    if take_profit <= 0:
        rr = 1.8 if _to_float(item.get("predicted_win_probability"), 0.0) >= 0.65 else 1.5
        take_profit = round(price + (risk * rr), 4)

    intraday_score = _to_float(item.get("intraday_score"), 0.0)
    time_horizon = "intraday" if intraday_score >= 70 else "swing"
    entry_type = "market" if str(item.get("quote_quality") or "live").lower() == "live" else "limit_suggested"
    consensus = _to_float(item.get("consensus_strength"), 0.0)
    prob = _to_float(item.get("predicted_win_probability"), 0.0) * 100.0
    confidence_note = (
        f"Plan based on consensus {consensus:.1f}, win probability {prob:.1f}%, "
        f"and volatility-aware stop at {base_stop_pct*100:.1f}%."
    )
    return {
        "entry_type": entry_type,
        "entry_price_suggested": round(price, 4),
        "stop_loss_suggested": round(stop_loss, 4),
        "take_profit_suggested": round(take_profit, 4),
        "time_horizon": time_horizon,
        "confidence_note": confidence_note,
    }


def _fill_sort_key(item):
    return (
        -_to_float(item.get("adaptive_buy_score"), 0.0),
        -_to_float(item.get("predicted_win_probability"), 0.0),
        -_to_float(item.get("persona_weighted_grade", item.get("grade_percent")), 0.0),
        -_to_float(item.get("consensus_strength"), 0.0),
        _to_float(item.get("persona_disagreement_index"), 100.0),
    )


def _top_buys_from_rows(rows):
    return _top_buys_from_rows_with_config(
        rows=rows,
        buy_mode="balanced",
        min_probability=TOP_BUY_MIN_PROBABILITY,
        max_disagreement=TOP_BUY_MAX_DISAGREEMENT,
    )


def _resolve_buy_mode_config(raw_mode):
    mode = str(raw_mode or "balanced").strip().lower()
    if mode not in BUY_MODE_CONFIG:
        mode = "balanced"
    cfg = BUY_MODE_CONFIG.get(mode, BUY_MODE_CONFIG["balanced"])
    return {
        "buy_mode": mode,
        "min_probability": float(cfg.get("min_probability", TOP_BUY_MIN_PROBABILITY)),
        "max_disagreement": float(cfg.get("max_disagreement", TOP_BUY_MAX_DISAGREEMENT)),
    }


