@router.get("/api/chart/{symbol}")
def chart(symbol: str):
    cached = _cache_get("candles", f"legacy::{symbol.upper()}::5", CANDLE_TTL_SECONDS)
    if cached:
        return cached
    return candles(symbol=symbol, asset_type="stock", resolution="5", lookback_days=30)


@router.get("/api/candles")
def candles(
    symbol: str = Query("AAPL"),
    asset_type: str = Query("stock"),
    resolution: str = Query("15"),
    lookback_days: int = Query(30, ge=1, le=365),
    from_ts: int | None = Query(None, alias="from"),
    to_ts: int | None = Query(None, alias="to"),
):
    key = _finnhub_key()
    alpaca_key, alpaca_secret, alpaca_base, _alpaca_trading_base = _alpaca_creds()
    safe_symbol = str(symbol or "AAPL").upper().strip()
    res = _normalize_resolution(resolution)
    asset = str(asset_type or "stock").lower().strip()

    now_ts = int(time.time())
    end_ts = int(to_ts) if isinstance(to_ts, int) else now_ts
    start_ts = int(from_ts) if isinstance(from_ts, int) else end_ts - (int(lookback_days) * 86400)
    cache_key = f"{asset}:{safe_symbol}:{res}:{start_ts}:{end_ts}"
    cached = _cache_get("candles", cache_key, _candle_ttl_seconds(res))
    if cached:
        return cached
    provider = "FINNHUB"
    managed_cached = get_cache("timeframe", provider, safe_symbol, "candles", resolution=res, ttl=300)
    if managed_cached and isinstance(managed_cached.get("candles"), list) and managed_cached.get("candles"):
        managed_cached.update({"symbol": safe_symbol, "resolution": res, "from": start_ts, "to": end_ts, "source": "finnhub"})
        return managed_cached

    def _alpaca_candles_fallback(reason):
        if asset != "stock":
            return None
        if not (alpaca_key and alpaca_secret):
            return None
        provider_local = "ALPACA"
        if not get_call_permission(provider_local, cost=1):
            return None
        try:
            start_iso = datetime.fromtimestamp(start_ts, UTC).isoformat().replace("+00:00", "Z")
            end_iso = datetime.fromtimestamp(end_ts, UTC).isoformat().replace("+00:00", "Z")
            resp = requests.get(
                f"{alpaca_base}/v2/stocks/{safe_symbol}/bars",
                params={
                    "timeframe": _alpaca_timeframe(res),
                    "start": start_iso,
                    "end": end_iso,
                    "adjustment": "raw",
                    "limit": 10000,
                    "feed": "iex",
                },
                headers={
                    "APCA-API-KEY-ID": alpaca_key,
                    "APCA-API-SECRET-KEY": alpaca_secret,
                },
                timeout=10,
            )
            record_call(provider_local, cost=1)
            if resp.status_code != 200:
                if resp.status_code in (429, 402):
                    record_rate_limit(provider_local, http_status=resp.status_code)
                else:
                    record_error(provider_local)
                return None
            data = resp.json()
            bars = data.get("bars", []) if isinstance(data, dict) else []
            candles_out = []
            for row in bars or []:
                try:
                    t = row.get("t")
                    ts_val = int(datetime.fromisoformat(str(t).replace("Z", "+00:00")).timestamp()) if t else None
                    candles_out.append(
                        {
                            "t": ts_val,
                            "o": float(row.get("o")),
                            "h": float(row.get("h")),
                            "l": float(row.get("l")),
                            "c": float(row.get("c")),
                            "v": float(row.get("v", 0.0)),
                        }
                    )
                except Exception:
                    continue
            if not candles_out:
                return None
            payload = {
                "symbol": safe_symbol,
                "resolution": res,
                "from": start_ts,
                "to": end_ts,
                "candles": candles_out,
                "source": "alpaca",
                "cached": False,
                "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
                "feed_degraded_reason": str(reason or "finnhub_unavailable"),
            }
            _cache_set("candles", cache_key, payload)
            set_cache("timeframe", provider_local, safe_symbol, "candles", payload, resolution=res)
            return payload
        except Exception:
            record_error(provider_local)
            return None

    if not _allow_timeframe_fetch(safe_symbol, asset):
        fallback = get_cache("timeframe", provider, safe_symbol, "candles", resolution=res, ttl=900)
        if fallback:
            fallback.update({"symbol": safe_symbol, "resolution": res, "from": start_ts, "to": end_ts, "source": "finnhub"})
            fallback["feed_degraded_reason"] = "timeframe_throttled"
            return fallback
        return {
            "symbol": safe_symbol,
            "resolution": res,
            "from": start_ts,
            "to": end_ts,
            "candles": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": "timeframe_throttled",
            "feed_degraded_reason": "timeframe_throttled",
        }

    if not key:
        fallback = _alpaca_candles_fallback("finnhub_key_missing")
        if fallback:
            return fallback
        return {
            "symbol": safe_symbol,
            "resolution": res,
            "from": start_ts,
            "to": end_ts,
            "candles": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": "finnhub_key_missing",
        }
    if not get_call_permission(provider, cost=1):
        fallback = _alpaca_candles_fallback("finnhub_rate_limit_exhausted")
        if fallback:
            return fallback
        fallback = get_cache("timeframe", provider, safe_symbol, "candles", resolution=res, ttl=900)
        if fallback:
            fallback.update({"symbol": safe_symbol, "resolution": res, "from": start_ts, "to": end_ts, "source": "finnhub"})
            fallback["feed_degraded_reason"] = "rate_limit_exhausted"
            return fallback
        return {
            "symbol": safe_symbol,
            "resolution": res,
            "from": start_ts,
            "to": end_ts,
            "candles": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": "rate_limit_exhausted",
            "feed_degraded_reason": "rate_limit_exhausted",
        }

    query_symbol = safe_symbol
    endpoint = "stock/candle"
    if asset == "crypto":
        query_symbol = _normalize_crypto_symbol(safe_symbol)
        endpoint = "crypto/candle"

    try:
        resp = requests.get(
            f"https://finnhub.io/api/v1/{endpoint}",
            params={
                "symbol": query_symbol,
                "resolution": res,
                "from": start_ts,
                "to": end_ts,
                "token": key,
            },
            timeout=10,
        )
        record_call(provider, cost=1)
        if resp.status_code != 200:
            if resp.status_code == 429:
                record_rate_limit(provider)
            else:
                record_error(provider)
            fallback = _alpaca_candles_fallback(f"finnhub_http_{resp.status_code}")
            if fallback:
                return fallback
            return {
                "symbol": safe_symbol,
                "resolution": res,
                "from": start_ts,
                "to": end_ts,
                "candles": [],
                "source": "finnhub",
                "cached": False,
                "data_unavailable": f"http_{resp.status_code}",
            }
        data = resp.json()
        if data.get("s") != "ok":
            record_error(provider)
            fallback = _alpaca_candles_fallback(str(data.get("s") or "finnhub_no_data"))
            if fallback:
                return fallback
            return {
                "symbol": safe_symbol,
                "resolution": res,
                "from": start_ts,
                "to": end_ts,
                "candles": [],
                "source": "finnhub",
                "cached": False,
                "data_unavailable": data.get("s") or "no_data",
            }

        ts = data.get("t", [])
        opens = data.get("o", [])
        highs = data.get("h", [])
        lows = data.get("l", [])
        closes = data.get("c", [])
        vols = data.get("v", [])
        count = min(len(ts), len(opens), len(highs), len(lows), len(closes))
        candles_out = []
        for i in range(count):
            try:
                candles_out.append({
                    "t": int(ts[i]),
                    "o": float(opens[i]),
                    "h": float(highs[i]),
                    "l": float(lows[i]),
                    "c": float(closes[i]),
                    "v": float(vols[i]) if i < len(vols) else 0.0,
                })
            except Exception:
                continue

        payload = {
            "symbol": safe_symbol,
            "resolution": res,
            "from": start_ts,
            "to": end_ts,
            "candles": candles_out,
            "source": "finnhub",
            "cached": False,
            "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        }
        _cache_set("candles", cache_key, payload)
        set_cache("timeframe", provider, safe_symbol, "candles", payload, resolution=res)
        return payload
    except Exception as e:
        record_error(provider)
        fallback = _alpaca_candles_fallback("finnhub_request_error")
        if fallback:
            return fallback
        fallback = get_cache("timeframe", provider, safe_symbol, "candles", resolution=res, ttl=900)
        if fallback:
            fallback.update({"symbol": safe_symbol, "resolution": res, "from": start_ts, "to": end_ts, "source": "finnhub"})
            fallback["feed_degraded_reason"] = "request_error"
            return fallback
        return {
            "symbol": safe_symbol,
            "resolution": res,
            "from": start_ts,
            "to": end_ts,
            "candles": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": str(e),
            "feed_degraded_reason": "request_error",
        }


@router.get("/api/news")
def news(symbol: str = Query("AAPL"), limit: int = Query(10, ge=1, le=50)):
    key = _finnhub_key()
    provider = "FINNHUB"
    safe_symbol = str(symbol or "AAPL").upper().strip()
    cache_key = f"{safe_symbol}:{limit}"
    cached = _cache_get("news", cache_key, NEWS_TTL_SECONDS)
    if cached:
        return cached
    managed_cached = get_cache("news", provider, safe_symbol, "company-news", resolution=str(limit), ttl=600)
    if managed_cached:
        managed_cached.update({"symbol": safe_symbol, "source": "finnhub"})
        return managed_cached

    if not key:
        return {
            "symbol": safe_symbol,
            "items": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": "finnhub_key_missing",
        }
    if not get_call_permission(provider, cost=1):
        fallback = get_cache("news", provider, safe_symbol, "company-news", resolution=str(limit), ttl=1200)
        if fallback:
            fallback.update({"symbol": safe_symbol, "source": "finnhub", "feed_degraded_reason": "rate_limit_exhausted"})
            return fallback
        return {
            "symbol": safe_symbol,
            "items": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": "rate_limit_exhausted",
            "feed_degraded_reason": "rate_limit_exhausted",
        }

    to_date = datetime.now(UTC).date()
    from_date = to_date - timedelta(days=14)
    try:
        resp = requests.get(
            "https://finnhub.io/api/v1/company-news",
            params={
                "symbol": safe_symbol,
                "from": from_date.isoformat(),
                "to": to_date.isoformat(),
                "token": key,
            },
            timeout=10,
        )
        record_call(provider, cost=1)
        if resp.status_code != 200:
            if resp.status_code == 429:
                record_rate_limit(provider)
            else:
                record_error(provider)
            return {
                "symbol": safe_symbol,
                "items": [],
                "source": "finnhub",
                "cached": False,
                "data_unavailable": f"http_{resp.status_code}",
            }
        data = resp.json()
        if not isinstance(data, list):
            record_error(provider)
            return {
                "symbol": safe_symbol,
                "items": [],
                "source": "finnhub",
                "cached": False,
                "data_unavailable": "unexpected_payload",
            }
        items = []
        for row in data[:limit]:
            if not isinstance(row, dict):
                continue
            items.append({
                "headline": row.get("headline"),
                "summary": row.get("summary"),
                "url": row.get("url"),
                "source": row.get("source"),
                "datetime": row.get("datetime"),
            })
        payload = {
            "symbol": safe_symbol,
            "items": items,
            "source": "finnhub",
            "cached": False,
            "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        }
        if not items:
            payload["data_unavailable"] = "no_news_items"
        _cache_set("news", cache_key, payload)
        set_cache("news", provider, safe_symbol, "company-news", payload, resolution=str(limit))
        return payload
    except Exception as e:
        record_error(provider)
        fallback = get_cache("news", provider, safe_symbol, "company-news", resolution=str(limit), ttl=1200)
        if fallback:
            fallback.update({"symbol": safe_symbol, "source": "finnhub", "feed_degraded_reason": "request_error"})
            return fallback
        return {
            "symbol": safe_symbol,
            "items": [],
            "source": "finnhub",
            "cached": False,
            "data_unavailable": str(e),
            "feed_degraded_reason": "request_error",
        }


@router.get("/api/top_signals")
def top_signals():
    p = os.path.join(STATE, "learning_metrics.json")
    if not os.path.exists(p):
        return {"error": "no data"}
    with open(p, "r") as f:
        data = json.load(f)

    if isinstance(data, list):
        signals = data
    elif isinstance(data, dict):
        signals = data.get("signals", [])
    else:
        signals = []

    for s in signals:
        s.setdefault("prediction_price", None)
        s.setdefault("prediction_percent", None)
        s.setdefault("stop_loss", None)
        s.setdefault("stop_loss_percent", None)

    stocks = [s for s in signals if s.get("asset_type") == "stock"]
    cryptos = [s for s in signals if s.get("asset_type") == "crypto"]
    key_fn = lambda s: s.get("brain_grade", 0) * 0.6 + s.get("persona_grade", 0) * 0.4
    return {
        "stocks": sorted(stocks, key=key_fn, reverse=True)[:6],
        "cryptos": sorted(cryptos, key=key_fn, reverse=True)[:6],
        "count": len(signals),
    }


@router.get("/api/rankings")
def rankings():
    global _PROVIDER_HEALTH_PRIME_TS
    cached = RANKINGS_ENDPOINT_CACHE.get("stocks", {})
    if cached.get("payload") and (time.time() - float(cached.get("ts", 0.0))) <= RANKINGS_ENDPOINT_TTL_SECONDS:
        _PERF_COUNTERS["rankings_cache_hit_count"] = int(_PERF_COUNTERS.get("rankings_cache_hit_count", 0)) + 1
        return list(cached.get("payload", []))
    build_lock = _RANKINGS_BUILD_LOCK["stocks"]
    have_lock = build_lock.acquire(blocking=False)
    if not have_lock:
        # If a build is already in-flight, return stale ranking payload instead of timing out.
        if cached.get("payload") and (time.time() - float(cached.get("ts", 0.0))) <= _RANKINGS_STALE_TTL_SECONDS:
            _PERF_COUNTERS["rankings_cache_hit_count"] = int(_PERF_COUNTERS.get("rankings_cache_hit_count", 0)) + 1
            return list(cached.get("payload", []))
        last_rows = LAST_RANKINGS.get("stocks", []) or []
        if last_rows:
            return [dict(r) for r in last_rows if isinstance(r, dict)]
        # Cold-cache contention path: allow the in-flight builder extra time to seed rows.
        waited = _wait_for_rank_rows("stocks", timeout_seconds=8.0, poll_seconds=0.2)
        if waited:
            return waited
        have_lock = build_lock.acquire(timeout=10.0)
        if not have_lock:
            # Last chance: return any stale in-memory rows if present.
            last_rows = LAST_RANKINGS.get("stocks", []) or []
            if last_rows:
                return [dict(r) for r in last_rows if isinstance(r, dict)]
            return []
    # Double-check cache once lock is acquired.
    cached = RANKINGS_ENDPOINT_CACHE.get("stocks", {})
    if cached.get("payload") and (time.time() - float(cached.get("ts", 0.0))) <= RANKINGS_ENDPOINT_TTL_SECONDS:
        if have_lock:
            build_lock.release()
        _PERF_COUNTERS["rankings_cache_hit_count"] = int(_PERF_COUNTERS.get("rankings_cache_hit_count", 0)) + 1
        return list(cached.get("payload", []))
    # Prime provider health snapshot with cooldown to avoid repeating expensive calls each cycle.
    now = time.time()
    if (now - float(_PROVIDER_HEALTH_PRIME_TS)) >= _PROVIDER_HEALTH_PRIME_COOLDOWN_SECONDS:
        try:
            GUARDIAN_API.provider_status(symbol="AAPL")
            _PROVIDER_HEALTH_PRIME_TS = now
        except Exception:
            pass
    try:
        learning_snapshot = _get_enriched_learning_insights_cached()
        universe_symbols = _load_universe_symbols()
        funnel = _build_funnel_candidates(
            universe_symbols,
            buy_mode=str(_FUNNEL_RUNTIME.get("active_buy_mode", os.getenv("ASTRA_DEFAULT_BUY_MODE", "balanced"))),
        )
        # Universe-first scoring: always score the full configured universe each cycle.
        # Funnel output remains additive metadata/weighting, not a pre-scoring hard gate.
        candidate_symbols = funnel.get("candidate_symbols") or universe_symbols
        data = fetch_live_data(symbols=universe_symbols)
        stocks = [
            d for d in data
            if d.get("symbol") and d["symbol"].upper() not in ["BTC", "ETH", "SOL", "XRP", "DOGE", "BNB"]
        ]
        scored_map = funnel.get("scores_by_symbol", {})
        stocks = [_ensure_persona_fields(s, funnel_hint=scored_map.get(str(s.get("symbol", "")).upper())) for s in stocks]
        ranked = _prioritize_rankings(stocks, learning_snapshot=learning_snapshot)
        ranked = PORTFOLIO_INTEL.apply(ranked, asset_type="stocks")
        ranked = _prioritize_rankings(ranked, learning_snapshot=learning_snapshot)
        output = []
        for item in ranked:
            enriched = dict(item)
            enriched["action"] = item.get("action") or item.get("prediction")
            enriched = _ensure_persona_fields(enriched, funnel_hint=scored_map.get(str(enriched.get("symbol", "")).upper()))
            if "funnel_score_total" not in enriched:
                enriched["funnel_score_total"] = float(
                    (enriched.get("persona_consensus_summary", {}) or {}).get("funnel_score_total")
                    or enriched.get("persona_weighted_grade", 0.0)
                )
            output.append(enriched)
        output = PORTFOLIO_RISK_ENGINE.enrich(
            output,
            asset_type="stocks",
            companion_rows=LAST_RANKINGS.get("crypto", []),
        )
        output = PREDICTIVE_MODEL.annotate_rows(output)
        output = REGIME_ENGINE.annotate_rows(output)
        cap_map = dict(_UNIVERSE_RUNTIME.get("cap_map") or {})
        for idx, row in enumerate(output):
            sym = str(row.get("symbol", "")).upper()
            row["market_cap_category"] = cap_map.get(sym, "unknown")
            output[idx] = _ensure_persona_fields(row)

        _update_signal_performance(output)
        LIVE_SIGNAL_LOG.process_rankings(output)
        # Avoid empty-result cache poisoning: keep prior non-empty rankings snapshot.
        if output:
            _update_last_rankings("stocks", output)
            RANKINGS_ENDPOINT_CACHE["stocks"] = {"ts": time.time(), "payload": list(output)}
        _PERF_COUNTERS["rankings_build_count"] = int(_PERF_COUNTERS.get("rankings_build_count", 0)) + 1
        _FUNNEL_RUNTIME.update(
            {
                "funnel_stage0_universe": int(len(universe_symbols or [])),
                "funnel_stage1_quoted": int(funnel.get("quoted_count", 0)),
                "funnel_stage2_scored": int(funnel.get("rows_evaluated", len(universe_symbols or []))),
                "funnel_stage3_persona_filtered": int(funnel.get("candidate_count", len(candidate_symbols))),
                "funnel_stage4_top6_selected": int(min(6, len(output))),
                "funnel_candidate_count": int(funnel.get("candidate_count", len(candidate_symbols))),
                "final_ranked_count": len(output),
                "universe_cap_distribution": funnel.get("universe_cap_distribution", {"large": 0, "mid": 0, "small": 0, "unknown": 0}),
                "quoted_cap_distribution": funnel.get("quoted_cap_distribution", {"large": 0, "mid": 0, "small": 0, "unknown": 0}),
                "scored_cap_distribution": funnel.get("scored_cap_distribution", {"large": 0, "mid": 0, "small": 0, "unknown": 0}),
                "candidate_cap_distribution": funnel.get("candidate_cap_distribution", {"large": 0, "mid": 0, "small": 0, "unknown": 0}),
                "final_cap_distribution": _cap_distribution([r.get("symbol") for r in output], cap_map),
                "candidate_symbols": list(candidate_symbols[:80]),
                "sample_skip_reasons": dict(get_ranking_snapshot_meta().get("skip_reasons_counts", {})),
                "adaptive_weights_applied": funnel.get("adaptive_weights_applied", {}),
                "last_updated_utc": _now_utc_iso(),
            }
        )
        return output
    finally:
        if have_lock:
            build_lock.release()


