        position_survival_score = round(
            max(0.0, min(100.0, (candidate_to_position_quality_score * 0.6) + (100.0 - promoted_failure_score) * 0.4)),
            2,
        )
        premature_exit_score = round(max(0.0, min(100.0, 100.0 - exit_timing_quality_score)), 2)
        failed_buy_detection_score = round(max(0.0, min(100.0, promoted_failure_score)), 2)

        prev_buy_conversion_score = _to_float(_FUNNEL_RUNTIME.get("last_buy_conversion_score"), buy_conversion_score)
        prev_overblocking_score = _to_float(_FUNNEL_RUNTIME.get("last_overblocking_score"), overblocking_pressure_score)
        prev_sell_signal_accuracy_score = _to_float(_FUNNEL_RUNTIME.get("last_sell_signal_accuracy_score"), sell_alert_accuracy_score)
        buy_conversion_trend = "up" if buy_conversion_score > prev_buy_conversion_score + 1.0 else ("down" if buy_conversion_score < prev_buy_conversion_score - 1.0 else "flat")
        overblocking_trend = "down" if overblocking_pressure_score < prev_overblocking_score - 1.0 else ("up" if overblocking_pressure_score > prev_overblocking_score + 1.0 else "flat")
        sell_signal_accuracy_trend = "up" if sell_alert_accuracy_score > prev_sell_signal_accuracy_score + 1.0 else ("down" if sell_alert_accuracy_score < prev_sell_signal_accuracy_score - 1.0 else "flat")

        hero_conf_scores = [_to_float((r or {}).get("confidence"), 0.0) for r in hero_rows if isinstance(r, dict)]
        hero_high_conf_share = (sum(1 for c in hero_conf_scores if c >= 70.0) / max(1, len(hero_conf_scores))) * 100.0
        confidence_bucket_separation_score = round(max(0.0, min(100.0, 50.0 + (hero_high_conf_share - (100.0 - hero_high_conf_share)) * 0.5)), 2)
        recalibrated_confidence_score = round(max(0.0, min(100.0, (hero_high_conf_share * 0.5) + (promoted_candidate_rate * 0.5))), 2)
