        confidence_understatement_score = round(max(0.0, min(100.0, false_negative_total * 5.0)), 2)
        high_confidence_predictiveness_score = round(max(0.0, min(100.0, promoted_candidate_rate)), 2)
        elite_confidence_quality_score = round(max(0.0, min(100.0, (recalibrated_confidence_score * 0.6) + (100.0 - confidence_overstatement_score) * 0.4)), 2)

        elite_setup_filter_score = round(max(0.0, min(100.0, top_pick_action_quality_score)), 2)
