@router.post("/api/positions/open")
def open_position(payload: dict = Body(...)):
    data = payload if isinstance(payload, dict) else {}
    symbol = str(data.get("symbol") or "").upper().strip()
    if not symbol:
        return {"ok": False, "error": "symbol_required"}
    asset_type = _normalize_asset_type(data.get("asset_type") or _asset_type_for_symbol(symbol))
    _ensure_latest_rankings()
    row = _find_latest_row(symbol, asset_type=asset_type)

    entry_price = data.get("entry_price")
    if entry_price is None and isinstance(row, dict):
        entry_price = row.get("price")
    try:
        entry_price = float(entry_price)
    except (TypeError, ValueError):
        return {"ok": False, "error": "entry_price_unavailable"}
    if entry_price <= 0:
        return {"ok": False, "error": "entry_price_invalid"}

    ranking_meta_payload = ranking_meta()
    quote_batch_id = (
        ranking_meta_payload.get("crypto_quote_batch_id")
        if asset_type == "crypto"
        else ranking_meta_payload.get("quote_batch_id")
    )
    snapshot_fields = {
        "predicted_win_probability": (row or {}).get("predicted_win_probability"),
        "persona_weighted_grade": (row or {}).get("persona_weighted_grade", (row or {}).get("grade_percent")),
        "consensus_strength": (row or {}).get("consensus_strength"),
        "persona_disagreement_index": (row or {}).get("persona_disagreement_index"),
        "regime_context": (row or {}).get("regime_context", (row or {}).get("regime")),
        "quote_batch_id": quote_batch_id,
        "latest_price": (row or {}).get("price"),
        "quote_quality": (row or {}).get("quote_quality", "unknown"),
        "data_unavailable_reason": (row or {}).get("data_unavailable_reason", ""),
        "last_snapshot_timestamp": (row or {}).get("timestamp", ""),
    }
    result = POSITION_TRACKER.open_position(
        symbol=symbol,
        asset_type=asset_type,
        entry_price=entry_price,
        quantity=data.get("quantity"),
        notes=data.get("notes"),
        snapshot_fields=snapshot_fields,
        mode=data.get("mode") or "intraday",
    )
    out = dict(result)
    if out.get("ok"):
        try:
            create_lifecycle_record(
                {
                    "lifecycle_id": str((out.get("position") or {}).get("position_id") or out.get("position_id") or ""),
                    "symbol": symbol,
                    "asset_type": asset_type,
                    "signal_timestamp": str((row or {}).get("timestamp") or datetime.now(UTC).isoformat().replace("+00:00", "Z")),
                    "release_status": str((row or {}).get("release_status") or (row or {}).get("paper_ready_status") or "manual"),
                    "entry_timestamp": str((out.get("position") or {}).get("entry_timestamp") or datetime.now(UTC).isoformat().replace("+00:00", "Z")),
                    "entry_price": entry_price,
                    "current_price": _to_float((row or {}).get("price"), entry_price),
                    "confidence": _to_float((row or {}).get("confidence"), _to_float((row or {}).get("predicted_win_probability"), 0.0)),
                    "grade": _to_float((row or {}).get("grade_percent"), _to_float((row or {}).get("persona_weighted_grade"), 0.0)),
                    "entry_quality_score": _to_float((row or {}).get("entry_quality_score"), 0.0),
                    "entry_quality_band": str((row or {}).get("entry_quality_band") or "unknown"),
                    "trade_archetype": str((row or {}).get("setup_type") or "unknown"),
                    "catalyst_context": str((row or {}).get("regime_context") or (row or {}).get("market_regime") or ""),
                    "source_endpoint": "/api/positions/open",
                    "lifecycle_stage": "entry",
                }
            )
        except Exception:
            pass
    out["symbol"] = symbol
    out["asset_type"] = asset_type
    out["entry_price"] = round(entry_price, 4)
    out["snapshot_found"] = bool(row)
    out["last_updated_utc"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
    return out


@router.post("/api/positions/close")
def close_position(payload: dict = Body(...)):
    data = payload if isinstance(payload, dict) else {}
    identifier = data.get("position_id") or data.get("symbol")
    if not identifier:
        return {"ok": False, "error": "position_id_or_symbol_required"}
    _ensure_latest_rankings()

    close_probe = POSITION_TRACKER._get_open_by_identifier(identifier)
    if close_probe is None:
        return {"ok": False, "error": "position_not_found"}

    row = _find_latest_row(close_probe.get("symbol"), asset_type=close_probe.get("asset_type"))
    exit_price = data.get("exit_price")
    if exit_price is None and isinstance(row, dict):
        exit_price = row.get("price")
    if exit_price is None:
        exit_price = close_probe.get("entry_price")
    try:
        exit_price = float(exit_price)
    except (TypeError, ValueError):
        return {"ok": False, "error": "exit_price_invalid"}
    if exit_price <= 0:
        return {"ok": False, "error": "exit_price_invalid"}

    closed = POSITION_TRACKER.close_position(
        identifier=identifier,
        exit_price=exit_price,
        exit_timestamp=data.get("exit_timestamp"),
        exit_reason_manual=data.get("exit_reason_manual"),
    )
    if not closed.get("ok"):
        return closed
    try:
        closed_row = closed.get("closed") if isinstance(closed.get("closed"), dict) else {}
        entry_px = _to_float(closed_row.get("entry_price"), _to_float(close_probe.get("entry_price"), 0.0))
        pnl_pct = 0.0
        if entry_px > 0.0:
            pnl_pct = ((_to_float(exit_price, 0.0) - entry_px) / entry_px) * 100.0
        close_lifecycle_record(
            str(closed_row.get("position_id") or close_probe.get("position_id") or identifier),
            {
                "symbol": str(closed_row.get("symbol") or close_probe.get("symbol") or ""),
                "asset_type": str(closed_row.get("asset_type") or close_probe.get("asset_type") or "stock"),
                "signal_timestamp": str(closed_row.get("entry_timestamp") or close_probe.get("entry_timestamp") or ""),
                "entry_timestamp": str(closed_row.get("entry_timestamp") or close_probe.get("entry_timestamp") or ""),
                "entry_price": entry_px,
                "current_price": _to_float(exit_price, 0.0),
                "exit_timestamp": str(closed_row.get("exit_timestamp") or data.get("exit_timestamp") or datetime.now(UTC).isoformat().replace("+00:00", "Z")),
                "exit_price": _to_float(exit_price, 0.0),
                "pnl_pct": pnl_pct,
                "max_favorable_excursion_pct": _to_float(closed_row.get("peak_unrealized_pnl_percent"), max(pnl_pct, 0.0)),
                "max_adverse_excursion_pct": _to_float(closed_row.get("drawdown_after_peak_percent"), min(pnl_pct, 0.0)),
                "confidence": _to_float(closed_row.get("entry_predicted_win_probability"), 0.0),
                "grade": _to_float(closed_row.get("entry_persona_weighted_grade"), 0.0),
                "entry_quality_score": _to_float(closed_row.get("entry_entry_quality_score"), _to_float(closed_row.get("entry_quality_score"), 0.0)),
                "entry_quality_band": str(closed_row.get("entry_entry_quality_band") or closed_row.get("entry_quality_band") or "unknown"),
                "trade_archetype": str(closed_row.get("entry_setup_type") or closed_row.get("detected_setup_type") or "unknown"),
                "catalyst_context": str(closed_row.get("entry_regime_context") or closed_row.get("market_regime") or ""),
                "exit_reason": str(data.get("exit_reason_manual") or "manual_close"),
                "outcome_label": "winner" if pnl_pct > 0 else ("loser" if pnl_pct < 0 else "flat"),
                "source_endpoint": "/api/positions/close",
            },
        )
    except Exception:
        pass

    warning = None
    try:
        c = closed.get("closed", {}) if isinstance(closed.get("closed"), dict) else {}
        entry_price = float(c.get("entry_price") or 0.0)
        ret = 0.0
        if entry_price > 0:
            ret = round(((exit_price - entry_price) / entry_price) * 100.0, 2)
        valid_label = int(bool(entry_price > 0 and exit_price > 0 and abs(ret) > 0.0001))
        invalid_reason = ""
        if not valid_label:
            if not entry_price or not exit_price:
                invalid_reason = "missing_price"
            elif abs(ret) <= 0.0001:
                invalid_reason = "unchanged_or_near_zero"
            else:
                invalid_reason = "invalid_label"
        TRADE_INTEL.record_trade({
            "trade_id": str(c.get("position_id") or ""),
            "symbol": c.get("symbol"),
            "asset_type": "crypto" if str(c.get("asset_type")) == "crypto" else "stock",
            "mode": c.get("mode") or "intraday",
            "entry_timestamp": c.get("entry_timestamp"),
            "entry_price": c.get("entry_price"),
            "entry_predicted_probability": c.get("entry_predicted_win_probability"),
            "entry_persona_grade": c.get("entry_persona_weighted_grade"),
            "entry_regime": c.get("entry_regime_context"),
            "market_regime": c.get("entry_regime_context"),
            "entry_persona_fit_summary": c.get("persona_best_fit") or (row or {}).get("persona_best_fit") or "unknown",
            "entry_market_cap_category": c.get("market_cap_category") or (row or {}).get("market_cap_category") or "unknown",
            "entry_sector": c.get("sector") or (row or {}).get("sector") or "unknown",
            "entry_signal_tags": ["manual_position_close"],
            "persona_scores_entry": (
                c.get("persona_grades") if isinstance(c.get("persona_grades"), dict)
                else ((row or {}).get("persona_grades") if isinstance((row or {}).get("persona_grades"), dict) else {})
            ),
            "final_consensus_persona_score": _to_float(
                c.get("entry_consensus_strength"),
                _to_float((row or {}).get("consensus_strength"), 0.0),
            ),
            "buy_mode": str(data.get("buy_mode") or c.get("buy_mode") or (row or {}).get("buy_mode") or "balanced"),
            "entry_consensus_strength": c.get("entry_consensus_strength"),
            "detected_setup_type": c.get("entry_detected_setup_type") or c.get("detected_setup_type") or (row or {}).get("detected_setup_type") or c.get("entry_setup_type") or "unknown",
            "setup_candidate_realness": c.get("entry_setup_candidate_realness") or c.get("setup_candidate_realness") or (row or {}).get("setup_candidate_realness") or "unknown",
            "setup_detection_score": _to_float(
                c.get("entry_setup_detection_score"),
                _to_float(c.get("setup_detection_score"), _to_float((row or {}).get("setup_detection_score"), 0.0)),
            ),
            "setup_detection_band": c.get("entry_setup_detection_band") or c.get("setup_detection_band") or (row or {}).get("setup_detection_band") or "unknown",
            "setup_detection_confidence": _to_float(
                c.get("entry_setup_detection_confidence"),
                _to_float(c.get("setup_detection_confidence"), _to_float((row or {}).get("setup_detection_confidence"), 0.0)),
            ),
            "setup_detection_evidence_label": c.get("entry_setup_detection_evidence_label") or c.get("setup_detection_evidence_label") or (row or {}).get("setup_detection_evidence_label") or "unknown",
            "conviction_tier": c.get("entry_conviction_tier") or c.get("conviction_tier") or (row or {}).get("conviction_tier") or "",
            "entry_quality_score": _to_float(
                c.get("entry_entry_quality_score"),
                _to_float(c.get("entry_quality_score"), _to_float((row or {}).get("entry_quality_score"), 0.0)),
            ),
            "entry_quality_band": c.get("entry_entry_quality_band") or c.get("entry_quality_band") or (row or {}).get("entry_quality_band") or "unknown",
            "entry_quality_candidate_class": c.get("entry_entry_quality_candidate_class") or c.get("entry_quality_candidate_class") or (row or {}).get("entry_quality_candidate_class") or "unknown",
            "entry_quality_primary_driver": c.get("entry_entry_quality_primary_driver") or c.get("entry_quality_primary_driver") or (row or {}).get("entry_quality_primary_driver") or "unknown",
            "entry_quality_primary_penalty": c.get("entry_entry_quality_primary_penalty") or c.get("entry_quality_primary_penalty") or (row or {}).get("entry_quality_primary_penalty") or "unknown",
            "entry_quality_evidence_label": c.get("entry_entry_quality_evidence_label") or c.get("entry_quality_evidence_label") or (row or {}).get("entry_quality_evidence_label") or "unknown",
            "exit_timestamp": c.get("last_update_ts"),
            "exit_price": exit_price,
            "exit_reason": data.get("exit_reason_manual") or "manual_close",
            "holding_period": c.get("duration_minutes"),
            "return_percent": ret,
            "profit_loss_percent": ret,
            "friction_adjusted_return": ret,
            "valid_label": valid_label,
            "invalid_reason": invalid_reason,
        })
    except Exception as e:
        warning = f"trade_intelligence_record_failed: {e}"

    payload_out = dict(closed)
    if warning:
        payload_out["warning"] = warning
    payload_out["last_updated_utc"] = datetime.now(UTC).isoformat().replace("+00:00", "Z")
    return payload_out


