@router.get("/api/positions")
def positions(asset_type: str | None = Query(None)):
    try:
        compact = _mobile_runtime_compaction_snapshot(force=False, include_closed_orders=True)
        # If Alpaca paper reconciliation is available, broker positions are the display truth.
        # Avoid the heavier internal enrichment path for compact mobile/dashboard views.
        if bool(compact.get("mobile_runtime_compaction_active")) and bool(compact.get("broker_positions_fetch_ok")):
            base_response = {
                "count": int(_to_float(compact.get("display_active_positions_count"), 0.0)),
                "positions": list(compact.get("desktop_positions_preview") or compact.get("true_broker_positions_preview") or []),
                "position_lifecycle_intelligence": {
                    "total_open_positions": int(_to_float(compact.get("display_active_positions_count"), 0.0)),
                    "broker_confirmed_display": True,
                    "internal_workflow_rows_hidden": int(_to_float(compact.get("stale_rows_hidden_count"), 0.0)),
                },
                "position_sync_v1": {
                    "open_position_count": int(_to_float(compact.get("display_active_positions_count"), 0.0)),
                    "source": "alpaca_broker_positions_compacted",
                },
                "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            }
            return MOBILE_RUNTIME_COMPACTION.compact_positions_response(base_response, compaction=compact)
    except Exception:
        pass
    _ensure_latest_rankings()
    at = _normalize_asset_type(asset_type) if asset_type else None
    rows = POSITION_TRACKER.get_open_positions(asset_type=at)
    top_payload, top_payload_age, top_payload_key = _top_buys_cached_payload_for_mode(
        "balanced",
        include_trace=False,
        max_age_seconds=max(TOP_BUYS_TTL_SECONDS * 4, 1800),
        allow_alt_trace=True,
    )
    if not isinstance(top_payload, dict) or not top_payload:
        latest_runtime_payload = _latest_top_buys_runtime_snapshot()
        if isinstance(latest_runtime_payload, dict) and latest_runtime_payload:
            top_payload = dict(latest_runtime_payload)
            top_payload_key = str(top_payload_key or "latest_runtime_snapshot")
            top_payload_age = _to_float(top_payload_age, 0.0)
    top_row_lookup = {}
    if isinstance(top_payload, dict):
        for bucket in ("stocks", "crypto"):
            block = top_payload.get(bucket) if isinstance(top_payload.get(bucket), dict) else {}
            for seq_key in ("final", "qualified", "best_opportunities"):
                seq = block.get(seq_key) if isinstance(block.get(seq_key), list) else []
                for item in seq:
                    if not isinstance(item, dict):
                        continue
                    sym = str(item.get("symbol") or "").upper().strip()
                    if not sym or sym in top_row_lookup:
                        continue
                    top_row_lookup[sym] = dict(item)
    if not top_row_lookup:
        for bucket in ("stocks", "crypto"):
            seq = LAST_RANKINGS.get(bucket) if isinstance(LAST_RANKINGS.get(bucket), list) else []
            for item in seq:
                if not isinstance(item, dict):
                    continue
                sym = str(item.get("symbol") or "").upper().strip()
                if not sym or sym in top_row_lookup:
                    continue
                top_row_lookup[sym] = dict(item)
    out = []
    lifecycle_state_counts = {
        "fresh_entry": 0,
        "early_winner": 0,
        "stagnant_position": 0,
        "vulnerable_winner": 0,
        "deteriorating_setup": 0,
        "higher_risk_hold": 0,
    }
    position_sync_summary = {
        "open_position_count": int(len(rows)),
        "quotes_synced_count": 0,
        "quote_fallback_count": 0,
        "zero_price_prevented_count": 0,
        "top_buys_matched_count": 0,
        "position_decision_distribution": {},
    }
    def _norm_confidence_pct(value):
        val = _to_float(value, 0.0)
        if val <= 1.0:
            val *= 100.0
        return round(max(0.0, min(100.0, val)), 2)

    for row in rows:
        symbol = str(row.get("symbol") or "").upper()
        latest = _find_latest_row(symbol, asset_type=row.get("asset_type"))
        latest_price_live = None
        if isinstance(latest, dict):
            try:
                latest_price_live = float(latest.get("price"))
                if latest_price_live <= 0:
                    latest_price_live = None
            except (TypeError, ValueError):
                latest_price_live = None
        else:
            latest = {}

        entry_price = _to_float(row.get("entry_price"), 0.0)
        prior_valid_price = _to_float(
            row.get("latest_valid_price"),
            _to_float(row.get("latest_price"), entry_price),
        )
        latest_price = latest_price_live
        position_quote_fallback_used = False
        position_last_valid_price_used = False
        if latest_price is None and prior_valid_price > 0:
            latest_price = prior_valid_price
            position_quote_fallback_used = True
            position_last_valid_price_used = True
        if latest_price is None and entry_price > 0:
            latest_price = entry_price
            position_quote_fallback_used = True
        quote_age_seconds = _to_float(latest.get("quote_age_seconds"), None)
        if quote_age_seconds is None:
            quote_age_seconds = _iso_age_seconds(latest.get("last_snapshot_timestamp") or latest.get("timestamp"))
        quote_source = str(latest.get("quote_source") or latest.get("provider_used") or latest.get("source") or row.get("quote_source") or "unknown")
        position_quote_status = "unavailable"
        if latest_price_live is not None:
            position_quote_status = "live_quote"
        elif latest_price is not None and position_last_valid_price_used:
            position_quote_status = "last_valid_fallback"
        elif latest_price is not None and entry_price > 0:
            position_quote_status = "entry_price_fallback"
        if latest_price_live is not None:
            position_sync_summary["quotes_synced_count"] = int(position_sync_summary.get("quotes_synced_count", 0)) + 1
        elif position_quote_fallback_used:
            position_sync_summary["quote_fallback_count"] = int(position_sync_summary.get("quote_fallback_count", 0)) + 1
        if latest_price_live is None and latest_price is not None and latest_price > 0:
            position_sync_summary["zero_price_prevented_count"] = int(position_sync_summary.get("zero_price_prevented_count", 0)) + 1

        unrealized = None
        if latest_price is not None and latest_price > 0 and entry_price > 0:
            unrealized = round(((latest_price - entry_price) / entry_price) * 100.0, 2)
        prior_peak = _to_float(row.get("peak_unrealized_pnl_percent"), unrealized if unrealized is not None else 0.0)
        prior_adverse = _to_float(row.get("max_adverse_pnl_percent"), unrealized if unrealized is not None else 0.0)
        peak_unrealized = (
            max(prior_peak, unrealized) if unrealized is not None else prior_peak
        )
        adverse_unrealized = (
            min(prior_adverse, unrealized) if unrealized is not None else prior_adverse
        )

        POSITION_TRACKER.update_position_snapshot(
            symbol,
            {
                "quote_batch_id": latest.get("quote_batch_id") or latest.get("entry_quote_batch_id") or "",
                "latest_price": latest_price,
                "latest_valid_price": latest_price if latest_price is not None and latest_price > 0 else prior_valid_price,
                "current_predicted_probability": latest.get("predicted_win_probability"),
                "current_consensus_strength": latest.get("consensus_strength"),
                "current_persona_disagreement_index": latest.get("persona_disagreement_index"),
                "regime_context": latest.get("regime_context", latest.get("regime")),
                "quote_quality": latest.get("quote_quality", "unknown"),
                "quote_source": quote_source,
                "last_quote_age_seconds": quote_age_seconds,
                "position_quote_status": position_quote_status,
                "position_quote_fallback_used": bool(position_quote_fallback_used),
                "position_last_valid_price_used": bool(position_last_valid_price_used),
                "peak_unrealized_pnl_percent": peak_unrealized,
                "max_adverse_pnl_percent": adverse_unrealized,
                "data_unavailable_reason": latest.get("data_unavailable_reason", ""),
                "last_snapshot_timestamp": latest.get("timestamp", ""),
            },
        )

        current_prob = latest.get("predicted_win_probability", row.get("current_predicted_probability"))
        current_consensus = latest.get("consensus_strength", row.get("current_consensus_strength"))
        current_disagreement = latest.get("persona_disagreement_index", row.get("current_persona_disagreement_index"))
        current_regime = latest.get("regime_context", row.get("current_regime_context"))
        quote_quality = latest.get("quote_quality", row.get("quote_quality"))
        quote_source = latest.get("quote_source", row.get("quote_source"))
        quote_age_seconds = (
            _to_float(latest.get("quote_age_seconds"), None)
            if isinstance(latest, dict)
            else None
        )
        if quote_age_seconds is None:
            quote_age_seconds = _iso_age_seconds(latest.get("timestamp")) if isinstance(latest, dict) else None
        data_unavailable_reason = latest.get("data_unavailable_reason", row.get("data_unavailable_reason"))
        snapshot_ts = latest.get("timestamp", row.get("last_snapshot_timestamp"))

        enriched = dict(row)
        enriched["latest_price"] = latest_price
        enriched["unrealized_pnl_percent"] = unrealized
        enriched["peak_unrealized_pnl_percent"] = peak_unrealized
        enriched["max_adverse_pnl_percent"] = adverse_unrealized
        enriched["current_predicted_probability"] = current_prob
        enriched["current_consensus_strength"] = current_consensus
        enriched["current_persona_disagreement_index"] = current_disagreement
        enriched["current_regime_context"] = current_regime
        enriched["quote_quality"] = quote_quality
        enriched["quote_source"] = quote_source
        enriched["last_quote_age_seconds"] = quote_age_seconds
        enriched["data_unavailable_reason"] = data_unavailable_reason
        enriched["last_snapshot_timestamp"] = snapshot_ts
        enriched["current_price"] = round(_to_float(latest_price, 0.0), 6) if latest_price is not None else None
        enriched["position_quote_status"] = position_quote_status
        enriched["position_quote_source"] = quote_source
        enriched["position_quote_freshness_seconds"] = quote_age_seconds
        enriched["position_quote_fallback_used"] = bool(position_quote_fallback_used)
        enriched["position_last_valid_price_used"] = bool(position_last_valid_price_used)
        top_row = top_row_lookup.get(symbol) if symbol else None
        if isinstance(top_row, dict):
            position_sync_summary["top_buys_matched_count"] = int(position_sync_summary.get("top_buys_matched_count", 0)) + 1
            enriched["aligned_top_buys_grade"] = top_row.get("grade")
            enriched["aligned_top_buys_confidence"] = _norm_confidence_pct(
                top_row.get("confidence", top_row.get("predicted_win_probability"))
            )
            enriched["aligned_top_buys_qualification"] = top_row.get("qualification")
            enriched["aligned_top_buys_state"] = top_row.get("canonical_final_state")
            enriched["aligned_signal_quality_decision"] = top_row.get("signal_quality_decision")
            enriched["aligned_entry_timing_decision"] = top_row.get("entry_timing_decision")
            enriched["aligned_learning_activation_decision"] = top_row.get("learning_activation_decision")
        else:
            enriched["aligned_top_buys_grade"] = enriched.get("aligned_top_buys_grade")
            enriched["aligned_top_buys_confidence"] = _norm_confidence_pct(
                enriched.get("current_predicted_probability", enriched.get("entry_predicted_win_probability"))
            )
            enriched["aligned_top_buys_qualification"] = None
            enriched["aligned_top_buys_state"] = None
            enriched["aligned_signal_quality_decision"] = None
            enriched["aligned_entry_timing_decision"] = None
            enriched["aligned_learning_activation_decision"] = None
        pullback_from_peak = round(
            max(0.0, _to_float(peak_unrealized, 0.0) - (_to_float(unrealized, 0.0) if unrealized is not None else _to_float(peak_unrealized, 0.0))),
            4,
        )
        enriched["pullback_from_peak_percent"] = pullback_from_peak
        consensus_drop = _to_float(enriched.get("entry_consensus_strength"), 0.0) - _to_float(current_consensus, 0.0)
        disagreement_rise = _to_float(current_disagreement, 0.0) - _to_float(enriched.get("entry_persona_disagreement_index"), 0.0)
        lifecycle_state = "stagnant_position"
        if unrealized is not None and abs(unrealized) <= 0.35:
            lifecycle_state = "fresh_entry"
        if unrealized is not None and unrealized >= 1.2 and pullback_from_peak <= 0.8:
            lifecycle_state = "early_winner"
        if unrealized is not None and unrealized >= 1.5 and pullback_from_peak >= 1.4:
            lifecycle_state = "vulnerable_winner"
        if unrealized is not None and unrealized < -1.0:
            lifecycle_state = "deteriorating_setup"
        if disagreement_rise >= 10.0 or consensus_drop >= 12.0 or _to_float(quote_age_seconds, 0.0) > 45.0:
            lifecycle_state = "higher_risk_hold"
        lifecycle_state_counts[lifecycle_state] = int(lifecycle_state_counts.get(lifecycle_state, 0)) + 1
        review_urgency_score = max(
            0.0,
            min(
                100.0,
                (max(0.0, pullback_from_peak) * 15.0)
                + (max(0.0, consensus_drop) * 1.8)
                + (max(0.0, disagreement_rise) * 1.2)
                + (6.0 if _to_float(quote_age_seconds, 0.0) > 45.0 else 0.0)
                + (14.0 if lifecycle_state in {"deteriorating_setup", "higher_risk_hold"} else 0.0),
            ),
        )
        if review_urgency_score >= 68.0:
            risk_posture = "sell_now_review"
        elif review_urgency_score >= 45.0:
            risk_posture = "reduce_or_trim_review"
        elif review_urgency_score >= 24.0:
            risk_posture = "tighten_stop_review"
        else:
            risk_posture = "hold_through_noise"
        enriched["position_lifecycle_state"] = lifecycle_state
        signal_quality_decision = str(
            (top_row or {}).get("signal_quality_decision")
            or enriched.get("aligned_signal_quality_decision")
            or ""
        ).strip().lower()
        entry_timing_decision = str(
            (top_row or {}).get("entry_timing_decision")
            or enriched.get("aligned_entry_timing_decision")
            or ""
        ).strip().lower()
        learning_activation_decision = str(
            (top_row or {}).get("learning_activation_decision")
            or enriched.get("aligned_learning_activation_decision")
            or ""
        ).strip().lower()
        policy_hint = str(
            (top_row or {}).get("historical_policy_action_hint")
            or ""
        ).strip().lower()
        qualification = str(
            (top_row or {}).get("qualification")
            or (top_row or {}).get("canonical_final_state")
            or ""
        ).strip().lower()
        position_decision = (
            "exit_review"
            if risk_posture == "sell_now_review"
            else "reduce_or_trim"
            if risk_posture == "reduce_or_trim_review"
            else "tighten_stop"
            if risk_posture == "tighten_stop_review"
            else "hold"
        )
        decision_reasons = [f"lifecycle:{risk_posture}"]
        if position_quote_status == "unavailable":
            position_decision = "data_unavailable_review"
            decision_reasons.append("no_reliable_quote")
        else:
            weak_signal = signal_quality_decision in {"reject", "monitor_only"} or policy_hint in {"monitor_only", "avoid_for_now", "paper_only"} or entry_timing_decision in {"avoid_for_now", "avoid_chase"}
            mixed_signal = signal_quality_decision in {"watchlist_only", "allow_with_confirmation"} or entry_timing_decision in {"wait_for_confirmation", "wait_for_pullback"} or learning_activation_decision in {"caution", "suppress"} or _to_float(quote_age_seconds, 0.0) > 90.0
            if weak_signal:
                position_decision = "exit_review" if unrealized is not None and unrealized <= -2.0 else ("reduce_or_trim" if unrealized is not None and unrealized < 0.0 else "tighten_stop")
                decision_reasons.append("top_buys_alignment_weak")
            elif mixed_signal:
                if position_decision not in {"exit_review", "reduce_or_trim"}:
                    position_decision = "hold_with_caution"
                decision_reasons.append("confirmation_or_caution_required")
            elif qualification in {"released_buy", "paper_ready", "paper_ready_candidate"} and signal_quality_decision == "allow" and entry_timing_decision in {"immediate", "wait_for_confirmation", "confirmation"}:
                position_decision = "strong_hold" if unrealized is not None and unrealized >= 1.0 else "hold"
                decision_reasons.append("top_buys_alignment_supportive")
        if position_decision == "data_unavailable_review":
            position_risk_state = "data_gap"
        elif position_decision in {"exit_review", "reduce_or_trim"}:
            position_risk_state = "high_risk"
        elif position_decision in {"tighten_stop", "hold_with_caution"}:
            position_risk_state = "elevated_risk"
        else:
            position_risk_state = "normal_risk"
        position_action_recommendation = (
            "exit_review"
            if position_decision == "exit_review"
            else "reduce_or_trim"
            if position_decision == "reduce_or_trim"
            else "tighten_stop"
            if position_decision == "tighten_stop"
            else "hold_with_caution"
            if position_decision == "hold_with_caution"
            else "hold"
        )
        position_decision_confidence = _norm_confidence_pct(
            (top_row or {}).get("confidence", current_prob)
        )
        if position_decision in {"data_unavailable_review", "hold_with_caution"}:
            position_decision_confidence = round(max(0.0, position_decision_confidence - 12.0), 2)
        position_decision_reason = "; ".join([r for r in decision_reasons if r][:3])
        enriched["position_decision"] = position_decision
        enriched["position_decision_confidence"] = position_decision_confidence
        enriched["position_decision_reason"] = position_decision_reason
        enriched["position_risk_state"] = position_risk_state
        enriched["position_action_recommendation"] = position_action_recommendation
        canonical_position_state = (
            "exit"
            if position_decision == "exit_review"
            else "trim"
            if position_decision == "reduce_or_trim"
            else "tighten_stop"
            if position_decision == "tighten_stop"
            else "active_position"
        )
        enriched["canonical_position_decision_state"] = canonical_position_state
        enriched["canonical_trade_workflow_state"] = {
            "state": canonical_position_state,
            "source": "position_lifecycle_engine",
        }
        enriched["position_health_monitor"] = {
            "review_urgency_score": round(review_urgency_score, 2),
            "risk_posture": risk_posture,
            "consensus_drop": round(consensus_drop, 4),
            "disagreement_rise": round(disagreement_rise, 4),
        }
        enriched["current_risk_sell_posture"] = risk_posture
        dist = dict(position_sync_summary.get("position_decision_distribution") or {})
        dist[position_decision] = int(dist.get(position_decision, 0)) + 1
        position_sync_summary["position_decision_distribution"] = dist
        out.append(enriched)

    base_response = {
        "count": len(out),
        "positions": out,
        "position_lifecycle_intelligence": {
            "lifecycle_state_counts": lifecycle_state_counts,
            "total_open_positions": int(len(out)),
            "higher_risk_hold_count": int(lifecycle_state_counts.get("higher_risk_hold", 0)),
            "deteriorating_setup_count": int(lifecycle_state_counts.get("deteriorating_setup", 0)),
            "healthy_winner_count": int(lifecycle_state_counts.get("early_winner", 0)),
            "position_lifecycle_quality_score": round(
                max(
                    0.0,
                    min(
                        100.0,
                        62.0
                        + (lifecycle_state_counts.get("early_winner", 0) * 5.0)
                        - (lifecycle_state_counts.get("deteriorating_setup", 0) * 6.0)
                        - (lifecycle_state_counts.get("higher_risk_hold", 0) * 4.0),
                    ),
                ),
                2,
            ),
            "canonical_state_counts": {
                "active_position": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "active_position")),
                "tighten_stop": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "tighten_stop")),
                "trim": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "trim")),
                "exit": int(sum(1 for r in out if str((r or {}).get("canonical_position_decision_state") or "") == "exit")),
            },
        },
        "position_sync_v1": {
            **position_sync_summary,
            "top_buys_cache_source": str(top_payload_key or "none"),
            "top_buys_cache_age_seconds": round(max(0.0, _to_float(top_payload_age, 0.0)), 2),
        },
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }
    try:
        compaction = _mobile_runtime_compaction_snapshot(force=False, include_closed_orders=False)
        return MOBILE_RUNTIME_COMPACTION.compact_positions_response(base_response, compaction=compaction)
    except Exception:
        base_response["mobile_runtime_compaction"] = {
            "mobile_runtime_compaction_active": False,
            "mobile_payload_compacted": False,
            "full_history_preserved": True,
            "replay_learning_preserved": True,
        }
        return base_response


@router.get("/api/sell_alerts")
def position_sell_alerts():
    cached = _CACHE.get("position_sell_alerts", {})
    if cached.get("data") and (time.time() - float(cached.get("ts", 0.0))) <= POSITION_SELL_ALERTS_TTL_SECONDS:
        return dict(cached.get("data", {}))

    _ensure_latest_rankings()
    positions_rows = POSITION_TRACKER.get_open_positions()
    open_trades = []
    pos_by_symbol = {}
    latest_by_symbol = {}
    freshness_values = []
    ws_overlay_count = 0
    for pos in positions_rows:
            symbol = str(pos.get("symbol") or "").upper()
            pos_by_symbol[symbol] = dict(pos)
            latest = _find_latest_row(symbol, asset_type=pos.get("asset_type")) or {}
            latest_by_symbol[symbol] = dict(latest)
            latest_price = latest.get("price", pos.get("latest_price"))
            quote_age_seconds = _to_float(latest.get("quote_age_seconds"), None)
            if quote_age_seconds is None:
                quote_age_seconds = _iso_age_seconds(latest.get("timestamp", pos.get("last_snapshot_timestamp")))
            if quote_age_seconds is not None:
                freshness_values.append(float(quote_age_seconds))
            quote_source = str(
                latest.get("quote_source")
                or latest.get("provider_used")
                or latest.get("source")
                or pos.get("quote_source")
                or ""
            )
            if quote_source == "alpaca_ws_overlay":
                ws_overlay_count += 1
            entry_price = _to_float(pos.get("entry_price"), 0.0)
            unrealized_pct = None
            if _to_float(latest_price, 0.0) > 0 and entry_price > 0:
                unrealized_pct = round(((_to_float(latest_price, 0.0) - entry_price) / entry_price) * 100.0, 4)
            peak_unrealized = _to_float(pos.get("peak_unrealized_pnl_percent"), unrealized_pct if unrealized_pct is not None else 0.0)
            adverse_unrealized = _to_float(pos.get("max_adverse_pnl_percent"), unrealized_pct if unrealized_pct is not None else 0.0)
            if unrealized_pct is not None:
                peak_unrealized = max(peak_unrealized, unrealized_pct)
                adverse_unrealized = min(adverse_unrealized, unrealized_pct)
            pullback_from_peak = round(
                max(0.0, peak_unrealized - (unrealized_pct if unrealized_pct is not None else peak_unrealized)),
                4,
            )
            POSITION_TRACKER.update_position_snapshot(
                symbol,
                {
                    "quote_batch_id": latest.get("quote_batch_id", pos.get("entry_quote_batch_id", "")),
                    "latest_price": latest_price,
                    "current_predicted_probability": latest.get("predicted_win_probability", pos.get("current_predicted_probability")),
                    "current_consensus_strength": latest.get("consensus_strength", pos.get("current_consensus_strength")),
                    "current_persona_disagreement_index": latest.get("persona_disagreement_index", pos.get("current_persona_disagreement_index")),
                    "regime_context": latest.get("regime_context", pos.get("current_regime_context")),
                    "quote_quality": latest.get("quote_quality", pos.get("quote_quality", "unknown")),
                    "quote_source": quote_source,
                    "last_quote_age_seconds": quote_age_seconds,
                    "peak_unrealized_pnl_percent": peak_unrealized,
                    "max_adverse_pnl_percent": adverse_unrealized,
                    "data_unavailable_reason": latest.get("data_unavailable_reason", pos.get("data_unavailable_reason", "")),
                    "last_snapshot_timestamp": latest.get("timestamp", pos.get("last_snapshot_timestamp", "")),
                },
            )
            open_trades.append({
                "symbol": symbol,
                "mode": pos.get("mode", "intraday"),
                "entry_timestamp": pos.get("entry_timestamp"),
                "predicted_win_probability": pos.get("entry_predicted_win_probability"),
                "current_predicted_probability": latest.get("predicted_win_probability", pos.get("current_predicted_probability", pos.get("entry_predicted_win_probability"))),
                "consensus_strength": pos.get("entry_consensus_strength"),
                "current_consensus_strength": latest.get("consensus_strength", pos.get("current_consensus_strength", pos.get("entry_consensus_strength"))),
                "persona_disagreement_index": pos.get("entry_persona_disagreement_index"),
                "current_persona_disagreement_index": latest.get("persona_disagreement_index", pos.get("current_persona_disagreement_index", pos.get("entry_persona_disagreement_index"))),
                "regime_context": pos.get("entry_regime_context"),
                "current_regime_context": latest.get("regime_context", pos.get("current_regime_context", pos.get("entry_regime_context"))),
                "quote_quality": latest.get("quote_quality", pos.get("quote_quality", "unknown")),
                "quote_source": quote_source,
                "quote_age_seconds": quote_age_seconds,
                "latest_price": latest_price,
                "entry_price": entry_price,
                "unrealized_pnl_percent": unrealized_pct,
                "peak_unrealized_pnl_percent": peak_unrealized,
                "max_adverse_pnl_percent": adverse_unrealized,
                "pullback_from_peak_percent": pullback_from_peak,
            })

    eval_payload = EXIT_INTEL.evaluate_open_trades(open_trades, live_perf=LIVE_SIGNAL_LOG.live_performance())
    learned = EXIT_LEARNING.learned_thresholds()
    learned_used = bool(learned.get("sample_size", 0) >= 20)
    learning_exit_policy = {}
    regime_policy_hints = {}
    contextual_exit_hints = {}
    contextual_hold_time_hints = {}
    sell_quality_enforcement = {}
    degradation_exit_enforcement = {}
    early_weakening_exit_trigger = {}
    premature_exit_discipline = {}
    late_exit_penalty_enforcement = {}
    try:
        insights_payload = _normalize_learning_insights_payload(_get_enriched_learning_insights_cached())
        learning_exit_policy = dict(insights_payload.get("exit_policy_hints") or {})
        regime_policy_hints = dict(insights_payload.get("regime_policy_hints") or {})
        contextual_exit_hints = dict(insights_payload.get("contextual_exit_hints") or {})
        contextual_hold_time_hints = dict(insights_payload.get("contextual_hold_time_hints") or {})
        sell_quality_enforcement = dict(insights_payload.get("sell_quality_enforcement_engine") or {})
        degradation_exit_enforcement = dict(insights_payload.get("degradation_exit_enforcement_engine") or {})
        early_weakening_exit_trigger = dict(insights_payload.get("early_weakening_exit_trigger") or {})
        premature_exit_discipline = dict(insights_payload.get("premature_exit_discipline_engine") or {})
        late_exit_penalty_enforcement = dict(insights_payload.get("late_exit_penalty_enforcement") or {})
    except Exception:
        learning_exit_policy = {}
        regime_policy_hints = {}
        contextual_exit_hints = {}
        contextual_hold_time_hints = {}
        sell_quality_enforcement = {}
        degradation_exit_enforcement = {}
        early_weakening_exit_trigger = {}
        premature_exit_discipline = {}
        late_exit_penalty_enforcement = {}
    base_pullback_threshold = max(1.2, min(2.8, _to_float(learning_exit_policy.get("trailing_pullback_exit_threshold_percent"), 2.0)))
    base_stop_loss_threshold = max(-3.2, min(-1.8, _to_float(learning_exit_policy.get("stop_loss_threshold_percent"), -2.5)))
    exit_quality_score = _to_float(learning_exit_policy.get("exit_quality_score"), 0.0)
    exit_quality_trend = str(learning_exit_policy.get("exit_quality_trend") or "unknown").lower()
    avg_capture_ratio = _to_float(learning_exit_policy.get("avg_capture_ratio_percent"), 0.0)
    if exit_quality_score >= 70.0 and exit_quality_trend == "improving":
        base_pullback_threshold = min(2.8, base_pullback_threshold + 0.1)
        base_stop_loss_threshold = max(-3.2, base_stop_loss_threshold - 0.1)
    elif exit_quality_score <= 45.0 or exit_quality_trend == "worsening":
        base_pullback_threshold = max(1.2, base_pullback_threshold - 0.15)
        base_stop_loss_threshold = min(-1.8, base_stop_loss_threshold + 0.15)
    if avg_capture_ratio < 50.0:
        base_pullback_threshold = max(1.2, base_pullback_threshold - 0.1)
    alerts = []
    action_priority_counts = {
        "sell_now": 0,
        "trim": 0,
        "reduce": 0,
        "hold_through_noise": 0,
        "monitor": 0,
    }
    for sig in eval_payload.get("signals", []):
        if not isinstance(sig, dict):
            continue
        level = str(sig.get("exit_signal") or "NONE")
        reasons = []
        explanation = str(sig.get("explanation") or "")
        if explanation and explanation != "No exit deterioration detected.":
            reasons = [x.strip() for x in explanation.split(";") if x.strip()]
        primary_trigger = reasons[0] if reasons else "none"
        secondary = reasons[1:] if len(reasons) > 1 else []
        if level in {"STRONG_EXIT", "RISK_EXIT", "TIME_EXIT"}:
            recommended_action = "EXIT"
            urgency = "high"
        elif level == "SELL_WATCH":
            recommended_action = "TIGHTEN_STOP"
            urgency = "medium"
        elif level == "TIME_REVIEW":
            recommended_action = "TRIM"
            urgency = "medium"
        else:
            recommended_action = "HOLD"
            urgency = "low"

        symbol = str(sig.get("symbol") or "").upper()
        pos = pos_by_symbol.get(symbol, {})
        latest_ctx = latest_by_symbol.get(symbol, {})
        prob_drop = _to_float(sig.get("probability_drop_percent"), 0.0)
        dis_change = _to_float(pos.get("current_persona_disagreement_index"), 0.0) - _to_float(
            pos.get("entry_persona_disagreement_index"), 0.0
        )
        regime_shift = bool(sig.get("regime_shift", False))
        if learned_used and level == "NONE":
            if prob_drop >= _to_float(learned.get("probability_drop_sellwatch_threshold"), 8.0):
                recommended_action = "TIGHTEN_STOP"
                urgency = "medium"
                if primary_trigger == "none":
                    primary_trigger = "learned_probability_drop_threshold"
                secondary = list(secondary) + ["learned_threshold_trigger"]

        latest_price = _to_float(pos.get("latest_price"), 0.0)
        suggested_stop_update = None
        unrealized_pct = _to_float(pos.get("unrealized_pnl_percent"), None)
        peak_unrealized = _to_float(pos.get("peak_unrealized_pnl_percent"), unrealized_pct if unrealized_pct is not None else 0.0)
        pullback_from_peak = _to_float(pos.get("pullback_from_peak_percent"), 0.0)
        quote_age_seconds = _to_float(pos.get("quote_age_seconds"), _to_float(pos.get("last_quote_age_seconds"), 0.0))
        current_regime = str(pos.get("current_regime_context") or "unknown").strip().lower()
        setup_key = str(
            latest_ctx.get("setup_type")
            or pos.get("entry_setup_type")
            or pos.get("setup_type")
            or "unknown"
        ).strip().lower()
        persona_key = str(
            latest_ctx.get("persona_best_fit")
            or pos.get("entry_persona_best_fit")
            or "unknown"
        ).strip().lower()
        cap_key = str(
            latest_ctx.get("market_cap_category")
            or pos.get("entry_market_cap_category")
            or "unknown"
        ).strip().lower()
        now_month = datetime.now(UTC).month
        season_key = "winter" if now_month in (12, 1, 2) else "spring" if now_month in (3, 4, 5) else "summer" if now_month in (6, 7, 8) else "fall"
        regime_hint = regime_policy_hints.get(current_regime, {}) if isinstance(regime_policy_hints, dict) else {}
        regime_mult = _to_float(regime_hint.get("multiplier"), 1.0)
        pullback_threshold = base_pullback_threshold
        stop_loss_threshold = base_stop_loss_threshold
        if regime_mult < 0.97:
            pullback_threshold = max(1.2, pullback_threshold - 0.2)
            stop_loss_threshold = min(-1.8, stop_loss_threshold + 0.2)
        elif regime_mult > 1.03:
            pullback_threshold = min(2.8, pullback_threshold + 0.2)
            stop_loss_threshold = max(-3.2, stop_loss_threshold - 0.2)
        setup_regime_hint = ((contextual_exit_hints.get("setup_regime") or {}).get(f"{setup_key}|{current_regime}") or {})
        persona_regime_hint = ((contextual_exit_hints.get("persona_regime") or {}).get(f"{persona_key}|{current_regime}") or {})
        setup_cap_hint = ((contextual_exit_hints.get("setup_cap_bucket") or {}).get(f"{setup_key}|{cap_key}") or {})
        season_setup_hint = ((contextual_exit_hints.get("season_setup") or {}).get(f"{season_key}|{setup_key}") or {})
        context_exit_hints = [h for h in (setup_regime_hint, persona_regime_hint, setup_cap_hint, season_setup_hint) if isinstance(h, dict) and h]
        hold_setup_regime_hint = ((contextual_hold_time_hints.get("setup_regime") or {}).get(f"{setup_key}|{current_regime}") or {})
        hold_persona_regime_hint = ((contextual_hold_time_hints.get("persona_regime") or {}).get(f"{persona_key}|{current_regime}") or {})
        hold_setup_cap_hint = ((contextual_hold_time_hints.get("setup_cap_bucket") or {}).get(f"{setup_key}|{cap_key}") or {})
        hold_season_setup_hint = ((contextual_hold_time_hints.get("season_setup") or {}).get(f"{season_key}|{setup_key}") or {})
        hold_time_hints = [h for h in (hold_setup_regime_hint, hold_persona_regime_hint, hold_setup_cap_hint, hold_season_setup_hint) if isinstance(h, dict) and h]
        if context_exit_hints:
            wsum = 0.0
            pb_num = 0.0
            sl_num = 0.0
            for h in context_exit_hints:
                s = max(1.0, _to_float(h.get("sample_size"), 1.0))
                w = min(2.2, s / 80.0)
                pb_num += _to_float(h.get("trailing_pullback_exit_threshold_percent"), pullback_threshold) * w
                sl_num += _to_float(h.get("stop_loss_threshold_percent"), stop_loss_threshold) * w
                wsum += w
            if wsum > 0:
                contextual_pullback = pb_num / wsum
                contextual_stop_loss = sl_num / wsum
                # Conservative blend: mostly global+regime, partially contextual.
                pullback_threshold = max(1.2, min(2.8, (pullback_threshold * 0.7) + (contextual_pullback * 0.3)))
                stop_loss_threshold = max(-3.2, min(-1.8, (stop_loss_threshold * 0.7) + (contextual_stop_loss * 0.3)))
        hold_review_intraday = _to_float(learning_exit_policy.get("time_review_intraday_minutes"), 120.0)
        hold_review_swing_days = _to_float(learning_exit_policy.get("time_review_swing_days"), 15.0)
        hold_bias = 0.0
        if hold_time_hints:
            wsum = 0.0
            intraday_num = 0.0
            swing_num = 0.0
            bias_num = 0.0
            for h in hold_time_hints:
                s = max(1.0, _to_float(h.get("sample_size"), 1.0))
                w = min(2.0, s / 80.0)
                intraday_num += _to_float(h.get("review_intraday_minutes"), hold_review_intraday) * w
                swing_num += _to_float(h.get("review_swing_days"), hold_review_swing_days) * w
                bias_num += _to_float(h.get("hold_bias"), 0.0) * w
                wsum += w
            if wsum > 0:
                hold_review_intraday = max(30.0, min(240.0, (hold_review_intraday * 0.7) + ((intraday_num / wsum) * 0.3)))
                hold_review_swing_days = max(5.0, min(35.0, (hold_review_swing_days * 0.7) + ((swing_num / wsum) * 0.3)))
                hold_bias = bias_num / wsum
        memory_row = {
            "symbol": symbol,
            "setup_type": setup_key,
            "market_regime": current_regime,
            "entry_signal_tags": latest_ctx.get("entry_signal_tags", pos.get("entry_signal_tags", "")),
            "signal_tags": latest_ctx.get("signal_tags", pos.get("signal_tags", "")),
        }
        memory_ctx = _memory_context_for_row(memory_row)
        memory_sample = int(_to_float(memory_ctx.get("memory_sample_size"), 0.0))
        memory_wr = _to_float(memory_ctx.get("memory_win_rate"), 0.0)
        memory_fast_loss = _to_float(memory_ctx.get("memory_fast_loss_rate"), 0.0)
        memory_expectancy = _to_float(memory_ctx.get("memory_expectancy"), 0.0)
        trailing_exit = False
        stop_loss_exit = False
        if unrealized_pct is not None and peak_unrealized >= 4.0 and pullback_from_peak >= pullback_threshold:
            trailing_exit = True
            if recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                recommended_action = "EXIT"
                urgency = "high"
            if primary_trigger == "none":
                primary_trigger = "profit_protection_pullback"
            secondary = list(secondary) + [f"pullback_from_peak>={pullback_threshold:.1f}%"]
        if unrealized_pct is not None and unrealized_pct <= stop_loss_threshold:
            stop_loss_exit = True
            recommended_action = "EXIT"
            urgency = "high"
            primary_trigger = "stop_loss_threshold"
            secondary = list(secondary) + [f"unrealized_pnl<={stop_loss_threshold:.1f}%"]
        # Enforcement: escalate weaker/degrading positions earlier when sell/degradation quality is poor.
        degr_enf = _to_float(degradation_exit_enforcement.get("degradation_exit_enforcement_score"), 0.0)
        early_weaken = _to_float(early_weakening_exit_trigger.get("early_weakening_exit_trigger_score"), 0.0)
        sell_enf = _to_float(sell_quality_enforcement.get("sell_quality_enforcement_score"), 0.0)
        prem_disc = _to_float(premature_exit_discipline.get("premature_exit_discipline_score"), 0.0)
        late_enf = _to_float(late_exit_penalty_enforcement.get("late_exit_penalty_enforcement_score"), 0.0)
        enforcement_pressure = max(
            0.0,
            min(
                100.0,
                (degr_enf * 0.35)
                + (early_weaken * 0.25)
                + (sell_enf * 0.20)
                + ((100.0 - prem_disc) * 0.10)
                + ((100.0 - late_enf) * 0.10),
            ),
        )
        if memory_sample >= 16:
            if memory_wr <= 26.0 or memory_fast_loss >= 9.0 or memory_expectancy <= -0.18:
                enforcement_pressure = min(100.0, enforcement_pressure + 9.0)
                secondary = list(secondary) + ["similar_setup_loser_memory_pressure"]
            elif memory_wr >= 52.0 and memory_fast_loss <= 4.0 and memory_expectancy >= 0.12:
                enforcement_pressure = max(0.0, enforcement_pressure - 5.0)
                secondary = list(secondary) + ["similar_setup_winner_memory_relief"]
        if recommended_action in {"HOLD", "TIGHTEN_STOP"} and enforcement_pressure >= 56.0:
            recommended_action = "TRIM" if enforcement_pressure < 72.0 else "EXIT"
            urgency = "high" if enforcement_pressure >= 72.0 else "medium"
            if primary_trigger == "none":
                primary_trigger = "degradation_enforcement"
            secondary = list(secondary) + [f"enforcement_pressure>={enforcement_pressure:.1f}"]
        if recommended_action == "HOLD" and prob_drop >= 8.0 and enforcement_pressure >= 48.0:
            recommended_action = "TIGHTEN_STOP"
            urgency = "medium"
            secondary = list(secondary) + ["early_weakening_enforcement"]
        if quote_age_seconds and quote_age_seconds > 45 and recommended_action == "HOLD":
            recommended_action = "TIGHTEN_STOP"
            urgency = "medium"
            secondary = list(secondary) + ["quote_stale>45s"]
        entry_ts = str(pos.get("entry_timestamp") or "").strip()
        hold_seconds = _iso_age_seconds(entry_ts) if entry_ts else None
        if hold_seconds and hold_seconds > 0:
            hold_minutes = hold_seconds / 60.0
            mode = str(pos.get("mode") or "").lower()
            if mode == "intraday":
                if hold_minutes >= hold_review_intraday and recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                    recommended_action = "TRIM" if hold_bias <= 0.2 else recommended_action
                    urgency = "medium" if urgency == "low" else urgency
                    secondary = list(secondary) + [f"context_hold_review>{hold_review_intraday:.0f}m"]
            else:
                hold_days = hold_seconds / 86400.0
                if hold_days >= hold_review_swing_days and recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                    recommended_action = "TRIM" if hold_bias <= 0.2 else recommended_action
                    urgency = "medium" if urgency == "low" else urgency
                    secondary = list(secondary) + [f"context_hold_review>{hold_review_swing_days:.1f}d"]
        if recommended_action in {"TIGHTEN_STOP", "TRIM"} and latest_price > 0:
            suggested_stop_update = round(latest_price * 0.985, 4)
        risk_est = EXIT_LEARNING.expected_risk_if_hold(
            probability_drop_percent=prob_drop,
            disagreement_increase=dis_change,
            regime_shift=regime_shift,
        )
        risk_hold = _to_float(risk_est.get("expected_risk_if_hold"), 0.0)
        risk_conf = _to_float(risk_est.get("confidence"), 0.0)
        risk_sample = _to_int(risk_est.get("sample_size"), 0)
        missed_profit_pressure = _to_float(
            risk_est.get("missed_profit_pressure"),
            _to_float(learned.get("missed_profit_pressure"), 0.0),
        )
        hold_quality_estimate = _to_float(
            risk_est.get("hold_quality_estimate"),
            _to_float(learned.get("hold_quality_estimate"), 0.0),
        )
        if risk_sample >= 20 and risk_conf >= 0.35:
            if risk_hold >= 0.74 and recommended_action in {"HOLD", "TIGHTEN_STOP", "TRIM"}:
                recommended_action = "EXIT"
                urgency = "high"
                if primary_trigger == "none":
                    primary_trigger = "exit_learning_high_risk_if_hold"
                secondary = list(secondary) + [f"risk_if_hold>={risk_hold:.2f}"]
            elif risk_hold >= 0.62 and recommended_action in {"HOLD", "TIGHTEN_STOP"}:
                recommended_action = "TRIM"
                urgency = "medium" if urgency == "low" else urgency
                if primary_trigger == "none":
                    primary_trigger = "exit_learning_elevated_risk_if_hold"
                secondary = list(secondary) + [f"risk_if_hold>={risk_hold:.2f}"]
            elif (
                risk_hold <= 0.36
                and hold_quality_estimate >= 0.58
                and missed_profit_pressure >= 0.30
                and recommended_action == "TIGHTEN_STOP"
            ):
                recommended_action = "HOLD"
                urgency = "low"
                secondary = list(secondary) + ["exit_learning_hold_quality_support"]
        exit_reason_stack = [primary_trigger] + [s for s in secondary if s]
        exit_reason_stack = [r for r in exit_reason_stack if str(r or "").strip()]
        if not exit_reason_stack:
            exit_reason_stack = ["none"]
        if recommended_action == "EXIT":
            action_priority = "sell_now"
            canonical_sell_state = "exit"
        elif recommended_action == "TRIM":
            action_priority = "trim"
            canonical_sell_state = "trim"
        elif recommended_action == "TIGHTEN_STOP":
            action_priority = "reduce"
            canonical_sell_state = "tighten_stop"
        elif recommended_action == "HOLD" and urgency == "low":
            action_priority = "hold_through_noise"
            canonical_sell_state = "active_position"
        else:
            action_priority = "monitor"
            canonical_sell_state = "active_position"
        action_priority_counts[action_priority] = int(action_priority_counts.get(action_priority, 0)) + 1
        exit_signal_confidence = max(
            0.0,
            min(
                100.0,
                (_to_float(sig.get("signal_strength_score"), 0.0) * 0.55)
                + (max(0.0, prob_drop) * 2.1)
                + (7.0 if trailing_exit else 0.0)
                + (9.0 if stop_loss_exit else 0.0)
                + (6.0 if urgency == "high" else (3.0 if urgency == "medium" else 0.0)),
            ),
        )
        if recommended_action == "EXIT":
            core_exit_state = "exit_now"
        elif recommended_action == "TRIM":
            core_exit_state = "trim_risk"
        elif recommended_action == "TIGHTEN_STOP":
            core_exit_state = "tighten_and_monitor"
        else:
            core_exit_state = "hold_cautious" if risk_hold >= 0.45 else "hold_through_noise"
        core_exit_discipline_score = max(
            0.0,
            min(
                100.0,
                (exit_signal_confidence * 0.55)
                + (risk_hold * 100.0 * 0.30)
                + ((100.0 - (hold_quality_estimate * 100.0)) * 0.15),
            ),
        )

        alert_row = {
            "symbol": sig.get("symbol"),
            "asset_type": sig.get("asset_type"),
            "alert_level": level,
            "reasons": reasons,
            "primary_trigger": primary_trigger,
            "secondary_triggers": secondary,
            "probability_drop_percent": prob_drop,
            "consensus_change": sig.get("consensus_drop", 0.0),
            "regime_change": bool(sig.get("regime_shift", False)),
            "recommended_action": recommended_action,
            "suggested_action": "Review for manual exit" if level != "NONE" else "Hold",
            "suggested_stop_update": suggested_stop_update,
            "learned_thresholds_used": learned_used,
            "expected_risk_if_hold": risk_est.get("expected_risk_if_hold", 0.0),
            "expected_risk_sample_size": risk_est.get("sample_size", 0),
            "signal_strength_score": sig.get("signal_strength_score", 0.0),
            "exit_signal_confidence": round(exit_signal_confidence, 2),
            "exit_reason_stack": exit_reason_stack,
            "strongest_exit_trigger": exit_reason_stack[0],
            "position_exit_priority": action_priority,
            "canonical_position_decision_state": canonical_sell_state,
            "canonical_trade_workflow_state": {
                "state": canonical_sell_state,
                "source": "sell_alert_engine",
            },
            "core_exit_discipline_state": core_exit_state,
            "core_exit_discipline_score": round(core_exit_discipline_score, 2),
            "urgency": urgency,
            "unrealized_pnl_percent": unrealized_pct,
            "peak_unrealized_pnl_percent": peak_unrealized,
            "pullback_from_peak_percent": pullback_from_peak,
            "quote_age_seconds": quote_age_seconds,
            "quote_source": pos.get("quote_source"),
            "trailing_exit_triggered": trailing_exit,
            "stop_loss_triggered": stop_loss_exit,
            "exit_policy_applied": {
                "trailing_pullback_threshold_percent": round(pullback_threshold, 2),
                "stop_loss_threshold_percent": round(stop_loss_threshold, 2),
                "base_policy_reason": str(learning_exit_policy.get("policy_reason") or "default"),
                "regime_multiplier": round(regime_mult, 4),
                "context_setup": setup_key,
                "context_persona": persona_key,
                "context_cap_bucket": cap_key,
                "context_season": season_key,
                "contextual_hints_used_count": len(context_exit_hints),
                "hold_time_context_hints_used_count": len(hold_time_hints),
                "hold_review_intraday_minutes": round(hold_review_intraday, 2),
                "hold_review_swing_days": round(hold_review_swing_days, 2),
                "hold_bias": round(hold_bias, 4),
                "exit_quality_score": round(exit_quality_score, 2),
                "exit_quality_trend": exit_quality_trend,
                "avg_capture_ratio_percent": round(avg_capture_ratio, 2),
                "exit_learning_expected_risk_if_hold": round(risk_hold, 4),
                "exit_learning_confidence": round(risk_conf, 4),
                "exit_learning_sample_size": int(risk_sample),
                "exit_learning_missed_profit_pressure": round(missed_profit_pressure, 4),
                "exit_learning_hold_quality_estimate": round(hold_quality_estimate, 4),
            },
            "key_signal_changes": {
                "probability_drop_percent": prob_drop,
                "consensus_change": sig.get("consensus_drop", 0.0),
                "persona_disagreement_change": round(dis_change, 4),
                "regime_shift": regime_shift,
                "enforcement_pressure": round(enforcement_pressure, 2),
                "quote_quality": pos.get("quote_quality"),
                "current_regime_context": pos.get("current_regime_context"),
                "entry_regime_context": pos.get("entry_regime_context"),
            },
            "persona_delta": {
                "entry_consensus_strength": pos.get("entry_consensus_strength"),
                "current_consensus_strength": pos.get("current_consensus_strength"),
                "entry_persona_disagreement_index": pos.get("entry_persona_disagreement_index"),
                "current_persona_disagreement_index": pos.get("current_persona_disagreement_index"),
            },
            "memory_context": memory_ctx,
        }
        alert_row.update(_sell_alert_plain_explanation(alert_row))
        alerts.append(alert_row)
    alerts = _apply_ollama_sell_explanations(alerts)
    active = [a for a in alerts if a.get("alert_level") != "NONE"]
    stale_quotes_count = len([a for a in alerts if _to_float(a.get("quote_age_seconds"), 0.0) > 45.0])
    fresh_quotes_count = len(
        [a for a in alerts if _to_float(a.get("quote_age_seconds"), -1.0) >= 0 and _to_float(a.get("quote_age_seconds"), 0.0) <= 20.0]
    )
    avg_quote_age_seconds = round(sum(freshness_values) / len(freshness_values), 2) if freshness_values else None
    payload = {
        "total_open_positions": len(open_trades),
        "active_sell_alerts": len(active),
        "sell_alert_quality_suite": {
            "action_priority_counts": action_priority_counts,
            "sell_now_count": int(action_priority_counts.get("sell_now", 0)),
            "trim_count": int(action_priority_counts.get("trim", 0)),
            "reduce_count": int(action_priority_counts.get("reduce", 0)),
            "hold_through_noise_count": int(action_priority_counts.get("hold_through_noise", 0)),
            "monitor_count": int(action_priority_counts.get("monitor", 0)),
            "avg_exit_signal_confidence": round(
                sum(_to_float(a.get("exit_signal_confidence"), 0.0) for a in alerts) / max(1, len(alerts)),
                2,
            ),
            "strongest_exit_trigger": str((active[0] or {}).get("strongest_exit_trigger") if active else "none"),
            "canonical_state_counts": {
                "active_position": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "active_position")),
                "tighten_stop": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "tighten_stop")),
                "trim": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "trim")),
                "exit": int(sum(1 for a in alerts if str((a or {}).get("canonical_position_decision_state") or "") == "exit")),
            },
        },
        "monitoring_summary": {
            "ws_overlay_applied_count": int(ws_overlay_count),
            "fresh_quotes_count": int(fresh_quotes_count),
            "stale_quotes_count": int(stale_quotes_count),
            "avg_quote_age_seconds": avg_quote_age_seconds,
        },
        "learned_thresholds": learned,
        "learned_thresholds_used": learned_used,
        "learning_exit_policy": learning_exit_policy,
        "alerts": alerts,
        "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
    }
    _CACHE["position_sell_alerts"] = {"data": dict(payload), "ts": time.time()}
    return payload


def _read_json_file(path, default=None):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except Exception:
        return {} if default is None else default


def _write_json_file_safely(path, payload):
    try:
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        tmp = f"{path}.tmp"
        with open(tmp, "w") as f:
            json.dump(payload, f, indent=2, sort_keys=True)
        os.replace(tmp, path)
        return True
    except Exception:
        return False


def _today_utc_key():
    try:
        return datetime.now(UTC).strftime("%Y-%m-%d")
    except Exception:
        return ""


