def _load_safe_learning_weights_v1():
    now = time.time()
    cache_age = now - _to_float(_SAFE_LEARNING_WEIGHTS_CACHE.get("ts"), 0.0)
    try:
        mtime = os.path.getmtime(SAFE_LEARNING_WEIGHTS_PATH)
    except Exception:
        mtime = 0.0
    if (
        isinstance(_SAFE_LEARNING_WEIGHTS_CACHE.get("payload"), dict)
        and cache_age <= _to_float(SAFE_LEARNING_WEIGHTS_TTL_SECONDS, 120.0)
        and abs(_to_float(_SAFE_LEARNING_WEIGHTS_CACHE.get("file_mtime"), 0.0) - _to_float(mtime, 0.0)) < 0.001
    ):
        return dict(_SAFE_LEARNING_WEIGHTS_CACHE.get("payload") or {})
    payload = _safe_read_json(SAFE_LEARNING_WEIGHTS_PATH, default={}) or {}
    _SAFE_LEARNING_WEIGHTS_CACHE["payload"] = dict(payload)
    _SAFE_LEARNING_WEIGHTS_CACHE["ts"] = now
    _SAFE_LEARNING_WEIGHTS_CACHE["file_mtime"] = _to_float(mtime, 0.0)
    return dict(payload)


