    meta = get_ranking_snapshot_meta()
    runtime_integrity = _runtime_integrity_status()
    quote_fallback = _system_status_quote_fallback()
    fallback_applied = bool(
        quote_fallback
        and int(meta.get("live_buy_valid_quote_count", 0) or 0) <= 0
        and int(quote_fallback.get("live_buy_valid_quote_count", 0) or 0) > 0
    )

    def _meta_count(key, default=0):
        raw = int(meta.get(key, default) or 0)
        if raw > 0:
            return raw
        return int(quote_fallback.get(key, default) or 0)

    attempted = int(meta.get("last_cycle_total_candidates", 0))
    scored = int(meta.get("last_cycle_scored_symbol_count", 0))
    skipped = max(0, attempted - scored)
    ws = ALPACA_WS_MONITOR.status()
