@router.get("/api/provider_usage_status_v1")
def provider_usage_status_v1(
    simulate_hard_stop: bool = Query(False),
    simulate_budget_exhausted: bool = Query(False),
    run_fmp_rest_live_test: bool = Query(False),
    force_live_test_refresh: bool = Query(False),
):
    _get_knowledge_promotion_summary(force=False)
    payload = dict(_fmp_usage_governor_snapshot(update=True) or {})
    def _load_last_fmp_test_state():
        raw = _read_json_file(FMP_REST_TEST_STATE_PATH, default={})
        if not isinstance(raw, dict):
            return {}
        if "fmp_rest_last_test_ok" in raw:
            return dict(raw)
        candidates = [dict(v) for v in raw.values() if isinstance(v, dict)]
        if not candidates:
            return {}
        candidates.sort(key=lambda x: str(x.get("ts_utc") or ""), reverse=True)
        chosen = dict(candidates[0])
        return {
            "fmp_rest_live_test_available": True,
            "fmp_rest_last_test_ok": bool(chosen.get("ok", False)),
            "fmp_rest_last_test_error": str(chosen.get("error") or ""),
            "fmp_rest_last_test_status_code": int(_to_float(chosen.get("status_code"), 0.0)),
            "fmp_rest_last_test_bytes": int(_to_float(chosen.get("bytes"), 0.0)),
            "fmp_rest_last_test_endpoint": str(chosen.get("endpoint") or ""),
            "fmp_rest_last_test_symbol": str(chosen.get("symbol") or "AAPL"),
            "fmp_rest_last_test_cached": True,
            "fmp_rest_last_test_timestamp_utc": str(chosen.get("ts_utc") or ""),
        }
    if bool(run_fmp_rest_live_test) and bool(payload.get("fmp_rest_activation_allowed", False)):
        test_out = _fmp_rest_controlled_test(
            symbol="AAPL",
            purpose="profile_context",
            force=bool(force_live_test_refresh),
        )
    else:
        test_out = _load_last_fmp_test_state()
    if bool(simulate_hard_stop or simulate_budget_exhausted):
        payload["fmp_warning_active"] = True
        payload["fmp_hard_stop_active"] = True
        payload["fmp_enabled"] = False
        payload["fmp_rest_governor_allowed"] = False
        payload["fmp_estimated_remaining_today_gb"] = 0.0
        payload["fmp_blocked_calls_today"] = int(_to_float(payload.get("fmp_blocked_calls_today"), 0.0)) + 1
        payload["simulated_budget_stop"] = True
        payload["simulated_stop_reason"] = "hard_stop" if bool(simulate_hard_stop) else "daily_budget_exhausted"
    payload["fmp_rest_activation_allowed"] = bool(payload.get("fmp_rest_activation_allowed", False) and not payload.get("fmp_hard_stop_active", False))
    payload["fmp_rest_activation_reason"] = str(payload.get("fmp_rest_activation_reason") or ("blocked_hard_stop" if payload.get("fmp_hard_stop_active", False) else "unknown"))
    payload["fmp_rest_live_test_available"] = bool(test_out.get("fmp_rest_live_test_available", False))
    payload["fmp_rest_last_test_ok"] = bool(test_out.get("fmp_rest_last_test_ok", False))
    payload["fmp_rest_last_test_error"] = str(test_out.get("fmp_rest_last_test_error") or "")
    payload["fmp_rest_last_test_status_code"] = int(_to_float(test_out.get("fmp_rest_last_test_status_code"), 0.0))
    payload["fmp_rest_last_test_bytes"] = int(_to_float(test_out.get("fmp_rest_last_test_bytes"), 0.0))
    payload["fmp_rest_last_test_endpoint"] = str(test_out.get("fmp_rest_last_test_endpoint") or "")
    payload["fmp_rest_last_test_symbol"] = str(test_out.get("fmp_rest_last_test_symbol") or "AAPL")
    payload["fmp_rest_last_test_cached"] = bool(test_out.get("fmp_rest_last_test_cached", False))
    payload["fmp_rest_last_test_timestamp_utc"] = str(test_out.get("fmp_rest_last_test_timestamp_utc") or "")
    payload["fmp_stable_profile_test_ok"] = bool(
        payload.get("fmp_rest_last_test_ok", False)
        and str(payload.get("fmp_rest_last_test_endpoint") or "").startswith("/stable/profile")
    )
    payload["fmp_stable_last_status_code"] = int(_to_float(payload.get("fmp_rest_last_test_status_code"), 0.0))
    payload["fmp_stable_last_error"] = str(payload.get("fmp_rest_last_test_error") or "")
    payload.update(_fmp_endpoint_compatibility_snapshot())
    payload["provider_usage_status_v1"] = True
    payload["knowledge_promotion_v1"] = _knowledge_promotion_public_block()
    payload["fmp_efficiency_v1"] = _fmp_efficiency_public_block()
    payload["generated_at"] = _now_utc_iso()
    return payload


