def _astra_master_il_direct_statuses_v1() -> dict:
    """Compose only the I-L facade dependencies for independent validation."""
    base = _astra_build_i_cached_statuses_v1()
    base["ask_astra_reliability_grounding_v1"] = ASTRA_ASK_ASTRA_RELIABILITY_GROUNDING.status(statuses=base, force=True)
    base["copilot_effectiveness_ranking_attribution_v2"] = ASTRA_COPILOT_EFFECTIVENESS_RANKING_ATTRIBUTION.status(statuses=base, force=True)
    base["build_i_final_validation_v1"] = ASTRA_BUILD_I_FINAL_VALIDATION.status(statuses=base, force=True)
    for key, value in _astra_build_j_direct_statuses_v1().items():
        if key not in base or not base.get(key):
            base[key] = value
    base["shadow_lifecycle_compression_retention_v1"] = ASTRA_SHADOW_LIFECYCLE_COMPRESSION_RETENTION.status(statuses=base, force=True)
    base["active_learning_evidence_gap_v1"] = ASTRA_ACTIVE_LEARNING_EVIDENCE_GAP.status(statuses=base, force=True)
    base["teaching_effectiveness_v1"] = ASTRA_TEACHING_EFFECTIVENESS.status(statuses=base, force=True)
    base["build_j_final_validation_v1"] = ASTRA_BUILD_J_FINAL_VALIDATION.status(statuses=base, force=True)
    for key, value in _astra_build_k_direct_statuses_v1().items():
        if key not in base or not base.get(key):
            base[key] = value
    base["astra_autonomous_safe_repair_v1"] = ASTRA_AUTONOMOUS_SAFE_REPAIR.status(statuses=base, force=True)
    base["astra_governance_oversight_v2"] = ASTRA_GOVERNANCE_OVERSIGHT_V2.status(statuses=base, force=True)
    base["build_k_final_validation_v1"] = ASTRA_BUILD_K_FINAL_VALIDATION.status(statuses=base, force=True)
    for key, value in _astra_build_l_direct_statuses_v1().items():
        if key not in base or not base.get(key):
            base[key] = value
    base["momentum_exit_readiness_loss_acceptance_v1"] = ASTRA_MOMENTUM_EXIT_READINESS_LOSS_ACCEPTANCE.status(statuses=base, force=True)
    base["horizon_capacity_turnover_research_v1"] = ASTRA_HORIZON_CAPACITY_TURNOVER_RESEARCH.status(statuses=base, force=True)
    base["historical_replay_multi_horizon_validation_v1"] = ASTRA_HISTORICAL_REPLAY_MULTI_HORIZON_VALIDATION.status(statuses=base, force=True)
    base["crypto_intelligence_separate_evidence_v2"] = ASTRA_CRYPTO_INTELLIGENCE_SEPARATE_EVIDENCE.status(statuses=base, force=True)
    base["build_l_final_validation_v1"] = ASTRA_BUILD_L_FINAL_VALIDATION.status(statuses=base, force=True)
    return base


def _pladeu_open_positions_from_cached_status_v1(statuses: dict) -> list[dict]:
    """Use only already-cached broker truth; never refresh a broker on GET."""
    broker = dict(statuses.get("alpaca_paper_broker") or {})
    for key in ("positions", "open_positions", "broker_positions", "paper_positions"):
        rows = broker.get(key)
        if isinstance(rows, list):
            return [dict(row) for row in rows[:100] if isinstance(row, dict)]
    return []


def _paper_autopilot_persisted_trace_v1() -> tuple[dict, str]:
    # The dedicated canonical worker runs out of process. Prefer its durable
    # checkpoint over an older API-process facade snapshot so read-only lane,
    # capacity, and lifecycle consumers agree on the same broker observation.
    try:
        with open(os.path.join(STATE, "paper_autopilot_state.json"), "r", encoding="utf-8") as handle:
            payload = json.load(handle)
        persisted_trace = dict(payload.get("last_execution_trace") or {}) if isinstance(payload, dict) else {}
        if persisted_trace.get("broker_position_review_rows") or persisted_trace.get("evidence_accumulation_capacity_v1"):
            return persisted_trace, "paper_autopilot_persisted_state"
    except Exception:
        pass
    trace = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("last_execution_trace") or {})
    if trace:
        return trace, "paper_autopilot_runtime"
    return {}, "paper_autopilot_unavailable"


def _evidence_accumulation_capacity_payload_v1(statuses: dict | None = None) -> dict:
    """Read the existing cached broker snapshot and build one capacity view."""
    def _stable_reserve_schema(snapshot: dict) -> dict:
        """Migrate cached pre-commitment snapshots without refreshing a broker."""
        out = dict(snapshot or {})
        lanes = dict(out.get("lanes") or {})
        for lane in ("day", "crypto"):
            view = dict(lanes.get(lane) or {})
            view.setdefault("open_position_count", int(_to_float(view.get("positions_used"), 0.0)))
            view.setdefault("pending_order_count", 0)
            view.setdefault("active_commitment_count", 0)
            view.setdefault("current_reserve_occupancy_count", int(_to_float(view.get("positions_used"), 0.0)))
            view.setdefault("reserve_state", view.get("capacity_decision") or "FAIL_CLOSED")
            view.setdefault("historical_entries_used", view.get("entries_used", 0))
            view.setdefault("historical_entries_remaining", view.get("entries_remaining"))
            view.setdefault("historical_entry_counts_advisory_only", True)
            lanes[lane] = view
            out[f"{lane}_open_positions"] = view["open_position_count"]
            out[f"{lane}_pending_orders"] = view["pending_order_count"]
            out[f"{lane}_active_commitments"] = view["active_commitment_count"]
            out[f"{lane}_positions_used"] = view.get("positions_used")
            out[f"{lane}_positions_remaining"] = view.get("positions_remaining")
            out[f"{lane}_reserve_available"] = bool(view.get("reserve_available", False))
            out[f"{lane}_reserve_state"] = view["reserve_state"]
        out["lanes"] = lanes
        out.setdefault("current_commitment_snapshot", {"commitment_state_owner": "PaperAutopilot", "active_commitments": 0, "by_lane": {"day": 0, "crypto": 0}, "records": [], "stats": {}})
        out.setdefault("pending_order_snapshot", {"broker_pending_orders": 0, "broker_orders_fetch_ok": False})
        return out

    current = dict(statuses or {})
    alpaca = _cached_alpaca_paper_status_payload(current)
    positions = _pladeu_open_positions_from_cached_status_v1({"alpaca_paper_broker": alpaca})
    worker_trace, worker_state_source = _paper_autopilot_persisted_trace_v1()
    worker_capacity = dict(worker_trace.get("evidence_accumulation_capacity_v1") or {})
    if worker_capacity.get("broker_reconciliation_status") == "FRESH":
        snapshot = _stable_reserve_schema(dict(worker_capacity))
        snapshot["position_source"] = worker_state_source
        snapshot["broker_observed_open_positions_count"] = int(_to_float(worker_trace.get("broker_open_positions_count"), _to_float(snapshot.get("total_open_positions"), 0.0)))
        snapshot["cache_only_no_broker_refresh_on_get"] = True
        snapshot["source_timestamp"] = snapshot.get("generated_at")
        return {**snapshot, **_safety_flags_v1()}
    worker_count = int(_to_float(worker_trace.get("broker_open_positions_count"), -1.0))
    fetch_ok = bool(
        alpaca.get("positions_preflight_ok")
        or alpaca.get("positions_fetch_ok")
        or ("positions" in alpaca and alpaca.get("broker_reconciliation_active") is True)
    )
    broker_snapshot = {
        "broker_reconciliation_active": bool(alpaca),
        "broker_positions_fetch_ok": fetch_ok,
        "generated_at": alpaca.get("generated_at") or alpaca.get("timestamp"),
        "broker_state_age_seconds": alpaca.get("broker_state_age_seconds"),
        "buying_power": alpaca.get("buying_power") or alpaca.get("available_buying_power"),
        "broker_state_stale": bool(alpaca.get("stale") or alpaca.get("cache_stale")),
        "broker_open_positions_count": worker_count if not alpaca and worker_count >= 0 else None,
        "position_details_available": bool(positions) or bool(alpaca.get("positions")),
    }
    if not alpaca and worker_count >= 0:
        broker_snapshot["broker_reconciliation_active"] = bool(worker_trace.get("broker_reconciliation_active", True))
        broker_snapshot["broker_positions_fetch_ok"] = bool(worker_trace.get("broker_positions_fetch_ok", True))
        broker_snapshot["generated_at"] = worker_trace.get("last_autopilot_cycle_at") or worker_trace.get("cycle_timestamp")
    account_snapshot = {
        "equity": alpaca.get("account_equity") or alpaca.get("equity"),
        "buying_power": alpaca.get("buying_power") or alpaca.get("available_buying_power"),
        "cash": alpaca.get("cash"),
        "open_orders_count": alpaca.get("open_orders_count"),
    }
    snapshot = build_capacity_snapshot(
        broker_snapshot=broker_snapshot,
        account_snapshot=account_snapshot,
        open_positions=positions,
        global_position_limit=int(_to_float(os.getenv("ASTRA_PAPER_GLOBAL_POSITION_LIMIT"), 10.0)),
        global_risk_allowed=True,
    )
    snapshot["position_source"] = "cached_alpaca_paper_status_v1" if alpaca else worker_state_source
    snapshot["broker_observed_open_positions_count"] = worker_count if worker_count >= 0 else None
    snapshot["cache_only_no_broker_refresh_on_get"] = True
    snapshot["source_timestamp"] = alpaca.get("generated_at") or alpaca.get("timestamp")
    return {**_stable_reserve_schema(snapshot), **_safety_flags_v1()}


def _portfolio_capacity_release_review_payload_v1(statuses: dict | None = None) -> dict:
    current = dict(statuses or {})
    positions = _pladeu_open_positions_from_cached_status_v1(current)
    worker_trace, _worker_source = _paper_autopilot_persisted_trace_v1()
    if not positions:
        positions = [
            dict(row) for row in (worker_trace.get("broker_position_review_rows") or [])
            if isinstance(row, dict)
        ][:100]
    snapshot = _evidence_accumulation_capacity_payload_v1(current)
    resolution_inventory = dict(snapshot.get("position_resolution_inventory_v1") or {})
    if not positions:
        positions = [
            dict(row) for row in (snapshot.get("position_rows_for_read_only_consumers") or [])
            if isinstance(row, dict)
        ][:100]
    review = build_portfolio_release_review(positions)
    if snapshot.get("broker_reconciliation_status") != "FRESH" or (
        int(_to_float(snapshot.get("total_open_positions"), 0.0)) > 0 and not positions
    ):
        review["position_data_status"] = "UNAVAILABLE_OR_STALE_BROKER_SNAPSHOT"
        review["position_data_blocker"] = "BROKER_STATE_STALE"
        review["total_positions"] = None
        review["positions_by_state"] = {state: None for state in ("KEEP", "WATCH", "PROTECT_PROFIT", "EXIT_REVIEW", "CONTROLLED_LOSS_ACCEPTABLE", "THESIS_BROKEN", "REPLACE_CANDIDATE", "DATA_INSUFFICIENT")}
        review["review_rows"] = []
        review["estimated_releasable_slots"] = None
    review["capacity_snapshot_id"] = snapshot.get("snapshot_id")
    review["capacity_status"] = snapshot.get("global_capacity_status")
    review["positions_by_lane"] = (
        {lane: sum(1 for row in review.get("review_rows", []) if str(row.get("lane_id") or "").upper() == lane) for lane in ("SWING", "DAY", "CRYPTO")}
        if snapshot.get("broker_reconciliation_status") == "FRESH"
        else {lane: None for lane in ("SWING", "DAY", "CRYPTO")}
    )
    review["human_review_groups"] = {
        state: [row.get("symbol") for row in review.get("review_rows", []) if row.get("state") == state]
        for state in ("KEEP", "WATCH", "PROTECT_PROFIT", "EXIT_REVIEW", "CONTROLLED_LOSS_ACCEPTABLE", "THESIS_BROKEN", "REPLACE_CANDIDATE", "DATA_INSUFFICIENT")
    }
    # Stable executive aliases keep consumers from parsing nested diagnostic
    # structures while preserving the existing detailed review payload.
    review["generated_at"] = _now_utc_iso()
    review["snapshot_id"] = snapshot.get("snapshot_id")
    review["total_positions_reviewed"] = review.get("total_positions")
    review["classification_counts"] = dict(review.get("positions_by_state") or {})
    review["positions"] = list(review.get("review_rows") or [])
    review["legacy_position_resolution_v1"] = resolution_inventory
    review["canonical_position_projection_owner"] = "PaperAutopilot._evidence_capacity_snapshot_v1"
    review["canonical_lifecycle_owner"] = "engine.astra_unified_position_lifecycle_v1.build_unified_position_lifecycle_decision_v1"
    review["legacy_resolution_is_approval_gated"] = True
    review["automatic_exits_enabled"] = False
    return {**review, **_safety_flags_v1()}


def _position_intelligence_summary_index_v1(filename: str) -> dict:
    return _astra_evidence_state_json(os.path.join("storage_summary_indexes", filename))


def _position_intelligence_bounded_jsonl_tail_v1(filename: str, *, max_bytes: int, max_rows: int) -> list[dict]:
    """Read a bounded local evidence window without scanning historical archives."""
    path = os.path.join(STATE, filename)
    if not os.path.exists(path):
        return []
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as handle:
            handle.seek(max(0, size - max_bytes))
            lines = handle.read().decode("utf-8", "ignore").splitlines()
        if size > max_bytes and lines:
            lines = lines[1:]
    except Exception:
        return []
    rows: list[dict] = []
    for line in lines[-max_rows:]:
        try:
            row = json.loads(line)
        except Exception:
            continue
        if isinstance(row, dict):
            rows.append(row)
    return rows


def _position_lineage_excursion_overlay_v1(positions: list[dict], registry_by_symbol: dict[str, dict]) -> tuple[dict[str, dict], dict]:
    """Recover only exact local links for the active-book advisory review.

    The broker registry establishes order ownership. Candidate and lifecycle
    ledgers are secondary evidence and cannot populate missing history unless
    their identifiers or tightly bounded entry attributes resolve uniquely.
    """
    candidate_rows = _position_intelligence_bounded_jsonl_tail_v1(
        "candidate_decision_ledger_v1.jsonl", max_bytes=2_000_000, max_rows=1500
    )
    lifecycle_rows = _position_intelligence_bounded_jsonl_tail_v1(
        "trade_lifecycle_excursion_v1.jsonl", max_bytes=8_000_000, max_rows=5000
    )
    lifecycle_by_symbol: dict[str, list[dict]] = defaultdict(list)
    for row in lifecycle_rows:
        symbol = str(row.get("symbol") or "").upper().strip()
        if symbol:
            lifecycle_by_symbol[symbol].append(row)
    overlays: dict[str, dict] = {}
    lineage_rows: list[dict] = []
    excursion_rows: list[dict] = []
    replacement_rows: list[dict] = []
    qualified_candidates = _cached_candidate_rows_for_horizon_flow_v1()
    now = datetime.now(UTC)
    for position in positions:
        symbol = str(position.get("symbol") or "").upper().strip()
        if not symbol:
            continue
        registry = dict(registry_by_symbol.get(symbol) or {})
        broker_join = {**position, **registry}
        lineage = reconstruct_position_lineage(broker_join, candidate_rows)
        source_record = dict(lineage.get("record") or {})
        source_thesis = source_record.get("thesis") or source_record.get("original_thesis") or source_record.get("entry_rationale")
        thesis_state = "THESIS_UNCONFIRMED" if source_thesis else "ORIGINAL_THESIS_NOT_RECOVERABLE"
        entry_time = _turnover_parse_timestamp_v1(registry.get("entry_timestamp") or position.get("entry_timestamp"))
        entry_price = _to_float(position.get("avg_entry_price") or registry.get("filled_avg_price"), 0.0)
        current_price = _to_float(position.get("current_price"), 0.0)
        matching_lifecycles: dict[str, dict] = {}
        for record in lifecycle_by_symbol.get(symbol, []):
            record_entry_time = _turnover_parse_timestamp_v1(record.get("entry_timestamp"))
            record_entry_price = _to_float(record.get("entry_price"), 0.0)
            if not entry_time or not record_entry_time or not entry_price or not record_entry_price:
                continue
            if abs((record_entry_time - entry_time).total_seconds()) > 300.0:
                continue
            if abs(record_entry_price - entry_price) / max(abs(entry_price), 0.01) > 0.015:
                continue
            lifecycle_key = str(record.get("lifecycle_id") or record.get("entry_timestamp") or id(record))
            matching_lifecycles[lifecycle_key] = record
        if len(matching_lifecycles) == 1:
            lifecycle_record = next(iter(matching_lifecycles.values()))
            source_time = _turnover_parse_timestamp_v1(
                lifecycle_record.get("last_update_timestamp") or lifecycle_record.get("current_timestamp") or lifecycle_record.get("generated_at")
            )
            age_hours = (now - source_time).total_seconds() / 3600.0 if source_time else None
            excursion = validate_excursion_record(
                lifecycle_record, entry_price=entry_price, current_price=current_price
            )
            if age_hours is not None and age_hours > 72.0 and excursion.get("status") == "BROKER_AND_MARKET_OBSERVED":
                excursion = {"status": "STALE_MARKET_HISTORY", "errors": ["lifecycle_record_older_than_72_hours"], "source_lifecycle_id": lifecycle_record.get("lifecycle_id")}
        elif len(matching_lifecycles) > 1:
            excursion = {"status": "AMBIGUOUS_ENTRY_TIMESTAMP", "errors": ["multiple_distinct_lifecycle_ids_match_entry"], "ambiguity_count": len(matching_lifecycles)}
        else:
            excursion = {"status": "INSUFFICIENT_PRICE_HISTORY", "errors": ["no_exact_bounded_lifecycle_match"]}
        return_pct = _to_float(position.get("unrealized_plpc"), 0.0) * 100.0
        days = _to_float(registry.get("days_held"), 0.0)
        return_per_day = round(return_pct / days, 4) if days > 0 else None
        replacement = replacement_analysis(
            {"symbol": symbol, "return_per_day": return_per_day}, qualified_candidates
        )
        is_dust = abs(_to_float(position.get("market_value"), 0.0)) < 0.01
        profit_trigger = (
            excursion.get("status") == "BROKER_AND_MARKET_OBSERVED"
            and _to_float(excursion.get("current_return_pct"), 0.0) > 0.0
            and _to_float(excursion.get("giveback_pct"), 0.0) > 0.5
            and _to_float(excursion.get("giveback_pct"), 0.0) / max(0.01, _to_float(excursion.get("peak_unrealized_profit_pct"), 0.0)) >= 0.4
            and str(lifecycle_record.get("follow_through_label") if len(matching_lifecycles) == 1 else "").lower() in {"weak_continuation", "failed_continuation", "stalled_after_entry"}
        )
        lineage_info = {
            "original_recommendation_id": source_record.get("recommendation_id"),
            "original_candidate_id": source_record.get("candidate_id") or source_record.get("decision_id"),
            "original_rank": source_record.get("rank"),
            "original_score": source_record.get("score"),
            "original_recommendation_action": source_record.get("action") or source_record.get("final_action"),
            "entry_rationale": source_record.get("entry_rationale"),
            "original_thesis": source_thesis,
            "strategy_archetype": source_record.get("strategy_archetype") or source_record.get("setup_type"),
            "trade_style": source_record.get("trade_style") or registry.get("intended_trade_style"),
            "intended_horizon": source_record.get("intended_horizon") or registry.get("intended_trade_style"),
            "lane": source_record.get("lane_id"),
            "recommendation_timestamp": source_record.get("timestamp_utc") or source_record.get("timestamp"),
            "order_timestamp": registry.get("created_at") or registry.get("broker_timestamp"),
            "fill_timestamp": registry.get("filled_at") or registry.get("entry_timestamp"),
            "source_store": "candidate_decision_ledger_v1.jsonl" if source_record else "broker_truth_records_v1.json",
            "reconstruction_method": lineage.get("reconstruction_method"),
            "reconstruction_confidence": lineage.get("reconstruction_confidence"),
            "ambiguity_count": lineage.get("ambiguity_count", 0),
            "conflicting_candidate_count": lineage.get("conflicting_candidate_count", 0),
            "broker_order_id": registry.get("broker_order_id"),
            "client_order_id": registry.get("client_order_id"),
            "fill_id": registry.get("fill_id"),
            "lifecycle_id": excursion.get("source_lifecycle_id"),
        }
        overlays[symbol] = {
            "lineage": lineage_info,
            "recommendation_lineage_status": lineage.get("reconstruction_confidence"),
            "thesis_state": thesis_state,
            "original_thesis": source_thesis,
            "excursion": excursion,
            "mfe": excursion.get("mfe_pct"),
            "mae": excursion.get("mae_pct"),
            "profit_giveback_pct": excursion.get("giveback_pct"),
            "capture_ratio": excursion.get("capture_ratio"),
            "return_per_day": return_per_day,
            "drawdown_adjusted_return_per_day": (round(return_per_day / max(1.0, 1.0 + abs(_to_float(excursion.get("mae_pct"), 0.0))), 4) if return_per_day is not None and excursion.get("status") == "BROKER_AND_MARKET_OBSERVED" else None),
            "profit_protection_trigger": profit_trigger,
            "opportunity_cost_state": "INSUFFICIENT_COMPARISON_EVIDENCE" if replacement.get("replacement_state") == "NO_ELIGIBLE_REPLACEMENT" else "MODERATE_OPPORTUNITY_COST" if _to_float(replacement.get("expected_advantage"), 0.0) >= 0.75 else "LOW_OPPORTUNITY_COST",
            "replacement_analysis": replacement,
            "replacement_candidate_id": (replacement.get("candidate") or {}).get("symbol"),
            "replacement_score": replacement.get("expected_advantage"),
            "replacement_fresh": replacement.get("replacement_state") in {"REPLACEMENT_ADVANTAGE_MODERATE", "REPLACEMENT_ADVANTAGE_HIGH"},
            "registry_reconciliation_status": "DUST_ANOMALY" if is_dust and not registry else "UNRESOLVED_EXTERNAL_BROKER_RESIDUE" if not registry else "BROKER_REGISTRY_LINKED",
            "missing_evidence": [
                value for value in (
                    "original_recommendation_not_recoverable" if not source_record else "",
                    "original_thesis_not_recoverable" if not source_thesis else "",
                    "excursion_" + str(excursion.get("status")).lower() if excursion.get("status") != "BROKER_AND_MARKET_OBSERVED" else "",
                    "no_eligible_replacement" if replacement.get("replacement_state") == "NO_ELIGIBLE_REPLACEMENT" else "",
                ) if value
            ],
        }
        lineage_rows.append({"symbol": symbol, **lineage_info, "lineage_status": lineage.get("status")})
        excursion_rows.append({"symbol": symbol, **excursion})
        replacement_rows.append({"symbol": symbol, **replacement})
    confidence_counts = Counter(str(row.get("reconstruction_confidence") or "NOT_RECOVERABLE") for row in lineage_rows)
    excursion_counts = Counter(str(row.get("status") or "INSUFFICIENT_PRICE_HISTORY") for row in excursion_rows)
    replacement_counts = Counter(str(row.get("replacement_state") or "INSUFFICIENT_REPLACEMENT_EVIDENCE") for row in replacement_rows)
    return overlays, {
        "lineage_rows": lineage_rows,
        "excursion_rows": excursion_rows,
        "replacement_rows": replacement_rows,
        "bounded_read": {
            "candidate_ledger_rows": len(candidate_rows),
            "lifecycle_rows": len(lifecycle_rows),
            "candidate_ledger_max_bytes": 2_000_000,
            "lifecycle_max_bytes": 8_000_000,
        },
        "coverage_by_confidence_class": dict(confidence_counts),
        "broker_registry_coverage": {
            "BROKER_LINKED_EXACT": sum(1 for position in positions if str(position.get("symbol") or "").upper() in registry_by_symbol),
            "UNRESOLVED_EXTERNAL_BROKER_RESIDUE": sum(1 for position in positions if str(position.get("symbol") or "").upper() not in registry_by_symbol),
            "note": "broker registry linkage proves order ownership, not original candidate recommendation or thesis lineage",
        },
        "coverage_by_excursion_class": dict(excursion_counts),
        "coverage_by_replacement_state": dict(replacement_counts),
    }


def _position_intelligence_context_v1(statuses: dict | None = None) -> tuple[dict, dict]:
    """Join bounded symbol-level evidence to a fresh broker position snapshot."""
    current = dict(statuses or {})
    broker = _cached_alpaca_paper_status_payload(current)
    positions = _pladeu_open_positions_from_cached_status_v1({"alpaca_paper_broker": broker})[:100]
    registry = _broker_truth_open_position_rows_v1()
    registry_by_symbol = {
        str(row.get("symbol") or "").upper(): dict(row)
        for row in (registry.get("aggregated_positions") or []) if isinstance(row, dict)
    }
    lineage_overlays, lineage_audit = _position_lineage_excursion_overlay_v1(positions, registry_by_symbol)
    profiles = dict(_astra_evidence_state_json("symbol_behavior_profiles_v1.json").get("profiles") or {})
    candidates = {
        str(row.get("symbol") or row.get("ticker") or "").upper(): dict(row)
        for row in _cached_candidate_rows_for_horizon_flow_v1() if isinstance(row, dict)
    }
    lifecycle = _position_intelligence_summary_index_v1("trade_lifecycle_excursion_v2.jsonl.summary_index.json")
    replay = _position_intelligence_summary_index_v1("replay_counterfactual_learning_v2.jsonl.summary_index.json")
    candidate_index = _position_intelligence_summary_index_v1("candidate_decision_ledger_v1.jsonl.summary_index.json")
    opportunity = _position_intelligence_summary_index_v1("opportunity_cost_learning_v1.jsonl.summary_index.json")
    lifecycle_symbols = {str(key).upper(): int(_to_float(value, 0.0)) for key, value in ((lifecycle.get("dimension_counts") or {}).get("symbol") or {}).items()}
    replay_symbols = {str(key).upper(): int(_to_float(value, 0.0)) for key, value in ((replay.get("dimension_counts") or {}).get("symbol") or {}).items()}
    candidate_symbols = {str(key).upper(): int(_to_float(value, 0.0)) for key, value in ((candidate_index.get("dimension_counts") or {}).get("symbol") or {}).items()}
    opportunity_symbols = {str(key).upper(): int(_to_float(value, 0.0)) for key, value in ((opportunity.get("dimension_counts") or {}).get("symbol") or {}).items()}
    context_by_symbol: dict[str, dict] = {}
    coverage_rows: list[dict] = []
    for position in positions:
        symbol = str(position.get("symbol") or "").upper().strip()
        if not symbol:
            continue
        registry_row = dict(registry_by_symbol.get(symbol) or {})
        overlay = dict(lineage_overlays.get(symbol) or {})
        profile = dict(profiles.get(symbol) or {})
        candidate = dict(candidates.get(symbol) or {})
        lifecycle_count = int(lifecycle_symbols.get(symbol, 0))
        replay_count = int(replay_symbols.get(symbol, 0))
        candidate_count = int(candidate_symbols.get(symbol, 0))
        opportunity_count = int(opportunity_symbols.get(symbol, 0))
        # A current candidate row is useful context for a future replacement
        # review, but it is not proof of the original recommendation that
        # opened this broker position.  Keep that distinction explicit.
        observed_horizon = str(
            registry_row.get("intended_trade_style")
            if registry_row.get("intended_trade_style") not in (None, "", "unknown")
            else registry_row.get("actual_horizon_classification") or ""
        ).lower()
        excursion = dict(overlay.get("excursion") or {})
        replacement = dict(overlay.get("replacement_analysis") or {})
        linked = {
            "broker_truth": True,
            "recommendation_lineage": bool((overlay.get("lineage") or {}).get("original_recommendation_id")),
            "horizon_lifecycle": bool(observed_horizon),
            "symbol_behavior": bool(profile),
            "lifecycle": lifecycle_count > 0,
            "replay": replay_count > 0,
            "candidate_history": candidate_count > 0,
            "opportunity_cost": opportunity_count > 0 and symbol != "UNKNOWN",
            "mfe_mae": excursion.get("status") == "BROKER_AND_MARKET_OBSERVED",
            "thesis": bool(overlay.get("original_thesis")),
            "regime": False,
            "catalyst": False,
        }
        missing_evidence = [name for name in ("recommendation_lineage", "horizon_lifecycle", "mfe_mae", "opportunity_cost", "thesis") if not linked[name]]
        supporting_count = sum(1 for value in linked.values() if value)
        coverage = "COMPLETE_LINEAGE" if all(linked[name] for name in ("broker_truth", "recommendation_lineage", "horizon_lifecycle", "symbol_behavior", "lifecycle")) else "PARTIAL_LINEAGE" if supporting_count > 1 else "BROKER_ONLY"
        context_by_symbol[symbol] = {
            "entry_timestamp": registry_row.get("entry_timestamp"),
            "intended_trade_style": observed_horizon if linked["horizon_lifecycle"] else None,
            "horizon_source": (registry_row.get("source") if registry_row.get("intended_trade_style") not in (None, "", "unknown") else "broker_registry_observed_age_classification") if linked["horizon_lifecycle"] else None,
            "lane_id": ({"scalp": "SCALP", "day_trade": "DAY", "swing_trade": "SWING", "short_swing": "SWING", "standard_swing": "SWING", "extended_swing": "SWING"}.get(observed_horizon) if linked["horizon_lifecycle"] else None),
            "expected_hold_duration_days": registry_row.get("expected_hold_days_for_intended_style"),
            "days_held": registry_row.get("days_held"),
            "horizon_expired": bool(registry_row.get("horizon_status") == "horizon_mismatch"),
            "historical_similarity": "linked_symbol_lifecycle_summary" if lifecycle_count else None,
            "replay_evidence": "linked_symbol_replay_summary" if replay_count else None,
            "symbol_behavior": profile or None,
            "symbol_profile": profile or None,
            "symbol_evidence_count": int(_to_float(profile.get("sample_size"), 0.0)),
            "evidence_confidence": profile.get("profile_confidence"),
            "current_candidate_context_available": bool(candidate),
            "current_candidate_context": {
                "symbol": candidate.get("symbol") or candidate.get("ticker"),
                "score": candidate.get("score") or candidate.get("confidence"),
                "rank": candidate.get("rank"),
                "timestamp": candidate.get("generated_at") or candidate.get("timestamp"),
            } if candidate else None,
            **overlay,
            "lineage": {
                "position_link_key": position.get("asset_id") or symbol,
                "broker_order_id": registry_row.get("broker_order_id"),
                "client_order_id": registry_row.get("client_order_id"),
                "recommendation_id": (overlay.get("lineage") or {}).get("original_recommendation_id"),
                "lifecycle_id": (overlay.get("lineage") or {}).get("lifecycle_id") or registry_row.get("stable_key"),
                "lane_id": (overlay.get("lineage") or {}).get("lane"),
                **dict(overlay.get("lineage") or {}),
            },
            "retrieval": {"coverage": coverage, "linked_sources": [name for name, value in linked.items() if value]},
            "missing_evidence": list(dict.fromkeys(missing_evidence + list(overlay.get("missing_evidence") or []))),
        }
        evidence_condition = {
            "historical_lineage": "missing_historical_lineage" if not linked["recommendation_lineage"] else "linked",
            "horizon": "identifier_mismatch_or_missing_registry_record" if not linked["horizon_lifecycle"] and not registry_row else "missing_horizon" if not linked["horizon_lifecycle"] else "linked",
            "mfe_mae": excursion.get("status") or ("detailed_lifecycle_retrieval_not_available" if lifecycle_count else "missing_lifecycle_evidence"),
            "opportunity_cost": overlay.get("opportunity_cost_state") or ("index_symbol_dimension_unavailable" if opportunity.get("source_available") else "index_unavailable"),
            "replacement": replacement.get("replacement_state") or "INSUFFICIENT_REPLACEMENT_EVIDENCE",
        }
        coverage_rows.append({"symbol": symbol, "coverage": coverage, "linked_sources": [name for name, value in linked.items() if value], "missing_evidence": missing_evidence, "evidence_condition": evidence_condition, "lifecycle_count": lifecycle_count, "replay_count": replay_count, "candidate_history_count": candidate_count, "registry_match": bool(registry_row)})
    source_metadata = {
        "lifecycle_index": bool(lifecycle.get("source_available")),
        "replay_index": bool(replay.get("source_available")),
        "candidate_index": bool(candidate_index.get("source_available")),
        "opportunity_cost_index": bool(opportunity.get("source_available")),
    }
    return context_by_symbol, {
        "positions": coverage_rows,
        "source_metadata": source_metadata,
        "broker_registry_symbols": len(registry_by_symbol),
        "positions_with_complete_lineage": sum(1 for row in coverage_rows if row.get("coverage") == "COMPLETE_LINEAGE"),
        "positions_with_partial_lineage": sum(1 for row in coverage_rows if row.get("coverage") == "PARTIAL_LINEAGE"),
        "positions_with_broker_only_evidence": sum(1 for row in coverage_rows if row.get("coverage") == "BROKER_ONLY"),
        "positions_missing_horizon": sum(1 for row in coverage_rows if "horizon_lifecycle" in (row.get("missing_evidence") or [])),
        "positions_missing_thesis": sum(1 for row in coverage_rows if "thesis" in (row.get("missing_evidence") or [])),
        "positions_missing_mfe_mae": sum(1 for row in coverage_rows if "mfe_mae" in (row.get("missing_evidence") or [])),
        "positions_missing_opportunity_cost": sum(1 for row in coverage_rows if "opportunity_cost" in (row.get("missing_evidence") or [])),
        "positions_missing_replacement_analysis": sum(1 for row in coverage_rows if (context_by_symbol.get(row.get("symbol")) or {}).get("replacement_analysis", {}).get("replacement_state") == "NO_ELIGIBLE_REPLACEMENT"),
        "identifier_mismatch_count": sum(1 for row in coverage_rows if not row.get("registry_match")),
        "lineage_excursion_reconstruction_v1": lineage_audit,
    }


def _position_intelligence_utilization_payload_v1(statuses: dict | None = None, *, persist: bool = False) -> dict:
    current = dict(statuses or {})
    broker = _cached_alpaca_paper_status_payload(current)
    positions = [dict(row) for row in (broker.get("positions") or []) if isinstance(row, dict)][:100]
    contexts, retrieval = _position_intelligence_context_v1(current)
    review = build_portfolio_release_review(positions, contexts)
    rows = list(review.get("review_rows") or [])
    action_queue = dict(review.get("action_queue") or {})
    profiles = {symbol: dict(context.get("symbol_profile") or {}) for symbol, context in contexts.items()}
    roi_rows = []
    profit_rows = []
    for row in rows:
        symbol = str(row.get("symbol") or "").upper()
        snapshot = dict(row.get("position_snapshot") or {})
        context = dict(contexts.get(symbol) or {})
        days = _to_float(context.get("days_held"), 0.0)
        pnl_pct = snapshot.get("unrealized_pnl_pct")
        pnl_pct = _to_float(pnl_pct, 0.0) * 100.0 if pnl_pct is not None and abs(_to_float(pnl_pct, 0.0)) <= 2.0 else pnl_pct
        return_per_day = context.get("return_per_day")
        if return_per_day is None:
            return_per_day = round(_to_float(pnl_pct, 0.0) / days, 4) if days > 0 and pnl_pct is not None else None
        profile = profiles.get(symbol) or {}
        profile_sample = int(_to_float(profile.get("sample_size"), 0.0))
        profile_giveback = profile.get("giveback_average")
        excursion = dict(context.get("excursion") or {})
        if bool(context.get("profit_protection_trigger")):
            profit_state = "PROTECT_PROFIT"
        elif pnl_pct is not None and _to_float(pnl_pct, 0.0) > 0 and profile_sample >= 10 and _to_float(profile_giveback, 0.0) >= 50.0:
            profit_state = "WATCH_PROFIT_GIVEBACK"
        elif pnl_pct is not None and _to_float(pnl_pct, 0.0) > 0:
            profit_state = "LET_WINNER_RUN"
        else:
            profit_state = "INSUFFICIENT_EVIDENCE"
        replacement = dict(context.get("replacement_analysis") or {})
        roi_rows.append({
            "symbol": symbol,
            "unrealized_return_pct": pnl_pct,
            "holding_days": days if days > 0 else None,
            "return_per_calendar_day": return_per_day,
            "return_per_trading_day": return_per_day,
            "capital_occupied": snapshot.get("market_value"),
            "drawdown_adjusted_return_per_day": context.get("drawdown_adjusted_return_per_day"),
            "expected_forward_return_per_day": None,
            "opportunity_cost_assessment": context.get("opportunity_cost_state") or "INSUFFICIENT_COMPARISON_EVIDENCE",
            "replacement_state": replacement.get("replacement_state") or "INSUFFICIENT_REPLACEMENT_EVIDENCE",
            "replacement_candidate": replacement.get("candidate"),
            "replacement_evidence_status": replacement.get("reason") or "no_eligible_linked_replacement_in_cache",
        })
        profit_rows.append({"symbol": symbol, "profit_capture_state": profit_state, "current_giveback_available": excursion.get("status") == "BROKER_AND_MARKET_OBSERVED", "mfe_pct": excursion.get("mfe_pct"), "mae_pct": excursion.get("mae_pct"), "giveback_pct": excursion.get("giveback_pct"), "capture_ratio": excursion.get("capture_ratio"), "symbol_giveback_profile": profile_giveback if profile_sample else None, "profile_sample_size": profile_sample, "advisory_only": True})
    lane_profiles: dict[str, list[dict]] = {"scalp": [], "day_trade": [], "swing_trade": []}
    for profile in profiles.values():
        horizon = str(profile.get("best_horizon") or "").lower()
        lane = "scalp" if horizon == "scalp" else "day_trade" if horizon == "day_trade" else "swing_trade"
        lane_profiles[lane].append(profile)
    envelopes = {}
    strategy_rows = []
    for lane, lane_rows in lane_profiles.items():
        evidence = sum(int(_to_float(row.get("sample_size"), 0.0)) for row in lane_rows)
        information_value = round(max(0.0, 100.0 - min(100.0, evidence)), 2)
        strategy_state = "EXPLOIT_PROVEN_EDGE" if evidence >= 50 else "EXPLORE_UNDERSAMPLED_SETUP" if evidence >= 10 else "SHADOW_ONLY_EXPERIMENT"
        envelopes[lane] = {
            "status": "RECONSTRUCTED_SUPPORTED" if evidence >= 20 else "PROVISIONAL",
            "evidence_count": evidence,
            "expected_opportunity_count": None,
            "expected_win_rate_range": None,
            "expected_profit_factor_range": None,
            "expected_return_range": None,
            "expected_drawdown_range": None,
            "confidence": round(min(80.0, evidence / 2.0), 2),
            "regime_compatibility": "symbol_profile_context_only",
            "strongest_setup_types": [],
            "weakest_setup_types": [],
            "likely_failure_modes": ["broker_calibrated_outcomes_not_yet_available"],
        }
        strategy_rows.append({
            "lane": lane,
            "strategy_state": strategy_state,
            "evidence_count": evidence,
            "expected_risk_adjusted_value": None,
            "information_value": information_value,
            "trading_profit_claim_available": False,
            "human_review_required": True,
        })
    producer_specs = [
        ("broker_truth", "alpaca_paper_status_v1.positions", "ACTIVE_AND_CONSUMED"),
        ("candidate_ranking", "candidate_decision_ledger_v1.summary_index", "AVAILABLE_NOT_LINKED"),
        ("copilot_ranking", "astra_copilot_suite_v1", "DIAGNOSTIC_ONLY"),
        ("recommendation_lineage", "broker_truth_records_v1 + original recommendation record", "MISSING"),
        ("trade_style_assignment", "broker_truth_records_v1", "ACTIVE_AND_CONSUMED"),
        ("intended_horizon", "broker_truth_records_v1", "ACTIVE_AND_CONSUMED"),
        ("horizon_lifecycle", "broker_truth_records_v1 + lifecycle summary index", "ACTIVE_AND_CONSUMED"),
        ("momentum_state", "position/candidate context", "AVAILABLE_NOT_LINKED"),
        ("thesis_state", "original recommendation lineage", "MISSING"),
        ("market_regime", "cached market context", "AVAILABLE_NOT_LINKED"),
        ("breadth", "market breadth cache", "AVAILABLE_NOT_LINKED"),
        ("sector_rotation", "sector rotation cache", "AVAILABLE_NOT_LINKED"),
        ("catalyst_intelligence", "catalyst context cache", "AVAILABLE_NOT_LINKED"),
        ("fundamentals", "provider-backed cached symbol context", "AVAILABLE_NOT_LINKED"),
        ("symbol_behavior", "symbol_behavior_profiles_v1", "ACTIVE_AND_CONSUMED"),
        ("historical_similarity", "trade_lifecycle_excursion_v2.summary_index", "ACTIVE_AND_CONSUMED"),
        ("replay_evidence", "replay_counterfactual_learning_v2.summary_index", "ACTIVE_AND_CONSUMED"),
        ("shadow_evidence", "realistic_shadow_evidence_learning_lab_v1", "SHADOW_ONLY"),
        ("reconstructed_lifecycle", "historical_lifecycle_reconstruction_v1", "DIAGNOSTIC_ONLY"),
        ("mfe_mae", "trade_lifecycle_excursion_v2 detailed rows", "MISSING"),
        ("time_to_peak", "trade_lifecycle_excursion_v2 detailed rows", "MISSING"),
        ("profit_giveback", "symbol_behavior_profiles_v1", "ACTIVE_AND_CONSUMED"),
        ("return_per_day", "broker_truth_records_v1 + fresh broker prices", "ACTIVE_AND_CONSUMED"),
        ("position_age", "broker_truth_records_v1", "ACTIVE_AND_CONSUMED"),
        ("time_below_entry", "broker history/lifecycle detail", "MISSING"),
        ("opportunity_cost", "opportunity_cost_learning_v1.summary_index", "AVAILABLE_NOT_LINKED"),
        ("replacement_candidate_quality", "cached eligible candidate comparison", "MISSING"),
        ("concentration_correlation", "portfolio risk cache", "AVAILABLE_NOT_LINKED"),
        ("liquidity_spread", "market data cache", "AVAILABLE_NOT_LINKED"),
        ("entry_quality", "candidate lineage + execution evidence", "MISSING"),
        ("exit_readiness", "exit_readiness_diagnostics_v1", "DIAGNOSTIC_ONLY"),
        ("governance", "astra_governance_oversight_v1", "ACTIVE_AND_CONSUMED"),
    ]
    linked_source_names = {
        "trade_style_assignment": "horizon_lifecycle",
        "intended_horizon": "horizon_lifecycle",
        "horizon_lifecycle": "horizon_lifecycle",
        "historical_similarity": "lifecycle",
        "replay_evidence": "replay",
        "profit_giveback": "symbol_behavior",
    }
    return_per_day_coverage = sum(1 for row in roi_rows if row.get("return_per_calendar_day") is not None)

    def _producer_coverage(source: str) -> int:
        if source == "return_per_day":
            return return_per_day_coverage
        if source == "position_age":
            return sum(1 for row in roi_rows if row.get("holding_days") is not None)
        if source == "governance":
            return len(rows)
        linked_name = linked_source_names.get(source, source.replace("_evidence", ""))
        return sum(1 for item in retrieval.get("positions") or [] if linked_name in (item.get("linked_sources") or []))

    producer_audit = [
        {
            "source": name, "canonical_store": store, "classification": state,
            "freshness": "fresh_broker_snapshot" if name == "broker_truth" else "bounded_cached_evidence",
            "symbol_coverage": _producer_coverage(name),
            "position_linkage_key": "symbol", "current_consumer": "portfolio_capacity_release_review_v1" if state.startswith("ACTIVE") else None,
            "expected_consumer": "position_monitoring_and_advisory_review", "active_influence_field": name if state.startswith("ACTIVE") else None,
            "acknowledgement": "position_intelligence_utilization_v1", "outcome_attribution_path": "advisory_decision_record", "reason": "bounded_symbol_join" if state.startswith("ACTIVE") else "no_current_symbol_level_link_or_required_field",
        }
        for name, store, state in producer_specs
    ]
    decision_records = [
        {
            "decision_id": f"position-intel:{row.get('symbol')}:{str(broker.get('generated_at') or '')[:10]}",
            "symbol": row.get("symbol"), "lane": row.get("lane_id"), "timestamp": broker.get("generated_at"),
            "original_decision": row.get("primary_state"), "supporting_intelligence": [name for name, state in (row.get("decision_influence") or {}).items() if state == "ACTIVE_CONSUMER"],
            "confidence": row.get("evidence_confidence"), "action_taken": "ADVISORY_ONLY_NO_EXECUTION", "later_actual_outcome": None,
            "counterfactual_outcome": None, "official_broker_metric_eligible": False,
        }
        for row in rows
    ]
    capacity = _evidence_accumulation_capacity_payload_v1(current)
    governance = dict(current.get("astra_governance_oversight_v1") or {})
    capacity_recommendation = "FAIL_CLOSED" if int(_to_float(capacity.get("total_open_positions"), len(rows))) >= int(_to_float(capacity.get("total_capacity"), 20.0)) or int(_to_float(governance.get("high_findings_count"), 0.0)) > 0 else "LIMITED"
    persistence = {"persisted": False, "mode": "bounded_payload_and_cache", "records": len(decision_records)}
    if persist:
        path = os.path.join(STATE, "position_intelligence_utilization_audit_v1.jsonl")
        try:
            with open(path, "a", encoding="utf-8") as handle:
                handle.write(json.dumps({"generated_at": _now_utc_iso(), "broker_snapshot": broker.get("generated_at"), "decision_records": decision_records, "coverage": review.get("retrieval_coverage")}, separators=(",", ":"), default=str) + "\n")
            persistence = {"persisted": True, "mode": "explicit_force_audit_append_only", "path": "state/position_intelligence_utilization_audit_v1.jsonl", "records": len(decision_records)}
        except Exception as exc:
            persistence = {"persisted": False, "mode": "persistence_unavailable", "error": str(exc)[:120], "records": len(decision_records)}
    lineage_audit = dict(retrieval.get("lineage_excursion_reconstruction_v1") or {})
    return {
        "endpoint": "/api/astra_position_intelligence_utilization_v1",
        "status": "PASS_WITH_WARNINGS" if rows else "INSUFFICIENT_EVIDENCE",
        "generated_at": _now_utc_iso(),
        "broker_snapshot": {"authoritative": broker.get("broker_snapshot_status") == "FRESH_READ_ONLY", "generated_at": broker.get("generated_at"), "open_positions": len(positions)},
        "producer_to_consumer_audit": producer_audit,
        "position_retrieval_coverage": {**retrieval, **dict(review.get("retrieval_coverage") or {})},
        "portfolio_review": review,
        "roi_capital_efficiency": {"positions": roi_rows, "return_per_day_available_count": sum(1 for row in roi_rows if row.get("return_per_calendar_day") is not None), "expected_forward_values_available": 0},
        "profit_capture_advisory": {"positions": profit_rows, "automatic_exits_enabled": False},
        "position_lineage_excursion_replacement_v1": {
            "status": "PASS_WITH_WARNINGS" if rows else "INSUFFICIENT_EVIDENCE",
            "lineage": lineage_audit.get("lineage_rows") or [],
            "excursions": lineage_audit.get("excursion_rows") or [],
            "replacements": lineage_audit.get("replacement_rows") or [],
            "bounded_read": lineage_audit.get("bounded_read") or {},
            "coverage_by_confidence_class": lineage_audit.get("coverage_by_confidence_class") or {},
            "broker_registry_coverage": lineage_audit.get("broker_registry_coverage") or {},
            "coverage_by_excursion_class": lineage_audit.get("coverage_by_excursion_class") or {},
            "coverage_by_replacement_state": lineage_audit.get("coverage_by_replacement_state") or {},
            "thesis_recovery_status": {
                "recovered": sum(1 for row in rows if row.get("original_thesis")),
                "not_recoverable": sum(1 for row in rows if row.get("thesis_status") == "ORIGINAL_THESIS_NOT_RECOVERABLE"),
            },
            "broker_actions_used": 0,
            "provider_calls_used": 0,
            "llm_calls_used": 0,
            **_safety_flags_v1(),
        },
        "bounded_consumers": [
            {"consumer": "position_monitoring_priority", "previous_state": "broker_only_classification", "new_state": "ACTIVE_ADVISORY", "maximum_influence_pct": 100.0, "confidence_requirement": "linked_broker_truth", "evidence_requirement": "symbol_level_link", "governance_gate": "human_review_required", "rollback_trigger": "retrieval_conflict", "review_period": "each_fresh_audit", "outcome_attribution": "decision_records"},
            {"consumer": "profit_protection_advisory", "previous_state": "profile_not_joined", "new_state": "ACTIVE_ADVISORY", "maximum_influence_pct": 100.0, "confidence_requirement": "profile_sample>=10", "evidence_requirement": "positive_current_pnl_and_symbol_profile", "governance_gate": "no_exit_execution", "rollback_trigger": "profile_link_missing", "review_period": "each_fresh_audit", "outcome_attribution": "decision_records"},
            {"consumer": "candidate_priority_tie_break", "previous_state": "not_consumed", "new_state": "DRY_RUN_ONLY", "maximum_influence_pct": 3.0, "confidence_requirement": "validated_symbol_linkage", "evidence_requirement": "future_outcome_attribution", "governance_gate": "ranking_unchanged", "rollback_trigger": "any_ranking_contract_difference", "review_period": "human_approved_future_review", "outcome_attribution": "shadow_comparison_only"},
        ],
        "strategy_selection": {
            "status": "ADVISORY_EVIDENCE_ROUTING_ONLY",
            "labels": ["EXPLOIT_PROVEN_EDGE", "EXPLORE_UNDERSAMPLED_SETUP", "SHADOW_ONLY_EXPERIMENT", "PAPER_CANARY_ELIGIBLE", "DEPRIORITIZE_LOW_EXPECTANCY", "RETIRE_OR_REDESIGN_SETUP"],
            "lanes": strategy_rows,
            "active_strategy_change": False,
            "reason": "information value is tracked separately from profit because broker-calibrated lane outcomes remain insufficient",
        },
        "forward_performance_envelope_by_lane": envelopes,
        "dynamic_capacity_advisory": {"recommendation": capacity_recommendation, "automatic_capacity_change": False, "capacity_snapshot": capacity.get("snapshot_id"), "governance_high_findings": governance.get("high_findings_count", 0)},
        "decision_impact_measurement": {"records": decision_records, "intelligence_utilization_rate": round(sum(1 for row in rows if len([value for value in (row.get("decision_influence") or {}).values() if value == "ACTIVE_CONSUMER"]) > 1) / max(1, len(rows)) * 100.0, 3), "positions_with_multi_source_intelligence": sum(1 for row in rows if len([value for value in (row.get("decision_influence") or {}).values() if value == "ACTIVE_CONSUMER"]) > 1), "recommendation_helpfulness_rate": None, "expected_vs_actual_calibration": None, "improvement_claimed": False, "persistence": persistence},
        "provider_calls_used": 0, "broker_actions_used": 0, "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


def _pladeu_direct_statuses_v1(force: bool = False) -> dict:
    """Compose PLADEU from bounded local state, never the full I-L validator.

    The master I-L validator is intentionally broad and is useful for a deep
    audit, but calling it from each PLADEU endpoint made otherwise cache-first
    diagnostics slow.  This direct path uses the existing unified cache and
    cached broker payload only.
    """
    unified_cache = _CACHE.get("unified_learning_diagnostics_v1") if isinstance(_CACHE.get("unified_learning_diagnostics_v1"), dict) else {}
    base = dict((unified_cache or {}).get("data") or {})
    if not base:
        try:
            with open(os.path.join(STATE, "dashboard_cache", "unified_learning_diagnostics_v1.json"), "r", encoding="utf-8") as handle:
                cached_payload = json.load(handle)
            base = dict(cached_payload) if isinstance(cached_payload, dict) else {}
        except Exception:
            base = {}
    if force:
        # Keep the explicit audit path authoritative while leaving ordinary
        # dashboard composition cache-first.  The broker helper performs only
        # bounded paper account, position, and open-order reads.
        try:
            fresh_alpaca = alpaca_paper_status_v1(force=True)
            if isinstance(fresh_alpaca, dict):
                base["alpaca_paper_status_v1"] = dict(fresh_alpaca)
                base["alpaca_paper_broker"] = dict(fresh_alpaca)
        except Exception:
            pass
    if not base.get("alpaca_paper_broker"):
        base["alpaca_paper_broker"] = _cached_alpaca_paper_status_payload(base) or _alpaca_paper_status_fast_fallback_v1("pladeu_cache_first")
    base["authoritative_broker_truth"] = _canonical_broker_truth_counts_v1(base)
    base["pladeu_candidate_source_metadata"] = _pladeu_candidate_source_metadata_v1()
    base["day_lane_pilot_config"] = _day_lane_pilot_config_v1()
    try:
        raw_candidates = _cached_candidate_rows_for_horizon_flow_v1()[:300]
        base["pladeu_candidate_rows"] = PAPER_OPPORTUNITY_ALLOCATION_ENGINE.decorate_candidates(raw_candidates)
    except Exception:
        base["pladeu_candidate_rows"] = []
    base["pladeu_open_positions"] = _pladeu_open_positions_from_cached_status_v1(base)
    base["evidence_accumulation_capacity_v1"] = _evidence_accumulation_capacity_payload_v1(base)
    base["portfolio_capacity_release_review_v1"] = _portfolio_capacity_release_review_payload_v1(base)
    try:
        base["pladeu_day_lane_allocation"] = PAPER_OPPORTUNITY_ALLOCATION_ENGINE.day_lane_governance(
            rows=base["pladeu_candidate_rows"], open_positions=base["pladeu_open_positions"]
        )
    except Exception:
        base["pladeu_day_lane_allocation"] = {}
    base["trade_lane_registry"] = ASTRA_TRADE_LANE_REGISTRY.status(statuses=base, force=bool(force))
    base["historical_reconstruction"] = ASTRA_HISTORICAL_LIFECYCLE_RECONSTRUCTION.status(statuses=base, force=bool(force))
    base["evidence_ladder"] = PAPER_LEARNING_EVIDENCE_LADDER.status(statuses=base, force=bool(force))
    base["lifecycle_satellite"] = TRADE_LIFECYCLE_PROFIT_CAPTURE_SATELLITE.status(statuses=base, force=bool(force))
    base["day_lane_governor"] = DAY_LANE_DIVERSITY_GOVERNOR.status(statuses=base, force=bool(force))
    base["day_lane_pilot_readiness_v1"] = _day_lane_pilot_readiness_payload_v1(base)
    base["multilane_paper_operational_status_v1"] = _multilane_paper_operational_status_v1_payload(base)
    base["learning_return_integrity_v1"] = _learning_return_integrity_v1_payload()
    base["pladeu_phase1_lane_validation_v1"] = PLADEU_PHASE1_LANE_VALIDATION.status(statuses=base, force=bool(force))
    base["pladeu_phase2_reconstruction_validation_v1"] = PLADEU_PHASE2_RECONSTRUCTION_VALIDATION.status(statuses=base, force=bool(force))
    base["pladeu_phase3_learning_validation_v1"] = PLADEU_PHASE3_LEARNING_VALIDATION.status(statuses=base, force=bool(force))
    base["pladeu_phase4_runtime_validation_v1"] = PLADEU_PHASE4_RUNTIME_VALIDATION.status(statuses=base, force=bool(force))
    base["pladeu_master_validation"] = PLADEU_MASTER_VALIDATION.status(statuses=base, force=bool(force))
    return base


def _attach_pladeu_statuses_v1(statuses: dict, force: bool = False) -> dict:
    """Attach compact PLADEU summaries to unified diagnostics from caches only."""
    try:
        raw_candidates = _cached_candidate_rows_for_horizon_flow_v1()[:300]
        statuses["pladeu_candidate_rows"] = PAPER_OPPORTUNITY_ALLOCATION_ENGINE.decorate_candidates(raw_candidates)
    except Exception:
        statuses["pladeu_candidate_rows"] = []
    statuses["pladeu_open_positions"] = _pladeu_open_positions_from_cached_status_v1(statuses)
    statuses["evidence_accumulation_capacity_v1"] = _evidence_accumulation_capacity_payload_v1(statuses)
    statuses["portfolio_capacity_release_review_v1"] = _portfolio_capacity_release_review_payload_v1(statuses)
    # Unified diagnostics keeps only the executive summary. The detailed
    # per-position table is available from its dedicated endpoint so the
    # Learning Center does not inherit another large dashboard hot payload.
    position_intelligence = _position_intelligence_utilization_payload_v1(statuses, persist=False)
    retrieval = dict(position_intelligence.get("position_retrieval_coverage") or {})
    portfolio_review = dict(position_intelligence.get("portfolio_review") or {})
    impact = dict(position_intelligence.get("decision_impact_measurement") or {})
    statuses["astra_position_intelligence_utilization_v1"] = {
        "endpoint": position_intelligence.get("endpoint"),
        "status": position_intelligence.get("status"),
        "generated_at": position_intelligence.get("generated_at"),
        "broker_snapshot": position_intelligence.get("broker_snapshot"),
        "position_retrieval_coverage": {key: value for key, value in retrieval.items() if key != "positions"},
        "portfolio_review": {
            "total_positions": portfolio_review.get("total_positions"),
            "primary_state_counts": portfolio_review.get("primary_state_counts"),
            "retrieval_coverage": portfolio_review.get("retrieval_coverage"),
            "differentiation_audit": portfolio_review.get("differentiation_audit"),
            "action_queue": portfolio_review.get("action_queue"),
        },
        "bounded_consumers": position_intelligence.get("bounded_consumers"),
        "dynamic_capacity_advisory": position_intelligence.get("dynamic_capacity_advisory"),
        "strategy_selection": position_intelligence.get("strategy_selection"),
        "decision_impact_measurement": {key: value for key, value in impact.items() if key != "records"},
        "provider_calls_used": 0,
        "broker_actions_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }
    lineage = dict(position_intelligence.get("position_lineage_excursion_replacement_v1") or {})
    statuses["astra_position_lineage_excursion_replacement_v1"] = {
        "endpoint": "/api/astra_position_lineage_excursion_replacement_v1",
        "status": lineage.get("status"),
        "coverage_by_confidence_class": lineage.get("coverage_by_confidence_class"),
        "broker_registry_coverage": lineage.get("broker_registry_coverage"),
        "coverage_by_excursion_class": lineage.get("coverage_by_excursion_class"),
        "coverage_by_replacement_state": lineage.get("coverage_by_replacement_state"),
        "thesis_recovery_status": lineage.get("thesis_recovery_status"),
        "bounded_read": lineage.get("bounded_read"),
        "provider_calls_used": 0,
        "broker_actions_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }
    statuses["authoritative_broker_truth"] = _canonical_broker_truth_counts_v1(statuses)
    statuses["pladeu_candidate_source_metadata"] = _pladeu_candidate_source_metadata_v1()
    statuses["day_lane_pilot_config"] = _day_lane_pilot_config_v1()
    try:
        statuses["pladeu_day_lane_allocation"] = PAPER_OPPORTUNITY_ALLOCATION_ENGINE.day_lane_governance(
            rows=statuses["pladeu_candidate_rows"], open_positions=statuses["pladeu_open_positions"]
        )
    except Exception:
        statuses["pladeu_day_lane_allocation"] = {}
    builders = (
        ("astra_trade_lane_registry_v1", "trade_lane_registry", ASTRA_TRADE_LANE_REGISTRY),
        ("historical_lifecycle_reconstruction_v1", "historical_reconstruction", ASTRA_HISTORICAL_LIFECYCLE_RECONSTRUCTION),
        ("paper_learning_evidence_ladder_v1", "evidence_ladder", PAPER_LEARNING_EVIDENCE_LADDER),
        ("trade_lifecycle_profit_capture_satellite_v1", "lifecycle_satellite", TRADE_LIFECYCLE_PROFIT_CAPTURE_SATELLITE),
        ("day_lane_diversity_governor_v1", "day_lane_governor", DAY_LANE_DIVERSITY_GOVERNOR),
    )
    statuses["day_lane_pilot_readiness_v1"] = _day_lane_pilot_readiness_payload_v1(statuses)
    statuses["multilane_paper_operational_status_v1"] = _multilane_paper_operational_status_v1_payload(statuses)
    statuses["astra_broker_truth_throughput_v1"] = _broker_truth_throughput_v1_payload(statuses)
    statuses["lane_execution_daily_report_v1"] = _lane_execution_daily_report_v1_payload(statuses)
    statuses["learning_return_integrity_v1"] = _learning_return_integrity_v1_payload()
    for public_key, internal_key, builder in builders:
        try:
            value = builder.status(statuses=statuses, force=bool(force))
        except Exception:
            value = {}
        statuses[public_key] = value
        statuses[internal_key] = value
    for public_key, builder in (
        ("pladeu_phase1_lane_validation_v1", PLADEU_PHASE1_LANE_VALIDATION),
        ("pladeu_phase2_reconstruction_validation_v1", PLADEU_PHASE2_RECONSTRUCTION_VALIDATION),
        ("pladeu_phase3_learning_validation_v1", PLADEU_PHASE3_LEARNING_VALIDATION),
        ("pladeu_phase4_runtime_validation_v1", PLADEU_PHASE4_RUNTIME_VALIDATION),
        ("pladeu_master_validation_v1", PLADEU_MASTER_VALIDATION),
    ):
        try:
            statuses[public_key] = builder.status(statuses=statuses, force=bool(force))
        except Exception:
            statuses[public_key] = {}
    statuses["pladeu_master_validation"] = statuses.get("pladeu_master_validation_v1") or {}
    # Learning Center consumes only an existing certification snapshot.  It
    # never starts a dry run or adds another dashboard-time endpoint call.
    certification_cache = _CACHE.get("astra_pre_market_trading_certification_v1")
    certification = dict((certification_cache or {}).get("data") or {}) if isinstance(certification_cache, dict) else {}
    statuses["astra_pre_market_trading_certification_v1"] = {
        "endpoint": "/api/astra_pre_market_trading_certification_v1",
        "status": certification.get("status") or "NOT_RUN",
        "snapshot_id": certification.get("snapshot_id"),
        "expiry_timestamp": certification.get("expiry_timestamp"),
        "lanes": {
            lane: {key: value for key, value in dict(row or {}).items() if key in {"status", "exact_blocker", "severity", "candidate_contract_count", "valid_contract_count", "order_ready_count"}}
            for lane, row in dict(certification.get("lanes") or {}).items()
        },
        "provider_calls_used": 0,
        "broker_actions_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }
    pladeu_packet = dict((statuses.get("pladeu_master_validation_v1") or {}).get("governance_packet") or {})
    for consumer_key in (
        "astra_governance_oversight_v2",
        "astra_knowledge_warehouse_v1",
        "astra_tier2a_librarian_executive_truth_layer_v1",
        "cortex_lifecycle_evidence_master_truth_v1",
    ):
        if isinstance(statuses.get(consumer_key), dict):
            statuses[consumer_key] = {
                **dict(statuses.get(consumer_key) or {}),
                "pladeu_advisory_packet_v1": pladeu_packet,
            }
    return statuses


def _attach_premarket_certification_compact_v1(statuses: dict) -> dict:
    """Attach a cached certification snapshot without rebuilding diagnostics."""
    certification_cache = _CACHE.get("astra_pre_market_trading_certification_v1")
    certification = dict((certification_cache or {}).get("data") or {}) if isinstance(certification_cache, dict) else {}
    statuses["astra_pre_market_trading_certification_v1"] = {
        "endpoint": "/api/astra_pre_market_trading_certification_v1",
        "status": certification.get("status") or "NOT_RUN",
        "snapshot_id": certification.get("snapshot_id"),
        "expiry_timestamp": certification.get("expiry_timestamp"),
        "lanes": {
            lane: {
                key: value
                for key, value in dict(row or {}).items()
                if key in {"status", "exact_blocker", "severity", "candidate_contract_count", "valid_contract_count", "order_ready_count"}
            }
            for lane, row in dict(certification.get("lanes") or {}).items()
        },
        "provider_calls_used": 0,
        "broker_actions_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }
    return statuses


def _pladeu_endpoint_payload_v1(key: str, force: bool = False) -> dict:
    base = _pladeu_direct_statuses_v1(force=bool(force))
    payload = dict(base.get(key) or {})
    if key == "day_lane_governor":
        # Cached governor diagnostics may outlive a configuration reload.  The
        # shared activation contract is authoritative for enablement, while
        # the governor remains advisory for diversity analysis.
        activation = dict((base.get("day_lane_pilot_config") or {}).get("activation_contract") or {})
        if activation:
            payload.update({
                "day_lane_enabled": bool(activation.get("lane_enabled")),
                "day_lane_execution_enabled": bool(activation.get("execution_enabled")),
                "day_lane_activation_contract": activation,
            })
    endpoint_paths = {
        "trade_lane_registry": "/api/astra_trade_lane_registry_v1",
        "historical_reconstruction": "/api/historical_lifecycle_reconstruction_v1",
        "evidence_ladder": "/api/paper_learning_evidence_ladder_v1",
        "lifecycle_satellite": "/api/trade_lifecycle_profit_capture_satellite_v1",
        "day_lane_governor": "/api/day_lane_diversity_governor_v1",
        "day_lane_pilot_readiness_v1": "/api/day_lane_pilot_readiness_v1",
        "multilane_paper_operational_status_v1": "/api/multilane_paper_operational_status_v1",
        "pladeu_master_validation": "/api/pladeu_master_validation_v1",
    }
    payload.update(
        {
            "endpoint": endpoint_paths.get(key, f"/api/{key}"),
            "generated_at": _now_utc_iso(),
            "mode": "paper_only_advisory_cache_first",
            "freshness": "cached_or_bounded_local_evidence",
            "source_lineage": "cached_candidates|cached_broker_truth|bounded_local_lifecycle_records",
            "evidence_classes": ((base.get("historical_reconstruction") or {}).get("reconstruction") or {}).get("evidence_class_counts", {}),
            "exact_blockers": list(payload.get("failed_checks") or []),
            "deferred_evidence": bool((base.get("pladeu_master_validation") or {}).get("deferred_evidence", False)),
            "warnings": [],
            "failed_sources": [],
            "failed_sources_count": 0,
            "provider_calls_used": 0,
            "broker_actions_used": 0,
            "llm_calls_used": 0,
            "dashboard_provider_calls_used": 0,
            "full_history_scans": 0,
            "behavior_safe_to_apply": False,
            "paper_mode_verified": True,
            "broker_live_endpoint_allowed": False,
            "automatic_promotion_enabled": False,
            "learned_exit_execution_enabled": False,
            "human_review_required": True,
        }
    )
    return payload


@router.get("/api/astra_trade_lane_registry_v1")
def astra_trade_lane_registry_v1(force: bool = False):
    return _pladeu_endpoint_payload_v1("trade_lane_registry", force=force)


