@router.get("/api/unified_position_lifecycle_exit_truth_closure_diagnostic_v1")
def unified_position_lifecycle_exit_truth_closure_diagnostic_v1(force: bool = False):
    """Read-only bridge from canonical broker positions to exit policy readiness."""
    broker = _cached_alpaca_paper_status_payload({})
    broker_snapshot_available = bool(broker)
    readiness = _exit_readiness_diagnostics_v1_payload({})
    contexts, context_audit = _position_intelligence_context_v1({"alpaca_paper_broker": broker})
    legacy_activations = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("legacy_forward_activations") or {})
    readiness_by_symbol = {str(row.get("symbol") or "").upper(): row for row in (readiness.get("position_rows") or []) if isinstance(row, dict)}
    rows = []
    for position in _pladeu_open_positions_from_cached_status_v1({"alpaca_paper_broker": broker})[:100]:
        symbol = str(position.get("symbol") or "").upper()
        activation = dict(legacy_activations.get(str(position.get("asset_id") or position.get("position_id") or symbol).upper()) or {})
        overlay = {**activation, **dict(contexts.get(symbol) or {}), **dict(readiness_by_symbol.get(symbol) or {})}
        decision = build_unified_position_lifecycle_decision_v1(
            {**position, **overlay}, current_market_evidence=position,
            lifecycle_plan=overlay, evidence_context=overlay,
        )
        rows.append(decision)
    stage_rows = []
    repairable = []
    for row in rows:
        baseline = dict(row.get("forward_baseline") or {})
        horizon = dict(row.get("provisional_horizon") or {})
        twin = dict(row.get("shadow_twin") or {})
        stage_rows.extend([
            {"position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"), "lane": row.get("lane"), "horizon": horizon.get("provisional_horizon"), "stage": "forward_baseline", "state": "PASS" if baseline.get("baseline_state") == "LEGACY_FORWARD_BASELINE_COMPLETE" else "PASS_WITH_WARNINGS" if baseline.get("baseline_state") == "LEGACY_FORWARD_BASELINE_PARTIAL" else "NOT_APPLICABLE", "owner": "engine.astra_unified_position_lifecycle_v1.build_legacy_forward_baseline_v1", "blocker": (baseline.get("limitations") or [None])[0], "blocker_category": "evidence", "safe_repair_allowed": False},
            {"position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"), "lane": row.get("lane"), "horizon": horizon.get("provisional_horizon"), "stage": "provisional_horizon", "state": "PASS" if horizon.get("state") == "PROVISIONAL_HORIZON_ACTIVE" else "INSUFFICIENT_EVIDENCE", "owner": "engine.astra_unified_position_lifecycle_v1.estimate_legacy_provisional_horizon_v1", "blocker": None if horizon.get("state") == "PROVISIONAL_HORIZON_ACTIVE" else "holding_age_unavailable", "blocker_category": "evidence", "safe_repair_allowed": False},
            {"position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"), "lane": row.get("lane"), "horizon": horizon.get("provisional_horizon"), "stage": "position_shadow_twin", "state": "PASS" if twin.get("state") == "POSITION_SHADOW_TWIN_ACTIVE" else "BROKER_EVIDENCE_PENDING", "owner": "engine.astra_unified_position_lifecycle_v1.build_position_shadow_twin_v1", "blocker": (twin.get("limitations") or ["forward_activation_timestamp_required"])[0], "blocker_category": "evidence", "safe_repair_allowed": False},
        ])
        for evidence in row.get("evidence_rows") or []:
            state = "PASS" if evidence.get("consumed") else "NOT_AVAILABLE"
            stage_rows.append({
                "position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"),
                "lane": row.get("lane"), "horizon": row.get("original_horizon"), "stage": f"evidence:{evidence.get('source')}",
                "state": state, "owner": evidence.get("owner"), "producer": evidence.get("owner"),
                "consumer": "engine.astra_unified_position_lifecycle_v1", "actual_value": evidence.get("consumed"),
                "expected_value": True, "blocker": evidence.get("limitation"),
                "blocker_category": "evidence" if state != "PASS" else None,
                "safe_repair_allowed": False if state != "PASS" else None,
            })
        action_state = "HUMAN_POLICY_DECISION_REQUIRED" if row.get("policy_eligibility") == "POLICY_BLOCKED" else "NOT_APPLICABLE"
        stage_rows.extend([
            {"position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"), "lane": row.get("lane"), "horizon": row.get("original_horizon"), "stage": "policy_validation", "state": action_state, "owner": "PaperAutopilot.authorized_lane_exit_pending", "producer": "unified_position_lifecycle", "consumer": "PaperAutopilot", "blocker": row.get("exact_blocker"), "blocker_category": "policy", "safe_repair_allowed": False},
            {"position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"), "lane": row.get("lane"), "horizon": row.get("original_horizon"), "stage": "paper_order_readiness", "state": action_state, "owner": "PaperAutopilot", "producer": "PaperAutopilot.authorized_lane_exit_pending", "consumer": "AlpacaPaperBroker", "blocker": row.get("exact_blocker"), "blocker_category": "policy", "safe_repair_allowed": False},
            {"position_id": row.get("position_id"), "symbol": row.get("symbol"), "cohort": row.get("cohort"), "lane": row.get("lane"), "horizon": row.get("original_horizon"), "stage": "broker_ack_fill_truth", "state": "EXTERNAL_BROKER_PENDING", "owner": "PaperAutopilot", "producer": "AlpacaPaperBroker", "consumer": "broker_truth_records_v1", "blocker": "NO_POLICY_AUTHORIZED_EXIT_ORDER_SUBMITTED", "blocker_category": "broker", "safe_repair_allowed": False},
        ])
    status = "PASS" if broker_snapshot_available else "EXTERNAL_BROKER_PENDING"
    return {
        "endpoint": "/api/unified_position_lifecycle_exit_truth_closure_diagnostic_v1", "status": status,
        "generated_at": _now_utc_iso(), "positions_total": len(rows),
        "broker_snapshot_available": broker_snapshot_available,
        "broker_snapshot_state": "CACHED_BROKER_STATE_AVAILABLE" if broker_snapshot_available else "BROKER_STATE_UNAVAILABLE_FAIL_CLOSED",
        "evidence_context_audit": context_audit,
        "cohort_distribution": dict(Counter(str(row.get("cohort")) for row in rows)),
        "classification_distribution": dict(Counter(str(row.get("classification")) for row in rows)),
        "evidence_retrieved_count": sum(int(row.get("evidence_retrieved_count") or 0) for row in rows),
        "evidence_matched_count": sum(int(row.get("evidence_matched_count") or 0) for row in rows),
        "evidence_weighted_count": sum(int(row.get("evidence_weighted_count") or 0) for row in rows),
        "evidence_consumed_count": sum(int(row.get("evidence_consumed_count") or 0) for row in rows),
        "evidence_influenced_count": sum(int(row.get("evidence_influenced_count") or 0) for row in rows),
        "predictive_forecast_distribution": dict(Counter(str(row.get("predictive_forecast_state")) for row in rows)),
        "forward_baseline_distribution": dict(Counter(str((row.get("forward_baseline") or {}).get("baseline_state")) for row in rows)),
        "provisional_horizon_distribution": dict(Counter(str((row.get("provisional_horizon") or {}).get("provisional_horizon")) for row in rows)),
        "shadow_twin_distribution": dict(Counter(str((row.get("shadow_twin") or {}).get("state")) for row in rows)),
        "policy_blocked_count": sum(1 for row in rows if row.get("policy_eligibility") == "POLICY_BLOCKED"),
        "evidence_insufficient_count": sum(1 for row in rows if row.get("exact_blocker") == "INSUFFICIENT_CURRENT_DIRECT_EVIDENCE"),
        "repairable_failures": repairable, "stage_rows": stage_rows, "position_rows": rows,
        "canonical_position_decision_owner": "engine.astra_unified_position_lifecycle_v1.build_unified_position_lifecycle_decision_v1",
        "canonical_exit_policy_owner": "PaperAutopilot.authorized_lane_exit_pending", "read_only": True,
        "provider_calls_used": 0, "broker_actions_used": 0, "llm_calls_used": 0, "full_history_scan_count": 0,
        **_safety_flags_v1(),
    }


def _legacy_swing_canary_pre_submit_audit_payload_v1() -> dict:
    """Read persisted worker output only; this is never an execution trigger."""
    runtime = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("legacy_swing_canary") or {})
    activations = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("legacy_forward_activations") or {})
    config = dict(runtime.get("configuration") or {})
    reviews = dict(runtime.get("reviews") or {})
    selection = dict(runtime.get("selection") or {})
    pre_submit = runtime.get("pre_submit") if isinstance(runtime.get("pre_submit"), dict) else None
    adapter = dict(runtime.get("writer_adapter_contract") or {})
    stage_rows = []
    repairable = []
    config_ok = bool(config.get("policy_id") == "LEGACY_SWING_CONTROLLED_PAPER_CANARY_V1")
    worker_ok = bool(runtime.get("worker_acknowledgement") == "CANARY_CONFIGURATION_CONSUMED_BY_WORKER")
    canary_active = bool(config.get("enabled")) and not bool(config.get("kill_switch"))
    for activation_id, record in sorted(activations.items()):
        row = dict(record or {})
        if str(row.get("cohort") or "").startswith("DUST"):
            continue
        review = dict(reviews.get(activation_id) or {})
        position_id = review.get("position_id") or row.get("position_id")
        symbol = review.get("symbol") or row.get("symbol")
        base = {"position_id": position_id, "activation_id": row.get("activation_id") or activation_id, "symbol": symbol,
                "owner": "PaperAutopilot._refresh_legacy_swing_canary_pre_submit", "producer": "PaperAutopilot worker",
                "consumer": "legacy_swing_canary runtime state", "store": "paper_autopilot_state.json", "join_key": activation_id}
        stages = [
            ("activation", "PASS" if row.get("legacy_activation_timestamp") else "NOT_PERSISTED", "persisted activation required"),
            ("shadow_twin", "PASS" if dict(row.get("shadow_twin") or {}).get("state") == "POSITION_SHADOW_TWIN_ACTIVE" else "DISCONNECTED", "active shadow twin required"),
            ("reassessment", "PASS" if review.get("next_review_at") else "DISCONNECTED", "worker must persist next review"),
            ("technical_eligibility", "PASS" if "eligibility" in review else "DISCONNECTED", "worker must evaluate eligibility"),
        ]
        for stage, state, expected in stages:
            repair = state in {"NOT_PERSISTED", "DISCONNECTED"}
            result = {**base, "stage": stage, "expected_state": "PASS", "actual_state": state,
                      "acknowledgement": (review.get("acknowledgements") or {}).get("TECHNICAL_ELIGIBILITY_EVALUATED"),
                      "blocker": None if state == "PASS" else expected,
                      "blocker_type": "technical" if repair else None, "safe_repair_allowed": repair,
                      "exact_repair": "run normal PaperAutopilot worker refresh" if repair else None}
            stage_rows.append(result)
            if repair:
                repairable.append(result)
        eligibility = dict(review.get("eligibility") or {})
        if canary_active:
            authorized = bool(eligibility.get("execution_authorized"))
            stage_rows.append({
                **base, "stage": "execution_enforcement", "expected_state": "CANDIDATE_GATE_EVALUATED",
                "actual_state": "EXECUTION_AUTHORIZED" if authorized else "BROKER_SUBMISSION_BLOCKED_BY_CANDIDATE_GATE",
                "acknowledgement": "CANARY_ACTIVE_NATURAL_ELIGIBILITY_ONLY",
                "blocker": None if authorized else eligibility.get("exact_blocker"),
                "blocker_type": None if authorized else "legitimate evidence/policy block",
                "safe_repair_allowed": False, "exact_repair": None,
            })
        else:
            stage_rows.append({
                **base, "stage": "execution_enforcement", "expected_state": "KILL_SWITCH_ACTIVE",
                "actual_state": eligibility.get("final_state") or "CANARY_DISABLED",
                "acknowledgement": "EXECUTION_BLOCKED_BY_DISABLED_POLICY", "blocker": "disabled_by_design",
                "blocker_type": "legitimate safety block", "safe_repair_allowed": False, "exact_repair": None,
            })
    global_rows = [
        {"stage": "configuration", "owner": "engine.astra_unified_position_lifecycle_v1.legacy_swing_canary_configuration_v1",
         "producer": "canonical configuration", "consumer": "PaperAutopilot worker", "store": "paper_autopilot_state.json",
         "join_key": "policy_id", "expected_state": "PASS", "actual_state": "PASS" if config_ok else "NOT_CONSUMED",
         "acknowledgement": runtime.get("worker_acknowledgement"), "blocker": None if config_ok else "configuration_missing",
         "blocker_type": "technical" if not config_ok else None, "safe_repair_allowed": not config_ok,
         "exact_repair": "persist canonical disabled configuration from worker" if not config_ok else None},
        {"stage": "worker_consumption", "owner": "PaperAutopilot._refresh_legacy_swing_canary_pre_submit",
         "producer": "PaperAutopilot worker", "consumer": "legacy_swing_canary runtime state", "store": "paper_autopilot_state.json",
         "join_key": "policy_id", "expected_state": "PASS", "actual_state": "PASS" if worker_ok else "NOT_CONSUMED",
         "acknowledgement": runtime.get("worker_acknowledgement"), "blocker": None if worker_ok else "worker_not_yet_run",
         "blocker_type": "technical" if not worker_ok else None, "safe_repair_allowed": not worker_ok,
         "exact_repair": "run normal PaperAutopilot worker cycle" if not worker_ok else None},
        {"stage": "candidate_ranking", "owner": "engine.astra_unified_position_lifecycle_v1.select_legacy_swing_canary_candidate_v1",
         "producer": "PaperAutopilot worker", "consumer": "legacy_swing_canary runtime state", "store": "paper_autopilot_state.json",
         "join_key": "position_id", "expected_state": "PASS", "actual_state": "PASS" if worker_ok and "selected_candidate" in selection else "DISCONNECTED",
         "acknowledgement": selection.get("tie_break_reason"), "blocker": None if worker_ok and "selected_candidate" in selection else "selection_not_persisted",
         "blocker_type": "technical" if worker_ok and "selected_candidate" not in selection else None,
         "safe_repair_allowed": worker_ok and "selected_candidate" not in selection,
         "exact_repair": "persist deterministic selection from worker" if worker_ok and "selected_candidate" not in selection else None},
        {"stage": "adapter_mapping", "owner": "PaperAutopilot.legacy_swing_canary_writer_pre_submit",
         "producer": "canonical legacy SWING adapter", "consumer": "PaperAutopilot._submit_authorized_lane_exit", "store": "source contract",
         "join_key": "pre_submit_id/action_id", "expected_state": "ADAPTER_MAPPING_VALID",
         "actual_state": "ADAPTER_MAPPING_VALID" if adapter.get("status") == "WRITER_PATH_CONNECTED" else "DISCONNECTED",
         "acknowledgement": adapter.get("smallest_adapter_boundary"), "blocker": "BROKER_SUBMISSION_BLOCKED",
         "blocker_type": "legitimate safety block", "safe_repair_allowed": False, "exact_repair": None},
        {"stage": "writer_adapter_contract", "owner": "engine.astra_unified_position_lifecycle_v1.legacy_swing_writer_adapter_contract_v1",
         "producer": "canonical adapter specification", "consumer": "PaperAutopilot._submit_authorized_lane_exit", "store": "paper_autopilot_state.json",
         "join_key": "policy_id", "expected_state": "WRITER_PATH_CONNECTED", "actual_state": adapter.get("status") or "DISCONNECTED",
         "acknowledgement": adapter.get("existing_writer"), "blocker": "BROKER_SUBMISSION_BLOCKED",
         "blocker_type": "legitimate safety block", "safe_repair_allowed": False, "exact_repair": None},
    ]
    stage_rows.extend(global_rows)
    repairable.extend([row for row in global_rows if row.get("safe_repair_allowed")])
    return {
        "endpoint": "/api/legacy_swing_canary_pre_submit_closure_diagnostic_v1", "status": "PASS" if not repairable else "FAILED",
        "generated_at": _now_utc_iso(), "read_only": True, "configuration": config,
        "kill_switch_state": bool(config.get("kill_switch")), "canary_enabled": bool(config.get("enabled")),
        "positions_processed": len(reviews), "activation_records": len(activations), "reviews": list(reviews.values()),
        "selection": selection, "pre_submit": pre_submit, "writer_adapter_contract": adapter,
        "stage_rows": stage_rows, "repairable_failures": repairable,
        "broker_actions": int(runtime.get("broker_actions") or 0), "natural_orders": int(runtime.get("natural_orders") or 0),
        "fixture_orders": int(runtime.get("fixture_orders") or 0), "provider_calls_used": 0, "llm_calls_used": 0,
        "broker_actions_used": 0, **_safety_flags_v1(),
    }


@router.get("/api/legacy_swing_canary_pre_submit_closure_diagnostic_v1")
def legacy_swing_canary_pre_submit_closure_diagnostic_v1():
    """Read-only disabled-canary closure diagnostic; never invokes a writer."""
    return _legacy_swing_canary_pre_submit_audit_payload_v1()


@router.get("/api/legacy_swing_canary_pre_submit_audit_v1")
def legacy_swing_canary_pre_submit_audit_v1():
    """Alias for the canonical pre-submit runtime audit."""
    return _legacy_swing_canary_pre_submit_audit_payload_v1()


def _legacy_swing_canary_activation_readiness_payload_v1() -> dict:
    """Read-only activation certification. It never changes canary control state."""
    runtime = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("legacy_swing_canary") or {})
    reviews = dict(runtime.get("reviews") or {})
    config = legacy_swing_canary_configuration_v1()
    pre_submit = _legacy_swing_canary_pre_submit_audit_payload_v1()
    classification = legacy_swing_classification_integrity_diagnostic_v1()
    required = _legacy_swing_required_evidence_payload_v1()
    market = _broker_market_evidence_payload_v1()
    fmp = _fmp_production_consumption_payload_v1()
    # Readiness is polled during normal worker activity.  Use the canonical
    # in-scope safety audits rather than recursively building the broad
    # Governance bundle, which can fan out into unrelated dashboard work.
    historical = _legacy_swing_historical_bar_momentum_payload_v1()
    runtime_reliability = _astra_runtime_worker_reliability_payload_v1()
    governance = {
        "critical_findings_count": int(historical.get("governance_critical") or 0),
        "high_findings_count": int(historical.get("governance_high") or 0)
        + (0 if runtime_reliability.get("overall_status") in {"PASS", "PASS_WITH_WARNINGS"} else 1),
    }
    safety = dict(getattr(PAPER_AUTOPILOT, "_alpaca_safety_snapshot", lambda: {})() or {})
    candidate_rows, quality_rows = [], []
    for activation_id, raw in sorted(reviews.items()):
        review, decision, eligibility = dict(raw or {}), dict((raw or {}).get("decision") or {}), dict((raw or {}).get("eligibility") or {})
        evidence = dict(review.get("required_evidence") or {})
        actionable = str(review.get("current_classification") or "") in set(config.get("eligible_classifications") or [])
        if actionable:
            components = dict(decision.get("classification_components") or {})
            supported = bool(components.get("evidence_complete")) and not bool(decision.get("evidence_stale") or decision.get("evidence_conflicting")) and bool(review.get("classification_reason"))
            quality_rows.append({"symbol": review.get("symbol"), "activation_id": review.get("activation_id") or activation_id, "classification": review.get("current_classification"), "confidence": review.get("classification_confidence"), "reason": review.get("classification_reason"), "supported": supported, "components": components, "missing_evidence": decision.get("evidence_missing") or [], "suppressed_classifications": decision.get("suppressed_classifications") or []})
        candidate_rows.append({"symbol": review.get("symbol"), "position_id": review.get("position_id"), "activation_id": review.get("activation_id") or activation_id, "classification": review.get("current_classification"), "technical_eligibility": bool(eligibility.get("technical_eligibility")), "eligibility_failures": eligibility.get("eligibility_failures") or [], "exact_blocker": eligibility.get("exact_blocker"), "decision_confidence": eligibility.get("decision_confidence"), "direct_confirmation": review.get("direct_confirmation_state"), "direct_confirmation_confidence": review.get("direct_confirmation_confidence"), "momentum_state": (evidence.get("MOMENTUM") or {}).get("status"), "thesis_state": (evidence.get("THESIS_STATE") or {}).get("status"), "liquidity_state": (evidence.get("LIQUIDITY") or {}).get("status"), "candidate_evidence_complete": bool(eligibility.get("technical_eligibility"))})
    eligible = [row for row in candidate_rows if row.get("technical_eligibility")]
    unsupported = [row for row in quality_rows if not row.get("supported")]
    provider_starved = any(str((family or {}).get("starvation_state") or "") == "PROVIDER_STARVED" for family in (market.get("families") or {}).values())
    system_blockers = []
    if not bool(safety.get("paper_mode_verified")) or bool(safety.get("live_endpoint_detected")):
        system_blockers.append("PAPER_ONLY_BROKER_BOUNDARY_REQUIRED")
    if int(governance.get("critical_findings_count") or 0) or int(governance.get("high_findings_count") or 0):
        system_blockers.append("GOVERNANCE_HIGH_OR_CRITICAL")
    for name, payload in (("CLASSIFICATION", classification), ("REQUIRED_EVIDENCE", required), ("MARKET_EVIDENCE", market), ("FMP", fmp), ("WRITER", pre_submit)):
        if payload.get("repairable_failures"):
            system_blockers.append(f"{name}_REPAIRABLE_FAILURE")
    if provider_starved:
        system_blockers.append("PROVIDER_STARVED")
    if unsupported:
        system_blockers.append("UNSUPPORTED_ACTIONABLE_CLASSIFICATION")
    writer_ready = pre_submit.get("status") == "PASS" and (pre_submit.get("writer_adapter_contract") or {}).get("status") == "WRITER_PATH_CONNECTED"
    if not writer_ready:
        system_blockers.append("WRITER_BLOCKED")
    backlog = int(market.get("bounded_backlog") or 0)
    readiness = "NOT_READY" if system_blockers else "READY_WITH_BACKLOG" if backlog else "READY"
    return {"endpoint": "/api/legacy_swing_canary_activation_readiness_v1", "read_only": True, "configuration_ready": bool(config.get("paper_only") and config.get("policy_id")), "classification_quality_ready": not unsupported and not classification.get("repairable_failures"), "evidence_pipeline_ready": not required.get("repairable_failures") and not market.get("repairable_failures") and not fmp.get("repairable_failures"), "candidate_evidence_ready": bool(eligible), "direct_confirmation_ready": bool(eligible), "quantity_ready": True, "idempotency_ready": True, "writer_ready": writer_ready, "broker_safety_ready": not bool(safety.get("live_endpoint_detected")) and bool(safety.get("paper_mode_verified")), "governance_ready": not (int(governance.get("critical_findings_count") or 0) or int(governance.get("high_findings_count") or 0)), "reconciliation_ready": all(not bool((review.get("eligibility") or {}).get("eligibility_checks", {}).get("no_duplicate_pending_exit") is False) for review in reviews.values()), "provider_starvation_state": "PROVIDER_STARVED" if provider_starved else "ACTIVE", "market_data_backlog_state": "BACKLOG" if backlog else "CLEAR", "eligible_candidates": eligible, "selected_candidate": (runtime.get("selection") or {}).get("selected_candidate"), "selected_candidate_blockers": [] if eligible else [row for row in candidate_rows if row.get("classification") in set(config.get("eligible_classifications") or [])], "activation_recommended": readiness in {"READY", "READY_WITH_BACKLOG"}, "activation_blockers": system_blockers, "readiness_state": readiness, "configuration": config, "classification_quality_rows": quality_rows, "candidate_rows": candidate_rows, "broker_actions": 0, "provider_calls": 0, "fixture_orders": 0, "natural_orders": int(runtime.get("natural_orders") or 0)}


@router.get("/api/legacy_swing_canary_activation_readiness_v1")
def legacy_swing_canary_activation_readiness_v1():
    return {**_legacy_swing_canary_activation_readiness_payload_v1(), **_safety_flags_v1()}


def _legacy_swing_exit_truth_closure_payload_v1() -> dict:
    """Read persisted legacy canary lifecycle state only; never refreshes a broker."""
    runtime = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("legacy_swing_canary") or {})
    lifecycle = dict(getattr(PAPER_AUTOPILOT, "_runtime_state", {}).get("legacy_swing_exit_lifecycle") or {})
    reviews = dict(runtime.get("reviews") or {})
    selection = dict(runtime.get("selection") or {})
    orders, fills = dict(lifecycle.get("orders") or {}), dict(lifecycle.get("fills") or {})
    reconciliations, closures = dict(lifecycle.get("reconciliations") or {}), dict(lifecycle.get("closures") or {})
    truths, releases = dict(lifecycle.get("truths") or {}), dict(lifecycle.get("capacity_releases") or {})
    effectiveness = dict(lifecycle.get("effectiveness") or {})
    stage_rows, repairable, waiting = [], [], []
    actionable = directly_confirmed = 0
    for activation_id, review in sorted(reviews.items()):
        row = dict(review or {})
        classification = str(row.get("current_classification") or "")
        direct = dict(row.get("direct_confirmation") or {})
        confirmation_state = str(direct.get("confirmation_state") or row.get("direct_confirmation_state") or "UNCONFIRMED")
        if classification in {"THESIS_BROKEN", "CONTROLLED_LOSS_ACCEPTABLE", "PROTECT_PROFIT", "PROTECT_PARTIAL", "REDUCE_RISK", "REPLACE_CANDIDATE"}:
            actionable += 1
        if confirmation_state.startswith("CONFIRMED_"):
            directly_confirmed += 1
        base = {"position_id": row.get("position_id"), "activation_id": row.get("activation_id") or activation_id, "symbol": row.get("symbol"), "store": "paper_autopilot_state.json", "join_key": activation_id}
        confirmation_missing = not bool(direct.get("confirmation_id"))
