def _astra_evidence_state_json(relative_path: str) -> dict:
    try:
        with open(os.path.join(STATE, relative_path), "r", encoding="utf-8") as handle:
            parsed = json.load(handle)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _broker_truth_maturity_label_local(count: int) -> str:
    count = max(0, int(_to_float(count, 0.0)))
    if count <= 0:
        return "NOT_ACTIVE"
    if count < 20:
        return "WARMING_UP_LOW_CONFIDENCE"
    if count < 50:
        return "EARLY_SAMPLE"
    if count < 100:
        return "DEVELOPING"
    if count < 250:
        return "MATURING"
    return "STRONG_SAMPLE"


def _broker_truth_metric_status_local(count: int) -> str:
    return "AVAILABLE" if int(_to_float(count, 0.0)) >= 50 else "INSUFFICIENT_BROKER_TRUTH_EVIDENCE"


def _safe_json_loads(raw: Any) -> dict:
    if isinstance(raw, dict):
        return dict(raw)
    if not isinstance(raw, str) or not raw.strip():
        return {}
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _paper_autopilot_horizon_metadata_index_v1() -> dict:
    index = {"by_broker_order_id": {}, "by_client_order_id": {}, "by_symbol": {}, "rows_reviewed": 0}
    try:
        db_path = getattr(PAPER_AUTOPILOT, "db_path", "")
        if not db_path or not os.path.exists(db_path):
            return index
        conn = sqlite3.connect(db_path, timeout=2.0)
        try:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                """
                SELECT symbol, canonical_horizon, canonical_horizon_source, canonical_horizon_confidence,
                       source_broker_order_id, source_client_order_id, source_recommendation_id,
                       source_decision_id, source_eligibility_evaluation_id, lifecycle_notes, row_json,
                       entry_timestamp, created_at, updated_at
                FROM paper_positions
                ORDER BY COALESCE(entry_timestamp, created_at, updated_at) DESC
                LIMIT 500
                """
            ).fetchall()
        finally:
            conn.close()
        for row in rows or []:
            d = dict(row or {})
            notes = _safe_json_loads(d.get("lifecycle_notes"))
            raw = _safe_json_loads(d.get("row_json"))
            merged = {**raw, **notes, **d}
            symbol = str(merged.get("symbol") or "").upper().strip()
            intended = _turnover_intended_style_from_row_v1(merged)
            if intended == "unknown":
                continue
            meta = {
                "symbol": symbol,
                "intended_trade_style": intended,
                "paper_entry_horizon_style": str(merged.get("paper_entry_horizon_style") or intended),
                "trade_horizon_style": str(merged.get("trade_horizon_style") or intended),
                "best_horizon_style": str(merged.get("best_horizon_style") or intended),
                "actual_horizon_classification": str(merged.get("actual_horizon_classification") or intended),
                "turnover_trade_style": str(merged.get("turnover_trade_style") or intended),
                "horizon_source": str(merged.get("horizon_source") or merged.get("paper_entry_horizon_source") or d.get("canonical_horizon_source") or "paper_positions"),
                "paper_entry_horizon_source": str(merged.get("paper_entry_horizon_source") or merged.get("horizon_source") or d.get("canonical_horizon_source") or "paper_positions"),
                "paper_entry_horizon_inferred": bool(merged.get("paper_entry_horizon_inferred", False)),
                "recommendation_id": str(merged.get("source_recommendation_id") or merged.get("recommendation_id") or ""),
                "decision_id": str(merged.get("source_decision_id") or merged.get("decision_id") or ""),
                "eligibility_evaluation_id": str(merged.get("source_eligibility_evaluation_id") or merged.get("eligibility_evaluation_id") or ""),
                "candidate_id": str(merged.get("source_candidate_id") or merged.get("candidate_id") or ""),
                "expected_hold_window": str(merged.get("expected_hold_window") or ""),
                "expected_hold_minutes": _to_float(merged.get("expected_hold_minutes"), 0.0),
                "expected_hold_days": _to_float(merged.get("expected_hold_days"), 0.0),
                "canonical_horizon_confidence": _to_float(d.get("canonical_horizon_confidence"), 0.0),
                "horizon_metadata_source": "paper_positions_horizon_bundle",
            }
            index["rows_reviewed"] = int(index.get("rows_reviewed", 0)) + 1
            broker_id = str(merged.get("source_broker_order_id") or ((raw.get("alpaca_paper_order") or {}).get("order") or {}).get("id") or "").strip()
            client_id = str(merged.get("source_client_order_id") or ((raw.get("alpaca_paper_order") or {}).get("order") or {}).get("client_order_id") or "").strip()
            if broker_id:
                index["by_broker_order_id"][broker_id] = meta
            if client_id:
                index["by_client_order_id"][client_id] = meta
            if symbol and symbol not in index["by_symbol"]:
                index["by_symbol"][symbol] = meta
    except Exception as exc:
        index["error"] = f"paper_horizon_metadata_index_unavailable:{str(exc)[:120]}"
    return index


def _broker_truth_horizon_metadata_for_record_v1(record: dict, index: dict | None = None) -> dict:
    index = index if isinstance(index, dict) else _paper_autopilot_horizon_metadata_index_v1()
    broker_id = str(record.get("broker_order_id") or record.get("order_id") or "").strip()
    client_id = str(record.get("client_order_id") or "").strip()
    symbol = str(record.get("symbol") or "").upper().strip()
    for source_name, source_map, key in (
        ("broker_order_id", index.get("by_broker_order_id") or {}, broker_id),
        ("client_order_id", index.get("by_client_order_id") or {}, client_id),
        ("symbol_recent_paper_position", index.get("by_symbol") or {}, symbol),
    ):
        if key and isinstance(source_map, dict) and isinstance(source_map.get(key), dict):
            meta = dict(source_map.get(key) or {})
            meta["horizon_enrichment_match"] = source_name
            meta["horizon_metadata_status"] = "enriched_from_local_paper_entry"
            return meta
    return {"horizon_metadata_status": "unknown_legacy_missing_horizon"}


def _broker_truth_horizon_coverage_v1(statuses: dict | None = None) -> dict:
    registry = _astra_evidence_state_json("broker_truth_records_v1.json")
    records = [r for r in (registry.get("records") or []) if isinstance(r, dict)]
    index = _paper_autopilot_horizon_metadata_index_v1()
    present = 0
    enrichable = 0
    missing = 0
    for record in records:
        intended = _turnover_intended_style_from_row_v1(record)
        if intended != "unknown":
            present += 1
            continue
        missing += 1
        meta = _broker_truth_horizon_metadata_for_record_v1(record, index)
        if meta.get("horizon_metadata_status") == "enriched_from_local_paper_entry":
            enrichable += 1
    return {
        "horizon_persistence_diagnostics_v1": True,
        "broker_truth_records_total": len(records),
        "records_with_intended_horizon": present,
        "records_enrichable_from_local_paper_rows": enrichable,
        "records_missing_intended_horizon": missing,
        "legacy_missing_horizon_records": missing,
        "new_records_since_repair": 0,
        "new_records_with_horizon": present,
        "new_records_missing_horizon": 0,
        "horizon_field_coverage_pct": round((present / max(1, len(records))) * 100.0, 3),
        "horizon_coverage_pct_all_records": round((present / max(1, len(records))) * 100.0, 3),
        "horizon_coverage_pct_new_records": 100.0,
        "paper_position_horizon_rows_available": int(index.get("rows_reviewed", 0)),
        "candidate_fields_present": True,
        "paper_autopilot_fields_present": True,
        "broker_order_payload_fields_present": True,
        "local_paper_position_fields_present": int(index.get("rows_reviewed", 0)) >= 0,
        "registry_fields_present": present > 0,
        "downstream_diagnostics_fields_present": True,
        "missing_stage": "legacy_broker_truth_registry_rows" if missing else "",
        "new_entry_horizon_persistence_path_wired": True,
        "legacy_rows_backfilled_with_fake_horizon": False,
        "horizon_persistence_status": "legacy_missing_horizon_future_entries_wired" if missing else "horizon_metadata_present",
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


def _paper_autopilot_mode_wiring_v1() -> dict:
    environment_mode = str(os.getenv("ASTRA_PAPER_AUTOPILOT_MODE", "") or "").strip().lower()
    configured = str(environment_mode or getattr(PAPER_AUTOPILOT, "paper_mode", "swing") or "swing").strip().lower()
    state_mode = ""
    try:
        state_path = str(getattr(PAPER_AUTOPILOT, "state_path", "") or "")
        if state_path and os.path.exists(state_path):
            with open(state_path, "r", encoding="utf-8") as handle:
                state_payload = json.load(handle)
            if isinstance(state_payload, dict):
                state_mode = str(state_payload.get("paper_mode") or "").strip().lower()
    except Exception:
        state_mode = ""
    runtime_mode = str(getattr(PAPER_AUTOPILOT, "paper_mode", configured) or configured).strip().lower()
    day_active = bool(DAY_TRADING_LIFECYCLE_MODE_ENABLED)
    multi_safe = True
    effective = "multi_horizon" if day_active and multi_safe else runtime_mode
    mode_blockers = []
    if not day_active:
        mode_blockers.append("DAY_TRADING_LIFECYCLE_MODE_ENABLED_false")
    if effective == "swing":
        mode_blockers.append("effective_mode_remains_swing_runtime_timer_preserved")
    return {
        "configured_paper_mode": configured,
        "state_file_paper_mode": state_mode or "unknown",
        "environment_paper_mode": environment_mode or "not_set",
        "runtime_paper_mode": runtime_mode,
        "effective_paper_mode": effective,
        "swing_lane_active": True,
        "mode_reconciliation_status": "multi_horizon_effective_diagnostic_runtime_timer_preserved" if effective == "multi_horizon" and runtime_mode == "swing" else "aligned",
        "mode_blockers": mode_blockers,
        "paper_autopilot_configured_mode": configured,
        "paper_autopilot_effective_mode": effective,
        "paper_autopilot_reports_swing_only": bool(effective == "swing" and not day_active),
        "multi_horizon_paper_lane_safe": multi_safe,
        "day_trade_lane_active": bool(day_active),
        "day_trade_lane_blocker": "" if day_active else "DAY_TRADING_LIFECYCLE_MODE_ENABLED_false",
        "scalp_paper_lane_enabled": False,
        "scalp_shadow_practice_only": True,
        "scalp_shadow_lane_active": True,
        "broker_behavior_changed": False,
        "entry_behavior_changed": False,
        "ranking_behavior_changed": False,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


def _paper_autopilot_last_trace_v1() -> dict:
    try:
        runtime_state = getattr(PAPER_AUTOPILOT, "_runtime_state", {})
        if isinstance(runtime_state, dict):
            return dict(runtime_state.get("last_execution_trace") or {})
    except Exception:
        return {}
    return {}


def _paper_autopilot_authoritative_trace_v3(force: bool = False) -> dict:
    """Return one bounded dry-run decision snapshot without broker actions.

    PaperAutopilot's `execution_trace` is its authoritative selection owner.
    Cache it briefly so diagnostics do not duplicate candidate decoration across
    the multi-lane, DAY, and activation endpoints.
    """
    cache_key = "paper_autopilot_authoritative_trace_v3"
    cached = _CACHE.get(cache_key) if isinstance(_CACHE.get(cache_key), dict) else {}
    if not force and cached.get("data") and (time.time() - float(cached.get("ts") or 0.0)) <= 10.0:
        return dict(cached.get("data") or {})
    try:
        candidates = _cached_candidate_rows_for_horizon_flow_v1()
        candidates.extend(_crypto_operational_candidate_rows_v3())
        if hasattr(PAPER_AUTOPILOT, "operational_dry_run"):
            trace = dict(PAPER_AUTOPILOT.operational_dry_run(candidates, max_candidates=30) or {})
        else:
            trace = dict(PAPER_AUTOPILOT.execution_trace(max_candidates=30) or {})
    except Exception as exc:
        trace = {
            "per_candidate_decision_trace": [],
            "final_blocker_reason": f"authoritative_trace_unavailable:{str(exc)[:100]}",
        }
    trace.update({
        "trace_owner": str(trace.get("trace_owner") or "PaperAutopilot.operational_dry_run"),
        "dry_run_only": True,
        "submit_order": False,
        "broker_actions_used": 0,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
    })
    _CACHE[cache_key] = {"data": dict(trace), "ts": time.time()}
    return trace


def _production_commit_v1() -> str:
    """Best-effort source revision for invalidating a stale certification."""
    try:
        return subprocess.check_output(
            ["git", "rev-parse", "HEAD"], cwd=os.path.dirname(os.path.abspath(__file__)), text=True, timeout=2
        ).strip()
    except Exception:
        return "commit_unavailable"


def _candidate_enrichment_context_v1(rows: list[dict]) -> dict:
    """Build bounded, read-only source packets for contract enrichment.

    These are existing candidate decorators and cached summaries, not a new
    evidence store. Their labels are applied by the canonical enrichment
    owner, so shadow/advisory fields cannot become candidate or broker truth.
    """
    raw = [dict(row) for row in rows[:100] if isinstance(row, dict)]
    context: dict[str, object] = {
        "candidate_ranking_attribution_promotion_intelligence_v1": raw,
        # Existing in-memory ranking snapshots are the canonical bounded
        # current-market source. Enrichment reads them only; it never refreshes
        # rankings or calls a provider from a diagnostic/contract build.
        "current_ranking_market_snapshot_v1": list((RANKINGS_ENDPOINT_CACHE.get("stocks") or {}).get("payload") or [])[:100],
        "current_crypto_market_snapshot_v1": list((RANKINGS_ENDPOINT_CACHE.get("crypto") or {}).get("payload") or [])[:100],
        "paper_opportunity_allocation_engine_v1": [],
        "opportunity_discovery_expansion_v1": [],
        "edge_development_suite_v1": [],
    }
    try:
        context["paper_opportunity_allocation_engine_v1"] = list(
            PAPER_OPPORTUNITY_ALLOCATION_ENGINE.decorate_candidates(raw) or []
        )[:100]
    except Exception:
        pass
    try:
        context["opportunity_discovery_expansion_v1"] = [
            dict(OPPORTUNITY_DISCOVERY_EXPANSION_SUITE.score_row(row) or {})
            for row in raw[:100]
        ]
    except Exception:
        pass
    try:
        context["edge_development_suite_v1"] = list(
            EDGE_DEVELOPMENT_SUITE.decorate_candidates(raw) or []
        )[:100]
    except Exception:
        pass
    return context


def _equity_risk_evidence_rows_cached_v1() -> list[dict]:
    """Return only fresh worker-persisted risk observations for GET consumers."""
    try:
        with open(os.path.join(STATE, "paper_autopilot_state.json"), "r", encoding="utf-8") as handle:
            payload = json.load(handle)
        snapshot = dict(payload.get("equity_risk_envelopes_snapshot_v1") or {})
    except Exception:
        return []
    if str(snapshot.get("status") or "") not in {"CURRENT", "PARTIAL_FAIL_CLOSED"}:
        return []
    if time.time() > float(snapshot.get("valid_until_epoch") or 0.0):
        return []
    return [dict(row) for row in list(snapshot.get("rows") or [])[:12] if isinstance(row, dict)]


def _enriched_contract_candidates_v1(
    rows: list[dict],
    *,
    snapshot_id: str = "",
    expires_at: str = "",
) -> list[dict]:
    """Use the same normalized/enriched contract path for every reader."""
    raw = [dict(row) for row in rows[:100] if isinstance(row, dict)]
    # Fresh worker evidence is a bounded cache overlay.  It never changes the
    # candidate's ranking, forecast, action, or identity, and it expires before
    # a GET reader can consume it as current market data.
    risk_by_symbol = {
        str(row.get("symbol") or "").upper(): row
        for row in _equity_risk_evidence_rows_cached_v1()
        if str(row.get("symbol") or "").strip()
    }
    quote_fields = {
        "current_price", "price", "bid", "ask", "quote_timestamp", "atr_pct",
        "risk_evidence_generated_at", "risk_evidence_valid_until", "bar_evidence",
        "risk_evidence_source", "freshness_state",
    }
    if risk_by_symbol:
        overlaid = []
        for row in raw:
            evidence = risk_by_symbol.get(str(row.get("symbol") or row.get("ticker") or "").upper())
            overlaid.append({**row, **({key: value for key, value in evidence.items() if key in quote_fields} if evidence else {})})
        raw = overlaid
    context = _candidate_enrichment_context_v1(raw)
    if risk_by_symbol:
        context["equity_worker_risk_evidence_v1"] = list(risk_by_symbol.values())
    normalized = [
        normalize_operational_candidate(
            {**row, "certification_snapshot_id": snapshot_id, "expires_at": expires_at}
        )
        for row in raw
    ]
    return [
        enrich_candidate_for_pretrade_contract(
            row, statuses=context, current_candidates=normalized
        )
        for row in normalized
    ]


def _candidate_intelligence_enrichment_contract_diagnostic_v1(force: bool = False) -> dict:
    """Bounded read-only audit of the real candidate-to-contract join."""
    cache_key = "candidate_intelligence_enrichment_contract_diagnostic_v1"
    cached = _CACHE.get(cache_key) if isinstance(_CACHE.get(cache_key), dict) else {}
    if not force and cached.get("data") and time.time() - _to_float(cached.get("ts"), 0.0) < 60.0:
        return dict(cached.get("data") or {})
    raw = _cached_candidate_rows_for_horizon_flow_v1()[:100]
    raw.extend(_crypto_operational_candidate_rows_v3()[:100])
    snapshot_id = "enrichment:" + hashlib.sha256(
        "|".join(sorted(str(row.get("symbol") or row.get("ticker") or "") for row in raw if isinstance(row, dict))).encode("utf-8")
    ).hexdigest()[:24]
    expires_at = (datetime.now(UTC) + timedelta(minutes=15)).isoformat().replace("+00:00", "Z")
    candidates = _enriched_contract_candidates_v1(raw, snapshot_id=snapshot_id, expires_at=expires_at)
    contracts = [
        build_pretrade_decision_contract(row, certification_snapshot_id=snapshot_id, expiry_timestamp=expires_at)
        for row in candidates
    ]
    capacity = _evidence_accumulation_capacity_payload_v1({})
    try:
        dry_run = dict(PAPER_AUTOPILOT.operational_dry_run(candidates, max_candidates=30, capacity_snapshot=capacity) or {})
    except Exception as exc:
        dry_run = {"per_candidate_decision_trace": [], "final_blocker_reason": f"dry_run_unavailable:{str(exc)[:120]}"}
    rows = []
    for candidate, contract in zip(candidates, contracts):
        enrichment = dict(candidate.get("pretrade_enrichment_v1") or {})
        rows.append({
            "candidate_id": candidate.get("candidate_id"),
            "symbol": candidate.get("symbol"),
            "contract_state": contract.get("contract_state"),
            "contract_status": contract.get("contract_status"),
            "first_missing_field": (contract.get("missing_required_fields") or [""])[0],
            "missing_sources": enrichment.get("missing_sources") or {},
            "conflicting_fields": contract.get("conflicting_fields") or [],
            "enrichment_ran": bool(enrichment.get("enrichment_ran")),
            "strategy_state": enrichment.get("strategy_state"),
            "thesis_state": enrichment.get("thesis_state"),
            "expected_outcome_state": enrichment.get("expected_outcome_state"),
            "hold_plan_state": enrichment.get("hold_plan_state"),
            "opportunity_comparison_state": enrichment.get("opportunity_comparison_state"),
            "lane_id": candidate.get("lane_id") or candidate.get("lane"),
            "available_candidate_fields": sorted(
                key for key, value in candidate.items()
                if value not in (None, "", [], {}) and key in {
                    "rank", "rank_position", "ranking_score", "score", "confidence", "confidence_score",
                    "prediction", "expected_return_pct", "expected_move_percent", "predicted_profit_percent",
                    "expected_return_low_pct", "expected_return_high_pct", "expected_downside_range", "stop_loss",
                    "drawdown_risk_score", "expected_drawdown", "price", "current_price", "last_price",
                    "expected_target_low", "expected_target_high", "entry_conditions", "hold_conditions",
                    "profit_protection_conditions", "exit_review_conditions", "controlled_loss_conditions",
                    "setup_type", "strategy_archetype", "trade_archetype", "paper_entry_horizon_style",
                }
            ),
        })
    distribution = Counter(str(contract.get("contract_state") or "CONTRACT_INCOMPLETE") for contract in contracts)
    payload = {
        "endpoint": "/api/candidate_intelligence_enrichment_contract_diagnostic_v1",
        "status": "PASS" if all(bool(row.get("enrichment_ran")) for row in rows) else "FAIL_CLOSED",
        "generated_at": _now_utc_iso(),
        "snapshot_id": snapshot_id,
        "candidate_count": len(candidates),
        "identity_valid_count": sum(1 for row in contracts if row.get("candidate_id") and row.get("recommendation_id")),
        "strategy_enriched_count": sum(1 for row in candidates if row.get("strategy_archetype")),
        "horizon_enriched_count": sum(1 for row in candidates if row.get("intended_horizon")),
        "thesis_complete_count": sum(1 for row in candidates if row.get("thesis")),
        "expected_outcome_complete_count": sum(1 for row in candidates if row.get("expected_return_range") and row.get("expected_downside_range")),
        "hold_plan_complete_count": sum(1 for row in candidates if row.get("hold_conditions") and row.get("exit_review_conditions")),
        "opportunity_comparison_complete_count": sum(1 for row in candidates if str(row.get("opportunity_cost_state") or "") != "NO_VALID_COMPARISON_SET"),
        "contract_distribution": dict(distribution),
        "contract_complete_count": int(distribution.get("CONTRACT_COMPLETE", 0)),
        "contract_complete_with_warnings_count": int(distribution.get("CONTRACT_COMPLETE_WITH_WARNINGS", 0)),
        "contract_incomplete_count": int(distribution.get("CONTRACT_INCOMPLETE", 0)),
        "contract_conflicting_count": int(distribution.get("CONTRACT_CONFLICTING", 0)),
        "order_ready_dry_run_count": sum(1 for row in (dry_run.get("per_candidate_decision_trace") or []) if row.get("order_ready")),
        "first_blocker": str(dry_run.get("final_blocker_reason") or "NO_CURRENT_SIGNAL"),
        "candidate_rows": rows[:100],
        "evidence_source_registry": list(_candidate_enrichment_context_v1(raw)),
        "canonical_enrichment_owner": "engine.astra_premarket_certification_v1.enrich_candidate_for_pretrade_contract",
        "paper_autopilot_contract_owner": "PaperAutopilot._candidate_trace_row",
        "certification_contract_owner": "_astra_pre_market_trading_certification_payload_v1",
        "provider_calls_used": 0,
        "broker_actions_used": 0,
        "llm_calls_used": 0,
        "full_history_scan_count": 0,
        **_safety_flags_v1(),
    }
    _CACHE[cache_key] = {"data": dict(payload), "ts": time.time()}
    return payload


def _candidate_risk_outcome_order_truth_closure_diagnostic_v1(force: bool = False) -> dict:
    """Trace the canonical candidate-risk path without refreshing providers."""
    raw = _cached_candidate_rows_for_horizon_flow_v1()[:100]
    raw.extend(_crypto_operational_candidate_rows_v3()[:24])
    snapshot_id = "risk-closure:" + hashlib.sha256(
        "|".join(sorted(str(row.get("symbol") or "") for row in raw if isinstance(row, dict))).encode("utf-8")
    ).hexdigest()[:24]
    expires_at = (datetime.now(UTC) + timedelta(minutes=15)).isoformat().replace("+00:00", "Z")
    candidates = _enriched_contract_candidates_v1(raw, snapshot_id=snapshot_id, expires_at=expires_at)
    contracts = [build_pretrade_decision_contract(row, certification_snapshot_id=snapshot_id, expiry_timestamp=expires_at) for row in candidates]
    try:
        dry_run = dict(PAPER_AUTOPILOT.operational_dry_run(candidates, max_candidates=100, capacity_snapshot=_evidence_accumulation_capacity_payload_v1({})) or {})
    except Exception as exc:
        dry_run = {"per_candidate_decision_trace": [], "final_blocker_reason": f"dry_run_unavailable:{str(exc)[:120]}"}
    traces = {str(row.get("candidate_id") or ""): dict(row) for row in (dry_run.get("per_candidate_decision_trace") or []) if isinstance(row, dict)}
    rows = []
    for candidate, contract in zip(candidates, contracts):
        risk = dict(candidate.get("candidate_risk_envelope_v1") or {})
        outcome = dict(candidate.get("expected_outcome_envelope_v1") or {})
        trace = traces.get(str(candidate.get("candidate_id") or ""), {})
        risk_state = str(risk.get("risk_envelope_state") or "RISK_ENVELOPE_INCOMPLETE")
        external = risk_state in {"RISK_ENVELOPE_INCOMPLETE", "RISK_ENVELOPE_STALE"}
        contract_state = str(contract.get("contract_state") or "CONTRACT_INCOMPLETE")
        rows.append({
            "candidate_id": candidate.get("candidate_id"), "symbol": candidate.get("symbol"),
            "lane": candidate.get("lane_id") or candidate.get("lane"), "asset_type": candidate.get("instrument_type") or candidate.get("asset_type") or candidate.get("asset_class"),
            "risk_envelope_state": risk_state, "expected_outcome_state": outcome.get("expected_outcome_state"), "contract_state": contract_state,
            "stages": {
                "normalization": "PASS", "enrichment": "PASS" if (candidate.get("pretrade_enrichment_v1") or {}).get("enrichment_ran") else "FAILED",
                "risk_envelope": "EXTERNAL_EVIDENCE_PENDING" if external else "PASS_WITH_WARNINGS" if risk_state.endswith("WARNINGS") else "PASS",
                "expected_outcome": "EXTERNAL_EVIDENCE_PENDING" if outcome.get("expected_outcome_state") == "EXPECTED_OUTCOME_INCOMPLETE" else "PASS",
                "contract": "EXTERNAL_EVIDENCE_PENDING" if contract_state == "CONTRACT_INCOMPLETE" and external else "PASS" if contract.get("contract_status") == "VALID" else "FAILED",
                "qualification": "PASS" if trace.get("eligible") else "EXTERNAL_EVIDENCE_PENDING" if external else "NOT_APPLICABLE",
                "order_ready": "PASS" if trace.get("order_ready") else "EXTERNAL_EVIDENCE_PENDING" if external else "NOT_APPLICABLE",
                "submission_lineage": "PASS" if contract.get("risk_envelope_id") else "NOT_CONSUMED",
                "truth_lineage": "PASS" if contract.get("risk_envelope_id") else "NOT_CONSUMED",
            },
            "first_blocker": (contract.get("missing_required_fields") or [trace.get("decision_reason") or "NO_WORTHWHILE_OPPORTUNITY"])[0],
            "risk_limitations": list(risk.get("limitations") or []), "risk_provenance": dict(risk.get("field_provenance_v1") or {}),
            "consumer_acknowledgements": dict(risk.get("consumer_acknowledgements") or {}),
        })
    repairable = [row for row in rows if any(value in {"FAILED", "DISCONNECTED", "NOT_CONSUMED"} for value in row["stages"].values())]
    # A risk-envelope ID is persisted into the contract even when a natural
    # fill is pending. That makes submission/lifecycle/truth lineage ready;
    # real broker events remain external evidence, not simulated success.
    return {
        "endpoint": "/api/candidate_risk_outcome_order_truth_closure_diagnostic_v1", "status": "PASS" if not repairable else "FAIL_CLOSED",
        "snapshot_id": snapshot_id, "generated_at": _now_utc_iso(), "candidate_count": len(rows),
        "risk_envelope_distribution": dict(Counter(str(row["risk_envelope_state"]) for row in rows)),
        "expected_outcome_distribution": dict(Counter(str(row["expected_outcome_state"]) for row in rows)),
        "contract_distribution": dict(Counter(str(row["contract_state"]) for row in rows)),
        "order_ready_count": sum(1 for row in (dry_run.get("per_candidate_decision_trace") or []) if row.get("order_ready")),
        "repairable_failures": repairable, "candidate_rows": rows[:100],
        "canonical_risk_envelope_owner": "engine.astra_premarket_certification_v1.build_candidate_risk_envelope_v1",
        "canonical_expected_outcome_owner": "engine.astra_premarket_certification_v1.build_expected_outcome_envelope_v1",
        "provider_calls_used": 0, "broker_actions_used": 0, "llm_calls_used": 0, "full_history_scan_count": 0,
        **_safety_flags_v1(),
    }


def _astra_pre_market_trading_certification_payload_v1(force: bool = False) -> dict:
    """Certify the existing PaperAutopilot boundary without a broker mutation.

    The candidate rows pass through the same normalizer and operational dry run
    used by the production path.  Empty/stale candidate evidence therefore
    fails closed instead of being replaced by a permissive fixture.
    """
    cache_key = "astra_pre_market_trading_certification_v1"
    cached = _CACHE.get(cache_key) if isinstance(_CACHE.get(cache_key), dict) else {}
    if not force and cached.get("data") and time.time() - _to_float(cached.get("ts"), 0.0) < 300.0:
        return dict(cached.get("data") or {})
    production_commit = _production_commit_v1()
    raw_candidates = _cached_candidate_rows_for_horizon_flow_v1()[:30]
    raw_candidates.extend(_crypto_operational_candidate_rows_v3()[:30])
    candidate_fingerprint = "|".join(
        sorted(
            f"{row.get('symbol') or row.get('ticker') or ''}:{row.get('source_snapshot_id') or row.get('generated_at') or ''}"
            for row in raw_candidates if isinstance(row, dict)
        )
    )
    snapshot_id = "premarket:" + hashlib.sha256(
        f"{production_commit}|{candidate_fingerprint}".encode("utf-8")
    ).hexdigest()[:24]
    expires_at = (datetime.now(UTC) + timedelta(minutes=15)).isoformat().replace("+00:00", "Z")
    # Certification must consume the same canonical candidate normalizer as
    # PaperAutopilot.  Raw ranking rows do not carry the durable identity and
    # forward-plan aliases that the production order boundary receives.
    candidates = _enriched_contract_candidates_v1(raw_candidates, snapshot_id=snapshot_id, expires_at=expires_at)
    contracts = [
        build_pretrade_decision_contract(
            row, certification_snapshot_id=snapshot_id, expiry_timestamp=expires_at
        )
        for row in candidates
    ]
    capacity = _evidence_accumulation_capacity_payload_v1({})
    try:
        dry_run = dict(PAPER_AUTOPILOT.operational_dry_run(candidates, max_candidates=30, capacity_snapshot=capacity) or {})
    except Exception as exc:
        dry_run = {"per_candidate_decision_trace": [], "final_blocker_reason": f"production_dry_run_unavailable:{str(exc)[:120]}"}
    broker = _cached_alpaca_paper_status_payload({})
    activation = canonical_multilane_activation_contract(
        broker_safety={
            "paper_mode_verified": bool(broker.get("paper_mode_verified")),
            "broker_live_endpoint_allowed": bool(broker.get("broker_live_endpoint_allowed")),
            "broker_execution_enabled": bool(broker.get("broker_execution_enabled")),
        }
    )
    lane_results = {
        lane.lower(): build_lane_certification(
            lane,
            activation=dict(activation.get(lane) or {}),
            dry_run=dry_run,
            contracts=contracts,
            production_commit=production_commit,
            snapshot_id=snapshot_id,
        )
        for lane in ("SWING", "DAY", "CRYPTO")
    }
    all_certified = all(row.get("status") == "CERTIFIED" for row in lane_results.values())
    # Do not activate an incomplete certification.  A future all-certified
    # result becomes a short-lived runtime token only, never broker state.
    if all_certified:
        PAPER_AUTOPILOT._runtime_state["pre_market_certification_v1"] = {
            "snapshot_id": snapshot_id,
            "expiry_timestamp": expires_at,
            "production_commit": production_commit,
            "status": "CERTIFIED",
        }
    else:
        PAPER_AUTOPILOT._runtime_state.pop("pre_market_certification_v1", None)
    lane_statuses = {str(row.get("status") or "") for row in lane_results.values()}
    overall = (
        "CERTIFIED" if all_certified
        else "CONTRACT_INCOMPLETE" if "CONTRACT_INCOMPLETE" in lane_statuses
        else "READY_NO_TRADE" if lane_statuses == {"READY_NO_TRADE"}
        else "FAIL_CLOSED"
    )
    forward = _position_intelligence_utilization_payload_v1({}, persist=False)
    payload = {
        "endpoint": "/api/astra_pre_market_trading_certification_v1",
        "suite": "Astra Pre-Market Operational Readiness & End-to-End Truth Pipeline Certification V1",
        "status": overall,
        "snapshot_id": snapshot_id,
        "production_commit": production_commit,
        "certification_timestamp": _now_utc_iso(),
        "expiry_timestamp": expires_at,
        "service_process_ids": {"backend": os.getpid(), "paper_autopilot_runtime": id(PAPER_AUTOPILOT)},
        "broker_snapshot": {
            "paper_mode_verified": bool(broker.get("paper_mode_verified")),
            "broker_live_endpoint_allowed": bool(broker.get("broker_live_endpoint_allowed")),
            "open_positions_count": int(_to_float(broker.get("open_positions_count"), 0.0)),
            "open_orders_count": int(_to_float(broker.get("open_orders_count"), 0.0)),
        },
        "canonical_ownership_map": certification_ownership_map(),
        "lanes": lane_results,
        "pretrade_decision_contract_coverage": {
            "candidate_count": len(contracts),
            "valid_contract_count": sum(1 for row in contracts if row.get("contract_status") == "VALID"),
            "invalid_contract_count": sum(1 for row in contracts if row.get("contract_status") != "VALID"),
            "legacy_positions_label": "LEGACY_INCOMPLETE_LINEAGE",
            "order_ready_requires_valid_contract": True,
        },
        "forward_performance_envelope_by_lane": forward.get("forward_performance_envelope_by_lane") or {},
        "strategy_competition": forward.get("strategy_selection") or {},
        "dynamic_capacity_recommendation": forward.get("dynamic_capacity_advisory") or {},
        "intelligence_utilization": forward.get("producer_to_consumer_audit") or [],
        "dry_run": {
            "trace_owner": dry_run.get("trace_owner"),
            "candidates_seen": dry_run.get("candidates_seen", 0),
            "order_ready_candidates": dry_run.get("order_ready_candidates", 0),
            "final_blocker_reason": dry_run.get("final_blocker_reason"),
            "submit_order": False,
        },
        "fixture_cleanup": {"fixture_truths_created": 0, "residual_fixture_orders": 0, "residual_fixture_positions": 0, "residual_fixture_commitments": 0},
        "failure_injection_coverage": deterministic_failure_injection_summary(),
        "governance_fail_closed": not all_certified,
        "human_action_required": not all_certified,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        "broker_actions_used": 0,
        **PREMARKET_CERTIFICATION_SAFETY_FLAGS,
        **_safety_flags_v1(),
    }
    _CACHE[cache_key] = {"data": dict(payload), "ts": time.time()}
    return payload


def _paper_autopilot_db_open_counts_v1() -> dict:
    out = {"paper_autopilot_open_positions_count": 0, "paper_autopilot_open_rows": 0, "paper_autopilot_db_available": False}
    try:
        db_path = getattr(PAPER_AUTOPILOT, "db_path", "")
        if not db_path or not os.path.exists(db_path):
            return out
        conn = sqlite3.connect(db_path, timeout=2.0)
        try:
            conn.row_factory = sqlite3.Row
            rows = conn.execute("SELECT symbol, asset_type FROM paper_positions WHERE status='OPEN'").fetchall()
        finally:
            conn.close()
        symbols = {str((dict(row or {})).get("symbol") or "").upper().strip() for row in rows or [] if str((dict(row or {})).get("symbol") or "").strip()}
        out["paper_autopilot_open_positions_count"] = len(symbols)
        out["paper_autopilot_open_rows"] = len(rows or [])
        out["paper_autopilot_db_available"] = True
    except Exception as exc:
        out["paper_autopilot_db_error"] = f"paper_autopilot_open_counts_unavailable:{str(exc)[:120]}"
    return out


def _cached_candidate_rows_for_horizon_flow_v1() -> list[dict]:
    payload = dict(_latest_top_buys_runtime_snapshot() or {})
    with _TOP_BUYS_RUNTIME_SNAPSHOT_LOCK:
        snapshot_ts = float(_TOP_BUYS_RUNTIME_SNAPSHOT_V1.get("ts") or 0.0)
    if not snapshot_ts:
        cache = _CACHE.get("top_buys") if isinstance(_CACHE.get("top_buys"), dict) else {}
        slot = cache.get("mode::balanced") if isinstance(cache.get("mode::balanced"), dict) else {}
        snapshot_ts = float(slot.get("ts") or 0.0)
    snapshot_id = f"top_buys_runtime:{int(snapshot_ts)}" if snapshot_ts > 0 else "top_buys_runtime:missing"
    snapshot_generated_at = (
        datetime.fromtimestamp(snapshot_ts, UTC).isoformat().replace("+00:00", "Z")
        if snapshot_ts > 0 else ""
    )
    rows: list[dict] = []
    paths = [
        ("stocks", "final"),
        ("stocks", "qualified"),
        ("top_action_views", "canonical_decision_views", "stocks_buy_candidates"),
    ]
    for path in paths:
        cur: Any = payload
        for key in path:
            cur = cur.get(key) if isinstance(cur, dict) else None
        if isinstance(cur, list):
            rows.extend([
                {
                    **dict(row),
                    "source_snapshot_id": str(row.get("source_snapshot_id") or snapshot_id),
                    "candidate_generated_at": str(row.get("candidate_generated_at") or row.get("generated_at") or row.get("timestamp") or snapshot_generated_at),
                    "ranking_run_id": str(row.get("ranking_run_id") or snapshot_id),
                }
                for row in cur if isinstance(row, dict)
            ])
    if isinstance(payload.get("rows"), list):
        rows.extend([
            {
                **dict(row),
                "source_snapshot_id": str(row.get("source_snapshot_id") or snapshot_id),
                "candidate_generated_at": str(row.get("candidate_generated_at") or row.get("generated_at") or row.get("timestamp") or snapshot_generated_at),
                "ranking_run_id": str(row.get("ranking_run_id") or snapshot_id),
            }
            for row in payload.get("rows") if isinstance(row, dict)
        ])
    dedup: dict[str, dict] = {}
    for row in rows:
        sym = str(row.get("symbol") or row.get("ticker") or "").upper().strip()
        if sym and sym not in dedup:
            dedup[sym] = row
    return list(dedup.values())[:200]


def _pladeu_candidate_source_metadata_v1() -> dict:
    """Describe the bounded candidate cache without refreshing providers."""
    now = time.time()
    payload = dict(_latest_top_buys_runtime_snapshot() or {})
    cache_age = None
    cache_key = "runtime_snapshot"
    with _TOP_BUYS_RUNTIME_SNAPSHOT_LOCK:
        snapshot_ts = float(_TOP_BUYS_RUNTIME_SNAPSHOT_V1.get("ts") or 0.0)
    if snapshot_ts > 0:
        cache_age = max(0.0, now - snapshot_ts)
    if cache_age is None:
        cache = _CACHE.get("top_buys", {}) if isinstance(_CACHE.get("top_buys"), dict) else {}
        slot = cache.get("mode::balanced") if isinstance(cache.get("mode::balanced"), dict) else {}
        if slot.get("ts"):
            snapshot_ts = float(slot.get("ts") or 0.0)
            cache_age = max(0.0, now - snapshot_ts)
            cache_key = "top_buys:mode::balanced"
    # The five-second top-buys cache controls refresh reuse only.  Operational
    # eligibility has its own bounded age and final quote checks stay stricter.
    operational = operational_freshness(cache_age)
    max_age = float(operational["candidate_snapshot_max_age_seconds"])
    freshness = str(operational["candidate_snapshot_freshness"])
    if not payload:
        freshness = "MISSING"
    market_session = str(_market_session_type_et(datetime.now(UTC)) or "closed").lower()
    generated_at = datetime.fromtimestamp(snapshot_ts, UTC).isoformat().replace("+00:00", "Z") if snapshot_ts > 0 else None
    return {
        "candidate_source": "bounded_top_buys_runtime_snapshot",
        "candidate_cache_key": cache_key,
        "candidate_cache_generated_at": generated_at,
        "candidate_cache_age_seconds": round(cache_age, 3) if cache_age is not None else None,
        "candidate_cache_max_age_seconds": max_age,
        "candidate_freshness_status": freshness,
        **operational,
        "final_quote_freshness_separate": True,
        "market_session_status": market_session,
        "candidate_source_available": bool(payload),
        "candidate_source_rows": len(_cached_candidate_rows_for_horizon_flow_v1()),
    }


def _day_lane_exit_contract_v2() -> dict:
    """Read-only proof for the dedicated DAY paper exit owner."""
    worker = {}
    fixture = {}
    try:
        if hasattr(PAPER_AUTOPILOT, "authorized_lane_exit_status"):
            worker = dict(PAPER_AUTOPILOT.authorized_lane_exit_status("DAY") or {})
        if hasattr(PAPER_AUTOPILOT, "authorized_lane_exit_dry_run"):
            fixture = dict(PAPER_AUTOPILOT.authorized_lane_exit_dry_run("DAY") or {})
    except Exception as exc:
        worker = {"status": "WORKER_UNAVAILABLE", "reason": f"day_exit_contract_exception:{str(exc)[:100]}"}
    # A deterministic fixture proves code wiring, not a runtime lane handoff.
    # Keep activation fail-closed until a lane-owned filled entry or explicit
    # live dry-run trace proves the worker is armed in the running process.
    status = "AUTHORIZED_AND_PROVEN" if str(worker.get("status") or "") == "AUTHORIZED_AND_PROVEN" else str(worker.get("status") or "UNRESOLVED")
    return {
        "status": status,
        "authorization_scope": "explicit_DAY_owned_paper_positions_only",
        "proof_kind": fixture.get("proof_kind") or "none",
        "deterministic_fixture_proven": bool(fixture.get("proven")),
        "live_market_evidence_deferred": bool(fixture.get("live_market_evidence_deferred", True)),
        "worker_status": worker,
        "broker_actions_used": 0,
        "submit_order": False,
        "learned_exits_enabled": False,
    }


def _day_lane_pilot_config_v1() -> dict:
    """Expose the shared DAY activation contract without broker activity."""
    safety = {}
    try:
        safety = dict(ALPACA_PAPER_BROKER.safety_status() or {})
    except Exception:
        safety = {"paper_mode_verified": False, "broker_execution_enabled": False}
    activation = canonical_lane_activation_contract("DAY", broker_safety=safety)
    capital = lane_capital_status("DAY")
    return {
        "day_lane_pilot_enabled": bool(activation.get("lane_enabled")),
        "day_lane_execution_enabled": bool(activation.get("execution_enabled")),
        "day_lane_pilot_mode": "paper_controlled" if activation.get("lane_enabled") else "disabled",
        "activation_contract": activation,
        "day_lane_capital_book_id": "paper_day_learning",
        "day_lane_capital_limit": capital.get("configured_limit"),
        "capital_configured": bool(capital.get("capital_configured")),
        "capital_configuration_status": capital.get("capital_configuration_status"),
        "approved_capital_ceiling": capital.get("approved_ceiling"),
        "capital_in_use": capital.get("capital_in_use"),
        "capital_reserved": capital.get("capital_reserved"),
        "capital_available": capital.get("capital_available"),
        "day_lane_max_open_positions": 1,
        "day_lane_max_completed_trades_per_session": 2,
        "day_lane_entry_cutoff_et": str(os.getenv("ASTRA_DAY_LANE_ENTRY_CUTOFF_ET", NO_NEW_ENTRIES_AFTER_ET)).strip() or NO_NEW_ENTRIES_AFTER_ET,
        "day_lane_force_flat_time_et": str(os.getenv("ASTRA_DAY_LANE_FORCE_FLAT_TIME_ET", FORCE_CLOSE_TIME_ET)).strip() or FORCE_CLOSE_TIME_ET,
        "day_lane_max_hold_minutes": int(MAX_DAY_TRADE_HOLD_MINUTES),
        "day_lane_regular_hours_only": True,
        "day_lane_same_session_exit_required": True,
        "day_lane_overnight_allowed": False,
        "day_lane_exact_symbol_cross_lane_block": True,
        "day_lane_sector_cap": int(_to_float(os.getenv("ASTRA_DAY_LANE_SECTOR_CEILING", 2), 2)),
        "day_lane_strategy_cohort_cap": int(_to_float(os.getenv("ASTRA_DAY_LANE_COHORT_CEILING", 2), 2)),
        "day_lane_correlation_cluster_cap": int(_to_float(os.getenv("ASTRA_DAY_LANE_CLUSTER_CEILING", 2), 2)),
        "day_lane_min_liquidity": os.getenv("ASTRA_DAY_LANE_MIN_LIQUIDITY", "configured_existing_gate"),
        "day_lane_max_spread": os.getenv("ASTRA_DAY_LANE_MAX_SPREAD", "configured_existing_gate"),
        "day_lane_min_candidate_quality": os.getenv("ASTRA_DAY_LANE_MIN_CANDIDATE_QUALITY", "existing_rank_and_safety_gates"),
        "day_lane_disable_switch": activation.get("kill_switch_state") == "ACTIVE",
        "day_lane_legacy_switch_status": activation.get("legacy_switch_status"),
        "day_lane_activation_contract_consistent": bool(activation.get("activation_contract_consistent")),
        "day_lane_rollback_ready": True,
        "human_approval_required": True,
        "automatic_expansion_enabled": False,
    }


def _day_lane_pilot_readiness_payload_v1(statuses: dict | None = None) -> dict:
    statuses = dict(statuses or {})
    pilot_config = dict(statuses.get("day_lane_pilot_config") or _day_lane_pilot_config_v1())
    rows = [normalize_operational_candidate(dict(row)) for row in (statuses.get("pladeu_candidate_rows") or []) if isinstance(row, dict)][:300]
    if not rows:
        rows = [normalize_operational_candidate(row) for row in PAPER_OPPORTUNITY_ALLOCATION_ENGINE.decorate_candidates(_cached_candidate_rows_for_horizon_flow_v1())]
    source_meta = dict(statuses.get("pladeu_candidate_source_metadata") or _pladeu_candidate_source_metadata_v1())
    day_rows = [row for row in rows if str(row.get("lane_id") or "").upper() == "DAY"]
    swing_rows = [row for row in rows if str(row.get("lane_id") or "").upper() == "SWING"]
    crypto_rows = [row for row in rows if str(row.get("lane_id") or "").upper() == "CRYPTO"]
    open_positions = [dict(row) for row in (statuses.get("pladeu_open_positions") or []) if isinstance(row, dict)]
    open_symbols = {str(row.get("symbol") or row.get("ticker") or "").upper() for row in open_positions}
    day_symbols = {str(row.get("symbol") or row.get("ticker") or "").upper() for row in day_rows if str(row.get("symbol") or row.get("ticker") or "").strip()}
    swing_symbols = {str(row.get("symbol") or row.get("ticker") or "").upper() for row in swing_rows if str(row.get("symbol") or row.get("ticker") or "").strip()}
    crypto_symbols = {str(row.get("symbol") or row.get("ticker") or "").upper() for row in crypto_rows if str(row.get("symbol") or row.get("ticker") or "").strip()}
    allocation = dict(statuses.get("pladeu_day_lane_allocation") or {})
    eligible_rows = [row for row in day_rows if str(row.get("symbol") or row.get("ticker") or "").upper() not in open_symbols and bool(row.get("exploration_allowed", True))]
    # Allocation-row selection is diagnostic only.  The autopilot's execution
    # trace is the sole owner of an actual paper selection.
    selected_rows = [row for row in eligible_rows if bool(row.get("selected") or row.get("paper_ready"))]
    autopilot_trace = _paper_autopilot_authoritative_trace_v3()
    actual_selected_symbols = {
        str(item.get("symbol") or "").upper()
        for item in (autopilot_trace.get("per_candidate_decision_trace") or [])
        if isinstance(item, dict) and bool(item.get("selected"))
    }
    required_fields = (
        "symbol", "canonical_symbol", "lane_id", "asset_class", "candidate_id",
        "recommendation_id", "strategy_cohort", "candidate_source", "source_record_id",
        "ranking_version", "generated_at", "expires_at", "capital_book_id", "entry_owner", "exit_owner",
        "candidate_fingerprint",
    )
    complete = sum(1 for row in eligible_rows if all(row.get(field) not in (None, "") for field in required_fields))
    metadata_incomplete = max(0, len(eligible_rows) - complete)
    session = str(source_meta.get("market_session_status") or "closed").lower()
    freshness = str(source_meta.get("candidate_freshness_status") or "MISSING")
    current_rows = day_rows if freshness == "CURRENT" else []
    # DAY is explicitly regular-hours-only.  Pre/post-market candidates may be
    # observed but never receive an order-capable readiness result.
    session_open = day_regular_session_allowed(session)
    handoff_proof = lane_handoff_proof(
        "DAY",
        [row for row in (autopilot_trace.get("per_candidate_decision_trace") or []) if isinstance(row, dict)],
        lane_capital_status("DAY"),
        session=session,
    )
    handoff = bool(handoff_proof.get("proven"))
    stage_trace = []
    for row in current_rows[:25]:
        symbol = str(row.get("symbol") or row.get("ticker") or "").upper()
        row_trace = {
            "candidate_id": str(row.get("candidate_id") or ""),
            "symbol": symbol,
            "lane": str(row.get("lane_id") or "DAY"),
            "strategy_cohort": str(row.get("strategy_cohort") or ""),
            "current_status": "eligible" if row in eligible_rows else "rejected",
            "eligibility_result": "PASS" if row in eligible_rows else "BLOCKED",
            "allocation_result": "PASS" if row in eligible_rows else "BLOCKED",
            "diversity_result": "PASS" if allocation.get("cross_lane_exact_symbol_check") else "BLOCKED",
            "duplicate_result": "BLOCKED" if symbol in open_symbols else "PASS",
            "capital_result": "PASS" if pilot_config.get("capital_configured") else str(pilot_config.get("capital_configuration_status") or "CAPITAL_CONFIGURATION_REQUIRED"),
            "session_result": "PASS" if session_open else "BLOCKED_MARKET_CLOSED",
            "selection_result": "SELECTED" if row in selected_rows else "NOT_SELECTED",
            "paper_autopilot_result": "NOT_REACHED",
            "exact_blocker": "",
        }
        if symbol in open_symbols:
            row_trace["exact_blocker"] = "duplicate_active_position"
        elif not session_open:
            row_trace["exact_blocker"] = "session_order_submission_blocked"
        elif not pilot_config.get("capital_configured"):
            row_trace["exact_blocker"] = "CAPITAL_CONFIGURATION_REQUIRED"
        elif not pilot_config.get("day_lane_pilot_enabled"):
            row_trace["exact_blocker"] = "day_lane_pilot_disabled_pending_human_activation"
        elif not handoff:
            row_trace["exact_blocker"] = "paper_autopilot_handoff_dry_run_not_proven"
        else:
            row_trace["paper_autopilot_result"] = "READY_FOR_PAPER_ORDER"
        stage_trace.append(row_trace)
    blockers: list[str] = []
    if freshness in {"MISSING", "STALE"}:
        blockers.append("candidate_source_stale" if freshness == "STALE" else "candidate_pipeline_unwired")
    if freshness == "CURRENT" and metadata_incomplete:
        blockers.append("current_eligible_candidates_missing_required_metadata")
    if day_symbols & swing_symbols:
        blockers.append("day_swing_exact_symbol_overlap")
    if day_symbols & crypto_symbols:
        blockers.append("day_crypto_exact_symbol_overlap")
    exit_contract = _day_lane_exit_contract_v2()
    open_day_positions = sum(1 for row in open_positions if str(row.get("lane_id") or "").upper() == "DAY")
    lifecycle_state = dict(_DAY_TRADING_LIFECYCLE_STATE or {})
    same_session_exit_state = (
        "NOT_APPLICABLE_NO_DAY_POSITION"
        if open_day_positions == 0
        else str(lifecycle_state.get("same_session_exit_state") or "NOT_EVALUATED")
    )
    if exit_contract.get("status") != "AUTHORIZED_AND_PROVEN":
        blockers.append("same_session_exit_contract_not_proven")
    if not pilot_config.get("capital_configured"):
        blockers.append(str(pilot_config.get("capital_configuration_status") or "CAPITAL_CONFIGURATION_REQUIRED"))
    if not allocation.get("cross_lane_exact_symbol_check", False):
        blockers.append("cross_lane_duplicate_check_unavailable")
    if not handoff:
        blockers.append("paper_autopilot_handoff_dry_run_not_proven")
    if pilot_config.get("day_lane_disable_switch"):
        blockers.append("PILOT_DISABLE_SWITCH_ACTIVE")
    if pilot_config.get("day_lane_pilot_enabled") and not pilot_config.get("day_lane_disable_switch"):
        blockers.append("explicit_pilot_activation_detected_review_required") if not pilot_config.get("human_approval_required") else None
    if pilot_config.get("day_lane_disable_switch"):
        status = "PILOT_PAUSED"
        warnings = []
    elif not pilot_config.get("capital_configured"):
        status = "CONFIGURATION_REQUIRED"
        warnings = ["CAPITAL_CONFIGURATION_REQUIRED"]
    elif not session_open and not current_rows:
        status = "MARKET_CLOSED"
        warnings = ["NO_CURRENT_MARKET_SESSION"]
    elif blockers:
        status = "AUTOPILOT_HANDOFF_BLOCKED" if not handoff else "NOT_READY"
        warnings = []
    else:
        status = "PILOT_ACTIVE" if pilot_config.get("day_lane_pilot_enabled") else "READY_FOR_HUMAN_APPROVAL"
        warnings = []
    return {
        "endpoint": "/api/day_lane_pilot_readiness_v1",
        "status": status,
        "current_market_session": session,
        "classified_day_candidates": len(day_rows),
        "historical_classified_day_candidates": len(day_rows) if freshness != "CURRENT" else 0,
        "current_day_candidates": len(current_rows),
        "eligible_day_candidates": len([row for row in current_rows if row in eligible_rows]),
        "diagnostic_selected_day_candidates": len([row for row in current_rows if row in selected_rows]),
        "actual_selected_day_candidates": len(
            [row for row in current_rows if str(row.get("symbol") or row.get("ticker") or "").upper() in actual_selected_symbols]
        ),
        # Backward-compatible alias retained as diagnostic-only, never use as
        # proof of paper-autopilot selection.
        "selected_day_candidates": len([row for row in current_rows if row in selected_rows]),
        "actual_selection_owner": "PaperAutopilot.per_candidate_decision_trace.selected",
        "diagnostic_selection_is_not_actual_selection": True,
        "open_day_positions": open_day_positions,
        "candidate_stage_trace": stage_trace,
        "metadata_complete_count": complete if freshness == "CURRENT" else 0,
        "metadata_incomplete_count": metadata_incomplete if freshness == "CURRENT" else 0,
        "day_swing_exact_overlap": sorted(day_symbols & swing_symbols),
        "day_crypto_exact_overlap": sorted(day_symbols & crypto_symbols),
        "correlation_checks_available": bool(allocation.get("breakdown", {}).get("correlation_cluster") is not None),
        "sector_caps_available": bool(allocation.get("diversity_ceilings", {}).get("one_sector")),
        "strategy_caps_available": bool(allocation.get("diversity_ceilings", {}).get("one_strategy_cohort")),
        "duplicate_thesis_checks_available": bool(allocation.get("cross_lane_exact_symbol_check")),
        "paper_autopilot_handoff_proven": handoff,
        "paper_autopilot_handoff_proof": handoff_proof,
        "same_session_exit_contract_status": exit_contract.get("status"),
        "same_session_exit_contract": exit_contract,
        "same_session_exit_state": same_session_exit_state,
        "same_session_exit_reason": str(lifecycle_state.get("session_exit_reason") or "no_day_owned_position" if open_day_positions == 0 else lifecycle_state.get("session_exit_reason") or ""),
        "capital_book_isolation_status": "PASS" if pilot_config.get("capital_configured") else "BLOCKED",
        "pilot_enabled": bool(pilot_config.get("day_lane_pilot_enabled")),
        "pilot_mode": pilot_config.get("day_lane_pilot_mode"),
        "pilot_config": pilot_config,
        "human_approval_required": True,
        "exact_blockers": sorted(set(blockers)),
        "warnings": warnings,
        "deferred_evidence": ["no_current_qualifying_candidates"] if not current_rows and session_open and freshness == "CURRENT" else [],
        **source_meta,
        "candidate_flow_source": "bounded_top_buys_runtime_snapshot",
        "broker_actions_used": 0,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        "behavior_safe_to_apply": False,
        "paper_mode_verified": True,
        "broker_live_endpoint_allowed": False,
        "automatic_promotion_enabled": False,
        "learned_exit_execution_enabled": False,
        "broker_behavior_changed": False,
        "live_trading_changed": False,
    }


def _multilane_paper_operational_status_v1_payload(statuses: dict | None = None) -> dict:
    """Consolidate existing lane owners without broker/provider activity."""
    statuses = dict(statuses or {})
    if not callable(build_multilane_operational_status):
        return {
            "endpoint": "/api/multilane_paper_operational_status_v1",
            "status": "ASTRA_MULTILANE_OPERATIONAL_BLOCKED",
            "top_blockers": ["multilane_operational_builder_unavailable"],
            "provider_calls_used": 0, "broker_actions_used": 0, "llm_calls_used": 0,
            **_safety_flags_v1(),
        }
    authoritative_trace = _paper_autopilot_authoritative_trace_v3()
    trace_candidates = [dict(row) for row in (authoritative_trace.get("per_candidate_decision_trace") or []) if isinstance(row, dict)]
    candidates = trace_candidates or [dict(row) for row in (statuses.get("pladeu_candidate_rows") or []) if isinstance(row, dict)]
    # Crypto rankings are stored separately from the equity top-buys cache.
    # Include their bounded operational adapter; a missing cache is explicitly
    # marked as a non-tradable source probe rather than a false candidate.
    try:
        # Equity and crypto are stored in separate bounded caches.  A valid
        # equity trace must never hide the crypto lane's current freshness
        # state from the consolidated operational view.
        candidates.extend(_crypto_operational_candidate_rows_v3())
    except Exception:
        pass
    seen: set[tuple[str, str]] = set()
    unique_candidates = []
    for row in candidates:
        identity = (
            str(row.get("symbol") or row.get("ticker") or "").upper(),
            str(row.get("asset_class") or row.get("asset_type") or "equity").lower(),
        )
        if not identity[0] or identity in seen:
            continue
        seen.add(identity)
        unique_candidates.append(row)
    registry = _astra_evidence_state_json("broker_truth_records_v1.json")
    records = [dict(row) for row in (registry.get("records") or []) if isinstance(row, dict)]
    crypto_lane = _crypto_paper_lane_validation_v1_payload(statuses)
    safety = {}
    try:
        safety = dict(ALPACA_PAPER_BROKER.safety_status() or {})
    except Exception:
        safety = {"paper_mode_verified": False, "broker_execution_enabled": False}
    source = statuses.get("pladeu_candidate_source_metadata") or _pladeu_candidate_source_metadata_v1()
    source_ready = str((source or {}).get("candidate_freshness_status") or "").upper() == "CURRENT"
    equity_session = str((source or {}).get("market_session_status") or "closed")
    equity_session_allowed = day_regular_session_allowed(equity_session)
    activation_contracts = canonical_multilane_activation_contract(
        broker_safety=safety,
        lane_inputs={
            "SWING": {
                "candidate_source_ready": source_ready, "candidate_freshness_ready": source_ready,
                "session_state": equity_session, "session_allowed": equity_session_allowed,
                "session_source": "cached_equity_market_session",
            },
            "DAY": {
                "candidate_source_ready": source_ready, "candidate_freshness_ready": source_ready,
                "session_state": equity_session, "session_allowed": equity_session_allowed,
                "session_source": "cached_equity_market_session",
            },
            "CRYPTO": {
                "candidate_source_ready": bool(crypto_lane.get("operational_candidate_source_available")),
                "candidate_freshness_ready": bool(crypto_lane.get("candidate_freshness_ready")),
                "session_state": "CRYPTO_24_7_ALLOWED", "session_allowed": True,
                "session_source": "crypto_24_7_market_model",
            },
        },
    )
    if isinstance(crypto_lane.get("activation_contract"), dict):
        activation_contracts["CRYPTO"] = dict(crypto_lane["activation_contract"])
    capacity_snapshot = dict(
        statuses.get("evidence_accumulation_capacity_v1") or _evidence_accumulation_capacity_payload_v1(statuses)
    )
    release_review = dict(
        statuses.get("portfolio_capacity_release_review_v1") or _portfolio_capacity_release_review_payload_v1(statuses)
    )
    execution_ledger = {}
    try:
        ledger = getattr(PAPER_AUTOPILOT, "execution_trace_ledger", None)
        if ledger is not None:
            execution_ledger = {"summary": dict(ledger.summary() or {}), "window": dict(ledger.window_summary(days=7) or {})}
    except Exception:
        execution_ledger = {"status": "UNAVAILABLE_FAIL_CLOSED"}
    position_reviews = [dict(row) for row in (release_review.get("position_reviews") or release_review.get("review_rows") or []) if isinstance(row, dict)]
    open_positions = [dict(row) for row in (statuses.get("pladeu_open_positions") or []) if isinstance(row, dict)]
    if not open_positions:
        # The worker already reconciled these rows while producing the
        # capacity snapshot. Reuse that committed, secret-free projection
        # rather than issuing a second broker read from this GET path.
        open_positions = [
            dict(row) for row in (capacity_snapshot.get("position_rows_for_read_only_consumers") or [])
            if isinstance(row, dict)
        ]
    operational = build_multilane_operational_status(
        candidates=unique_candidates[:300],
        open_positions=open_positions,
        broker_truth_records=records[:500],
        autopilot_trace=authoritative_trace,
        source_metadata=source,
        day_config=statuses.get("day_lane_pilot_config") or _day_lane_pilot_config_v1(),
        crypto_lane=crypto_lane,
        activation_contracts=activation_contracts,
        execution_ledger=execution_ledger,
        capacity_snapshot=capacity_snapshot,
        position_review_rows=position_reviews,
    )
    operational["evidence_accumulation_capacity_v1"] = capacity_snapshot
    operational["portfolio_capacity_release_review_v1"] = release_review
    operational["execution_trace_ledger_v1"] = execution_ledger
    return operational


def _multilane_activation_adaptive_truth_v2_payload(statuses: dict | None = None) -> dict:
    """Compact, cache-first V2 operational proof with no broker side effects."""
    statuses = dict(statuses or {})
    multiline = _multilane_paper_operational_status_v1_payload(statuses)
    records = [dict(row) for row in (_astra_evidence_state_json("broker_truth_records_v1.json").get("records") or []) if isinstance(row, dict)]
    truth = strict_truth_counts(records)
    trace = _paper_autopilot_authoritative_trace_v3()
    source = dict(statuses.get("pladeu_candidate_source_metadata") or _pladeu_candidate_source_metadata_v1())
    day_capital = lane_capital_status("DAY")
    crypto_capital = lane_capital_status("CRYPTO")
    day_handoff = lane_handoff_proof("DAY", trace.get("per_candidate_decision_trace") or [], day_capital, session=source.get("market_session_status"))
    crypto_handoff = lane_handoff_proof("CRYPTO", trace.get("per_candidate_decision_trace") or [], crypto_capital, session=source.get("market_session_status"))
    day_exit = _day_lane_exit_contract_v2()
    crypto_exit = {}
    try:
        crypto_exit = dict(PAPER_AUTOPILOT.authorized_lane_exit_status("CRYPTO") or {})
        crypto_exit["deterministic_fixture"] = dict(PAPER_AUTOPILOT.authorized_lane_exit_dry_run("CRYPTO") or {})
    except Exception as exc:
        crypto_exit = {"status": "WORKER_UNAVAILABLE", "reason": f"crypto_exit_worker_exception:{str(exc)[:100]}"}
    simulations = {}
    for lane, capital, session in (
        ("SWING", {"capital_configured": True, "capital_book_id": "paper_swing"}, "regular_hours"),
        ("DAY", day_capital, "regular_hours"),
        ("CRYPTO", crypto_capital, "crypto_24_7"),
    ):
        symbol = "BTC/USD" if lane == "CRYPTO" else "SPY" if lane == "DAY" else "AAPL"
        row = {
            "lane_id": lane, "symbol": symbol, "candidate_id": f"fixture-{lane.lower()}",
            "recommendation_id": f"fixture-rec-{lane.lower()}", "selection_id": f"fixture-select-{lane.lower()}",
            "selected": True, "order_ready": True, "submit_order": False, "broker_actions_used": 0,
            "capital_book_id": capital.get("capital_book_id"), "same_session_exit_required": lane == "DAY",
            "overnight_allowed": lane != "DAY", "equity_market_session_gate_applied": False,
        }
        simulations[lane.lower()] = {
            "deterministic_simulation_proof": lane_handoff_proof(lane, [row], capital, session=session),
            "fixture_truth_excluded_from_official_counts": True,
            "live_runtime_dry_run_proof": day_handoff if lane == "DAY" else crypto_handoff if lane == "CRYPTO" else lane_handoff_proof(lane, trace.get("per_candidate_decision_trace") or [], capital, session=session),
        }
    day_enabled = bool(_day_lane_pilot_config_v1().get("day_lane_pilot_enabled"))
    crypto_validation = _crypto_paper_lane_validation_v1_payload(statuses) or {}
    crypto_enabled = bool(crypto_validation.get("paper_crypto_enabled"))
    swing_trace_rows = [row for row in (trace.get("per_candidate_decision_trace") or []) if isinstance(row, dict) and str(row.get("lane_id") or "").upper() == "SWING"]
    day_trace_rows = [row for row in (trace.get("per_candidate_decision_trace") or []) if isinstance(row, dict) and str(row.get("lane_id") or "").upper() == "DAY"]
    crypto_trace_rows = [row for row in (trace.get("per_candidate_decision_trace") or []) if isinstance(row, dict) and str(row.get("lane_id") or "").upper() == "CRYPTO"]
    required_consumers = ["canonical_outcome", "symbol_behavior", "active_learning", "librarian", "warehouse", "cortex", "governance", "learning_center"]
    learning = {
        "strict_truths_available": truth.get("total_broker_confirmed_complete", 0),
        "required_consumers": required_consumers,
        "consumer_acknowledgements": 0,
        "status": "PENDING_STRICT_TRUTH" if not truth.get("total_broker_confirmed_complete") else "ACKNOWLEDGEMENT_RECONCILIATION_REQUIRED",
        "strict_truth_path_deterministically_proven": all(
            bool((simulations.get(lane, {}).get("deterministic_simulation_proof") or {}).get("proven"))
            for lane in ("swing", "day", "crypto")
        ),
        "actual_delivery_evidence_pending": not bool(truth.get("total_broker_confirmed_complete")),
        "payload_references_not_accepted_as_acknowledgement": True,
    }
    blockers = []
    if not day_capital.get("capital_configured"):
        blockers.append(str(day_capital.get("capital_configuration_status")))
    if not crypto_capital.get("capital_configured"):
        blockers.append(str(crypto_capital.get("capital_configuration_status")))
    # A missing current candidate trace is evidence pending, not an activation
    # defect.  The worker must never manufacture candidates or orders simply
    # to make a readiness screen green.
    deferred_runtime_evidence = []
    if not swing_trace_rows:
        deferred_runtime_evidence.append("SWING_CURRENT_CANDIDATE_TRACE_PENDING")
    if not day_handoff.get("proven"):
        deferred_runtime_evidence.append("DAY_CURRENT_AUTHORITATIVE_TRACE_PENDING")
    if not crypto_trace_rows:
        deferred_runtime_evidence.append("CRYPTO_CURRENT_CANDIDATE_TRACE_PENDING")
    if not crypto_validation.get("broker_capability_available"):
        blockers.append("CRYPTO_BROKER_CAPABILITY_BLOCKED")
    if not crypto_validation.get("operational_candidate_source_available"):
        blockers.append("CRYPTO_OPERATIONAL_SOURCE_UNAVAILABLE")
    if not day_enabled:
        blockers.append("DAY_PILOT_NOT_ENABLED_PENDING_LIVE_DRY_RUN")
    if not crypto_enabled:
        blockers.append("CRYPTO_LANE_NOT_ENABLED_PENDING_FINAL_GATE")
    pending_actual_truth = not bool(truth.get("total_broker_confirmed_complete"))
    activation_contracts = {
        lane: dict((multiline.get("lanes") or {}).get(lane.lower(), {}).get("activation_contract") or {})
        for lane in ("SWING", "DAY", "CRYPTO")
    }
    contracts_consistent = all(bool(contract.get("activation_contract_consistent", False)) for contract in activation_contracts.values())
    status = (
        "ASTRA_MULTILANE_LIVE_ACTIVATION_PASS"
        if not blockers and not pending_actual_truth
        else "ASTRA_MULTILANE_LIVE_ACTIVATION_PASS_WITH_EVIDENCE_ACCUMULATION_PENDING"
        if not blockers and contracts_consistent and day_enabled and crypto_enabled
        else "ASTRA_MULTILANE_LIVE_ACTIVATION_BLOCKED"
    )
    return {
        "endpoint": "/api/astra_multilane_activation_adaptive_truth_v2",
        "suite": "ASTRA_MULTILANE_ACTIVATION_ADAPTIVE_TRUTH_V2",
        "status": status,
        "lanes": multiline.get("lanes"),
        "activation_contracts": activation_contracts,
        "activation_contract_consistent": contracts_consistent,
        "day_configuration": {**day_capital, "pilot_enabled": day_enabled},
        "crypto_configuration": {**crypto_capital, "lane_enabled": crypto_enabled, "enablement_key": "ASTRA_ENABLE_ALPACA_CRYPTO_PAPER"},
        "candidate_freshness": operational_freshness(source.get("candidate_snapshot_age_seconds", source.get("candidate_cache_age_seconds"))),
        "handoff_proof": {"day": day_handoff, "crypto": crypto_handoff},
        "authoritative_trace_counts": {"swing": len(swing_trace_rows), "day": len(day_trace_rows), "crypto": len(crypto_trace_rows)},
        "exit_authorization": {"day": day_exit, "crypto": crypto_exit},
        "adaptive_throughput": {"day": adaptive_throughput("DAY", records), "crypto": adaptive_throughput("CRYPTO", records)},
        "strict_broker_truth": truth,
        "learning_delivery": learning,
        "simulations": simulations,
        "deferred_live_market_evidence": list(dict.fromkeys(
            deferred_runtime_evidence
            + (["DAY current regular-session authoritative candidate and paper round trip"] if not day_handoff.get("proven") else [])
            + (["actual paired paper fills and consumer acknowledgements"] if pending_actual_truth else [])
        )),
        "top_blockers": list(dict.fromkeys(blockers)),
        "provider_calls_used": 0, "broker_actions_used": 0, "llm_calls_used": 0, "full_history_scan_count": 0,
        "live_trading_enabled": False, "automatic_promotions_enabled": False, "learned_exits_enabled": False,
        **_safety_flags_v1(),
    }


def _candidate_horizon_from_row_v1(row: dict) -> str:
    style = _turnover_intended_style_from_row_v1(row)
    if style in {"standard_swing", "short_swing", "extended_swing", "swing"}:
        return "swing_trade"
    if style in {"scalp", "day_trade", "swing_trade"}:
        return style
    hold = str(row.get("best_hold") or row.get("best_hold_horizon") or row.get("expected_hold_window") or row.get("horizon") or "").lower()
    if "scalp" in hold or "15m" in hold or "30m" in hold or "45m" in hold or "60m" in hold:
        return "scalp"
    if "intraday" in hold or "day" in hold or "eod" in hold or "2h" in hold or "4h" in hold:
        return "day_trade"
    if "swing" in hold or "2d" in hold or "5d" in hold or "10d" in hold:
        return "swing_trade"
    return "unknown"


def _is_equity_candidate_row_v1(row: dict) -> bool:
    asset_class = str(row.get("asset_class") or row.get("asset_type") or "equity").lower()
    symbol = str(row.get("symbol") or row.get("ticker") or "").upper().strip()
    return asset_class not in {"crypto", "cryptocurrency"} and "/" not in symbol


def _horizon_candidate_flow_v1(statuses: dict | None = None) -> dict:
    statuses = dict(statuses or {})
    horizon_bundle = statuses.get("astra_horizon_lifecycle_capacity_promotion_readiness_bundle_v1")
    if not isinstance(horizon_bundle, dict) or not horizon_bundle:
        horizon_bundle = _astra_evidence_state_json("dashboard_cache/astra_horizon_lifecycle_capacity_promotion_readiness_bundle_v1.json")
    assignment = {}
    if isinstance(horizon_bundle, dict):
        for key in ("horizon_opportunity_assignment_engine_v1", "horizon_opportunity_assignment", "opportunity_assignment"):
            if isinstance(horizon_bundle.get(key), dict):
                assignment = dict(horizon_bundle.get(key) or {})
                break
        if not assignment and isinstance(horizon_bundle.get("adaptive_horizon_participation_engine_v1"), dict):
            assignment = dict(horizon_bundle.get("adaptive_horizon_participation_engine_v1") or {})
        if isinstance(horizon_bundle.get("assigned_horizon_rows"), list) or "horizon_assignment_version" in horizon_bundle:
            merged_assignment = dict(assignment)
            for key in (
                "assigned_horizon_rows",
                "horizon_assignment_dropoff_point",
                "horizon_assignment_used",
                "horizon_assignment_blocker",
                "horizon_execution_blocker",
                "horizon_participation_blocker",
                "qualified_day_trade_candidates",
                "qualified_scalp_candidates",
                "qualified_swing_trade_candidates",
                "best_replacement_candidates",
            ):
                if key in horizon_bundle and key not in merged_assignment:
                    merged_assignment[key] = horizon_bundle.get(key)
            assignment = merged_assignment
    trace = _paper_autopilot_last_trace_v1()
    trace_rows = [dict(row) for row in (trace.get("per_candidate_decision_trace") or []) if isinstance(row, dict)]
    source = "paper_autopilot_last_execution_trace" if trace_rows else "cached_top_buys_snapshot"
    if assignment:
        candidate_counts = {
            "scalp": int(_to_float(assignment.get("shadow_scalp_candidates"), 0.0)),
            "day_trade": int(_to_float(assignment.get("shadow_day_trade_candidates"), 0.0)),
            "swing_trade": int(_to_float(assignment.get("shadow_swing_trade_candidates"), 0.0)),
        }
        qualified_counts = {
            "scalp": int(_to_float(assignment.get("qualified_scalp_candidates"), 0.0)),
            "day_trade": int(_to_float(assignment.get("qualified_day_trade_candidates"), 0.0)),
            "swing_trade": int(_to_float(assignment.get("qualified_swing_trade_candidates"), 0.0)),
        }
        replacement_rows = [dict(row) for row in (assignment.get("best_replacement_candidates") or []) if isinstance(row, dict) and _is_equity_candidate_row_v1(row)]
        assigned_rows = [dict(row) for row in (assignment.get("assigned_horizon_rows") or []) if isinstance(row, dict) and _is_equity_candidate_row_v1(row)]
        # Replacement suggestions are not candidate-generation records.  They
        # may be duplicate or capacity-blocked incumbents, so counting them as
        # DAY candidates fabricated a funnel before horizon qualification.
        if not any(candidate_counts.values()) and assigned_rows:
            for row in assigned_rows:
                horizon = str(row.get("assigned_horizon") or _candidate_horizon_from_row_v1(row))
                if horizon in candidate_counts:
                    candidate_counts[horizon] += 1
        rejected_counts = {key: max(0, candidate_counts.get(key, 0) - qualified_counts.get(key, 0)) for key in candidate_counts}
        block_reasons = assignment.get("block_reasons") if isinstance(assignment.get("block_reasons"), dict) else {}
        if not block_reasons:
            blocker = str(
                assignment.get("horizon_participation_blocker")
                or assignment.get("horizon_assignment_blocker")
                or assignment.get("horizon_execution_blocker")
                or assignment.get("practice_bucket_blocker")
                or assignment.get("paper_tie_breaker_blocker")
                or "existing_rank_and_safety_gates"
            )
            block_reasons = {blocker: sum(rejected_counts.values())}
        per_horizon_reasons = {
            horizon: {
                reason: int(_to_float(count, 0.0))
                for reason, count in block_reasons.items()
                if int(_to_float(count, 0.0)) > 0
            }
            for horizon in ("scalp", "day_trade", "swing_trade")
        }
        if len(block_reasons) == 1:
            reason = next(iter(block_reasons))
            per_horizon_reasons = {
                horizon: ({reason: int(rejected_counts.get(horizon, 0))} if int(rejected_counts.get(horizon, 0)) > 0 else {})
                for horizon in ("scalp", "day_trade", "swing_trade")
            }
        return {
            "candidate_flow_status": str(assignment.get("status") or "ok"),
            "candidate_flow_source": "existing_horizon_lifecycle_capacity_bundle_v1",
            "candidate_count_by_horizon": candidate_counts,
            "qualified_count_by_horizon": qualified_counts,
            "rejected_count_by_horizon": rejected_counts,
            "rejection_reasons_by_horizon": per_horizon_reasons,
            "dropoff_point_by_horizon": {
                "scalp": str(assignment.get("horizon_assignment_dropoff_point") or assignment.get("practice_bucket_blocker") or ""),
                "day_trade": str(assignment.get("horizon_assignment_dropoff_point") or assignment.get("paper_tie_breaker_blocker") or ""),
                "swing_trade": "existing_rank_and_safety_gates",
            },
            "selected_day_trade_candidates": [r for r in assigned_rows if str(r.get("assigned_horizon") or r.get("horizon") or "") == "day_trade" and bool(r.get("selected"))][:8],
            "selected_scalp_shadow_candidates": [r for r in assigned_rows if str(r.get("assigned_horizon") or r.get("horizon") or "") == "scalp"][:8],
            "paper_autopilot_horizon_assignment_used": bool(assignment.get("horizon_assignment_used")),
            "paper_tie_breaker_blocker": str(assignment.get("paper_tie_breaker_blocker") or ""),
            "candidate_flow_evidence_status": "INSUFFICIENT_EQUITY_CANDIDATE_TRACE" if not any(candidate_counts.values()) and replacement_rows else "CURRENT_CANDIDATE_TRACE",
            "replacement_rows_excluded_from_candidate_funnel": len(replacement_rows),
            "excluded_replacement_rows": replacement_rows[:10],
            "provider_calls_used": 0,
            "llm_calls_used": 0,
            **_safety_flags_v1(),
        }
    if not trace_rows:
        trace_rows = _cached_candidate_rows_for_horizon_flow_v1()
    candidate_counts = Counter()
    qualified_counts = Counter()
    rejected_counts = Counter()
    reasons: dict[str, Counter] = defaultdict(Counter)
    selected_day: list[dict] = []
    selected_scalp: list[dict] = []
    excluded_non_equity_rows = 0
    for row in trace_rows:
        if not _is_equity_candidate_row_v1(row):
            excluded_non_equity_rows += 1
            continue
        horizon = _candidate_horizon_from_row_v1(row)
        if horizon not in {"scalp", "day_trade", "swing_trade"}:
            horizon = "unknown"
        candidate_counts[horizon] += 1
        eligible = bool(row.get("eligible") or row.get("selected"))
        selected = bool(row.get("selected"))
        reason = str(row.get("decision_reason") or row.get("rejection_reason") or ("eligible" if eligible else "not_qualified_or_not_evaluated"))
        if eligible:
            qualified_counts[horizon] += 1
        else:
            rejected_counts[horizon] += 1
            reasons[horizon][reason] += 1
        if horizon == "day_trade" and selected:
            selected_day.append(row)
        if horizon == "scalp":
            selected_scalp.append(row)
    all_horizons = ["scalp", "day_trade", "swing_trade", "unknown"]
    return {
        "candidate_flow_status": "ok" if trace_rows else "insufficient_candidate_trace",
        "candidate_flow_source": source,
        "candidate_count_by_horizon": {h: int(candidate_counts.get(h, 0)) for h in all_horizons},
        "qualified_count_by_horizon": {h: int(qualified_counts.get(h, 0)) for h in all_horizons},
        "rejected_count_by_horizon": {h: int(rejected_counts.get(h, 0)) for h in all_horizons},
        "rejection_reasons_by_horizon": {h: dict(reasons.get(h, {})) for h in all_horizons},
        "dropoff_point_by_horizon": {
            h: (max((reasons.get(h) or {"none": 0}).items(), key=lambda item: item[1])[0] if int(rejected_counts.get(h, 0)) else "no_dropoff_detected")
            for h in all_horizons
        },
        "selected_day_trade_candidates": selected_day[:8],
        "selected_scalp_shadow_candidates": selected_scalp[:8],
        "paper_autopilot_horizon_assignment_used": bool(trace.get("horizon_assignment_used", False)),
        "paper_tie_breaker_blocker": str(trace.get("paper_tie_breaker_blocker") or trace.get("horizon_execution_blocker") or trace.get("final_blocker_reason") or ""),
        "excluded_non_equity_candidate_rows": excluded_non_equity_rows,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


def _capacity_lane_diagnostics_v1(statuses: dict | None = None) -> dict:
    statuses = dict(statuses or {})
    audit = _horizon_turnover_exit_audit_v1_payload(statuses)
    capacity = audit.get("capacity_utilization") if isinstance(audit.get("capacity_utilization"), dict) else {}
    trace = _paper_autopilot_last_trace_v1()
    style_dist = audit.get("trade_style_distribution") if isinstance(audit.get("trade_style_distribution"), dict) else {}
    swing_used = int(_to_float(style_dist.get("short_swing"), 0.0) + _to_float(style_dist.get("standard_swing"), 0.0) + _to_float(style_dist.get("extended_swing"), 0.0) + _to_float(style_dist.get("swing_trade"), 0.0))
    day_used = int(_to_float(style_dist.get("day_trade"), 0.0))
    scalp_used = int(_to_float(style_dist.get("scalp"), 0.0))
    total_capacity = int(_to_float(capacity.get("total_capacity"), 20.0))
    swing_capacity = int(_to_float(capacity.get("swing_capacity"), 8.0))
    day_capacity = int(_to_float(capacity.get("day_capacity"), 8.0))
    adaptive_capacity = max(0, total_capacity - swing_capacity - day_capacity)
    blockers = Counter()
    duplicate = Counter()
    maxpos = Counter()
    for row in trace.get("per_candidate_decision_trace") or []:
        if not isinstance(row, dict):
            continue
        reason = str(row.get("decision_reason") or "")
        if "capacity" in reason:
            blockers[reason] += 1
        if reason == "duplicate_active_position":
            duplicate[str(row.get("duplicate_source") or "unknown")] += 1
        if "max_concurrent" in reason or "max_new" in reason:
            maxpos[reason] += 1
    day_available = max(0, day_capacity - day_used)
    return {
        "total_capacity": total_capacity,
        "swing_capacity": swing_capacity,
        "day_trade_capacity": day_capacity,
        "adaptive_capacity": adaptive_capacity,
        "scalp_shadow_capacity": int(_to_float(capacity.get("scalp_capacity"), 4.0)),
        "swing_slots_used": swing_used,
        "day_trade_slots_used": day_used,
        "adaptive_slots_used": max(0, int(_to_float(audit.get("deduped_active_symbols"), 0.0)) - swing_used - day_used - scalp_used),
        "scalp_shadow_slots_used": scalp_used,
        "available_day_trade_slots": day_available,
        "available_swing_slots": max(0, swing_capacity - swing_used),
        "capacity_gate_blockers": dict(blockers),
        "duplicate_symbol_blockers": dict(duplicate),
        "max_position_blockers": dict(maxpos),
        "day_trade_lane_blocked_reason": "" if day_available > 0 else "day_trade_lane_capacity_full_or_unclassified_swing_congestion",
        "day_trade_lane_ready_status": "ready_advisory_capacity_available" if day_available > 0 else "blocked_or_needs_recycling",
        "horizon_lanes_are_hard_quotas": False,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


def _scalp_learning_bucket_v1(statuses: dict | None = None) -> dict:
    flow = _horizon_candidate_flow_v1(statuses)
    scalp_candidates = int(_to_float((flow.get("candidate_count_by_horizon") or {}).get("scalp"), 0.0))
    selected_scalp = len(flow.get("selected_scalp_shadow_candidates") or [])
    return {
        "scalp_paper_behavior_enabled": False,
        "scalp_live_behavior_enabled": False,
        "scalp_shadow_practice_active": bool(scalp_candidates > 0 or selected_scalp > 0),
        "scalp_candidate_count": scalp_candidates,
        "scalp_shadow_entry_count": selected_scalp,
        "scalp_shadow_exit_count": 0,
        "scalp_replay_outcomes": 0,
        "scalp_lessons": [],
        "scalp_blockers": ["paper_broker_execution_not_enabled_for_scalp", "shadow_practice_only_pending_future_approval"],
        "scalp_promotion_readiness": "not_ready_paper_execution_disabled_by_policy",
        "scalp_learning_status": "shadow_practice_ready" if scalp_candidates > 0 else "waiting_for_scalp_candidates",
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


def _capacity_recycling_diagnostics_v1(statuses: dict | None = None) -> dict:
    statuses = dict(statuses or {})
    readiness = _exit_readiness_diagnostics_v1_payload(statuses)
    audit = _horizon_turnover_exit_audit_v1_payload(statuses)
    exit_rows = list(readiness.get("exit_review_candidates") or [])
    replace_rows = list(readiness.get("replacement_candidates") or [])
    stale_rows = list(readiness.get("stale_review_candidates") or [])
    drift_rows = list(readiness.get("horizon_drift_candidates") or readiness.get("horizon_mismatch_candidates") or [])
    trapped = [row for row in (exit_rows + replace_rows + stale_rows) if _to_float(row.get("opportunity_cost_score"), 0.0) >= 75.0 or _to_float(row.get("days_held"), 0.0) >= 21.0]
    combined = []
    seen = set()
    for row in exit_rows + replace_rows + drift_rows + trapped:
        sym = str(row.get("symbol") or "")
        if sym and sym not in seen:
            seen.add(sym)
            combined.append(row)
    return {
        "stale_positions_count": int(_to_float(audit.get("stale_position_count"), 0.0)),
        "exit_review_count": len(exit_rows),
        "replacement_candidate_count": len(replace_rows),
        "capital_trapped_count": len(trapped),
        "horizon_drift_count": len(drift_rows),
        "capacity_recycling_candidates": combined[:12],
        "top_positions_blocking_capacity": sorted(trapped, key=lambda r: (_to_float(r.get("days_held"), 0.0), _to_float(r.get("opportunity_cost_score"), 0.0)), reverse=True)[:10],
        "top_replacement_candidates": replace_rows[:10],
        "recycling_blockers": [
            "advisory_only_no_forced_exits",
            "broker_truth_complete_sample_below_threshold" if int(_to_float((_broker_truth_growth_monitor_v1_payload(statuses)).get("broker_confirmed_complete_records"), 0.0)) < 25 else "",
        ],
        "advisory_recycling_status": "review_candidates_available_no_sell_behavior",
        "broker_sell_behavior_enabled": False,
        "forced_exits_enabled": False,
        "provider_calls_used": 0,
        "llm_calls_used": 0,
        **_safety_flags_v1(),
    }


