def _attach_astra_intelligence_maturation_readiness_report_v1(target: dict, statuses: dict | None = None, *, force: bool = False) -> dict:
    if not isinstance(target, dict):
        return {}
    if force or not isinstance(target.get("astra_intelligence_maturation_readiness_report_v1"), dict):
        target["astra_intelligence_maturation_readiness_report_v1"] = _astra_intelligence_maturation_readiness_report_v1_payload(statuses or target)
    return dict(target.get("astra_intelligence_maturation_readiness_report_v1") or {})


def _phase2a_summary_index_v1(name: str) -> dict:
    payload = _astra_evidence_state_json(f"storage_summary_indexes/{name}.jsonl.summary_index.json")
    return dict(payload or {}) if isinstance(payload, dict) else {}


def _phase2a_dimension_coverage_v1(index_payload: dict, field: str) -> float:
    dims = index_payload.get("dimension_counts") if isinstance(index_payload.get("dimension_counts"), dict) else {}
    values = dims.get(field) if isinstance(dims.get(field), dict) else {}
    if not values:
        return 0.0
    total = sum(int(_to_float(v, 0.0)) for v in values.values())
    unknown = sum(
        int(_to_float(v, 0.0))
        for key, v in values.items()
        if str(key or "").strip().lower() in {"", "unknown", "unknown_regime", "unknown_horizon", "unknown_sector", "none", "null", "n/a"}
    )
    return round(max(0.0, min(100.0, ((total - unknown) / max(1, total)) * 100.0)), 3)


def _phase2a_status_from_score_v1(score: float) -> str:
    if score >= 80:
        return "PASS"
    if score >= 45:
        return "PARTIAL"
    return "BLOCKED"


def _evidence_consumption_index_health_v1(index_payload: dict) -> float:
    if not isinstance(index_payload, dict) or not index_payload:
        return 0.0
    sample_rows = _to_float(index_payload.get("sample_rows"), 0.0)
    source_rows = _to_float(index_payload.get("source_line_count_estimate"), sample_rows)
    dimension_counts = index_payload.get("dimension_counts") if isinstance(index_payload.get("dimension_counts"), dict) else {}
    dimension_score = min(100.0, len([key for key, value in dimension_counts.items() if isinstance(value, dict) and value]) * 12.5)
    coverage_score = min(100.0, sample_rows / 25.0) if sample_rows > 0 else 0.0
    scale_score = min(100.0, source_rows / 50000.0) if source_rows > 0 else 0.0
    return round(_astra_score_average_v1(dimension_score, coverage_score, scale_score), 3)


def _evidence_consumption_freshness_v1(path: str) -> dict:
    full_path = os.path.join(STATE, path)
    try:
        age = max(0.0, time.time() - os.path.getmtime(full_path))
    except Exception:
        age = None
    if age is None:
        return {"freshness_status": "missing", "freshness_age_seconds": None}
    if age <= 21600:
        label = "fresh"
    elif age <= 86400:
        label = "recent"
    else:
        label = "stale"
    return {"freshness_status": label, "freshness_age_seconds": round(age, 3)}


