def _copilot_turnover_action_center_v1_payload(statuses: dict | None = None) -> dict:
    statuses = dict(statuses or {})
    audit = _horizon_turnover_exit_audit_v1_payload(statuses)
    readiness = _exit_readiness_diagnostics_v1_payload(statuses)
    broker_growth = _broker_truth_growth_monitor_v1_payload(statuses)
    mode_wiring = audit.get("paper_autopilot_mode_wiring_v1") if isinstance(audit.get("paper_autopilot_mode_wiring_v1"), dict) else _paper_autopilot_mode_wiring_v1()
    horizon_coverage = audit.get("horizon_persistence_diagnostics_v1") if isinstance(audit.get("horizon_persistence_diagnostics_v1"), dict) else _broker_truth_horizon_coverage_v1(statuses)
    capacity_lanes = _capacity_lane_diagnostics_v1(statuses)
    evidence_capacity = _evidence_accumulation_capacity_payload_v1(statuses)
    portfolio_release = _portfolio_capacity_release_review_payload_v1(statuses)
    source_alignment = _alpaca_position_source_alignment_v1(statuses)
    recycling = _capacity_recycling_diagnostics_v1(statuses)
    scalp_bucket = _scalp_learning_bucket_v1(statuses)
    opp = _opportunity_cost_turnover_diagnostics_v1_payload(statuses)
    hist = _historical_similarity_turnover_diagnostics_v1_payload(statuses)
    provider_v2 = statuses.get("astra_provider_data_knowledge_validation_v2") if isinstance(statuses.get("astra_provider_data_knowledge_validation_v2"), dict) else _provider_data_knowledge_v2_payload()
    equity_lineage = _equity_candidate_lineage_completion_v2_payload(statuses)
    equity_qualification = _equity_horizon_qualification_completion_v2_payload(statuses)
    crypto_lane = _crypto_paper_lane_validation_v1_payload(statuses)
    throughput = _learning_throughput_accelerator_v1_payload(statuses)
    market_hours_audit = _automated_market_hours_multilane_audit_payload_v1(force=False)
    actions = []
    if evidence_capacity.get("global_capacity_status") in {"GLOBAL_CAPACITY_EXHAUSTED", "BROKER_STATE_STALE", "BROKER_POSITION_DETAILS_UNAVAILABLE"}:
        actions.append({
            "action": "Review evidence accumulation capacity",
            "symbol": "PORTFOLIO",
            "priority": "high",
            "reason": evidence_capacity.get("global_capacity_status"),
            "confidence": 92,
            "paper_order_action": False,
        })
    if horizon_coverage.get("legacy_missing_horizon_records"):
        actions.append({
            "action": "Monitor horizon persistence repair",
            "symbol": "PORTFOLIO",
            "priority": "high",
            "reason": "legacy_broker_truth_rows_missing_intended_horizon_future_entries_wired",
            "confidence": 92,
            "paper_order_action": False,
        })
    if not mode_wiring.get("day_trade_lane_active"):
        actions.append({
            "action": "Review day-trade lane blocker",
            "symbol": "PORTFOLIO",
            "priority": "high",
            "reason": mode_wiring.get("day_trade_lane_blocker") or "day_trade_lane_inactive",
            "confidence": 90,
            "paper_order_action": False,
        })
    if capacity_lanes.get("day_trade_lane_ready_status") != "ready_advisory_capacity_available":
        actions.append({
            "action": "Review day-trade capacity lane",
            "symbol": "PORTFOLIO",
            "priority": "high",
            "reason": capacity_lanes.get("day_trade_lane_blocked_reason") or "day_trade_capacity_not_available",
            "confidence": 88,
            "paper_order_action": False,
        })
    if source_alignment.get("source_alignment_status") != "PASS":
        actions.append({
            "action": "Review active-position source alignment",
            "symbol": "PORTFOLIO",
            "priority": "medium",
            "reason": source_alignment.get("mismatch_reason"),
            "confidence": 84,
            "paper_order_action": False,
        })
    for row in readiness.get("exit_review_candidates") or []:
        actions.append({
            "action": "Review exit readiness",
            "symbol": row.get("symbol"),
            "priority": "high",
            "reason": ",".join(row.get("recommended_review_reason") or []),
            "confidence": row.get("exit_readiness_score"),
            "paper_order_action": False,
        })
    for row in readiness.get("profit_protection_candidates") or []:
        actions.append({
            "action": "Review profit protection",
            "symbol": row.get("symbol"),
            "priority": "medium",
            "reason": "profit_protection_score_elevated",
            "confidence": row.get("profit_protection_score"),
            "paper_order_action": False,
        })
    for row in readiness.get("stale_review_candidates") or []:
        actions.append({
            "action": "Review stale hold",
            "symbol": row.get("symbol"),
            "priority": "high" if _to_float(row.get("days_held"), 0.0) >= 30.0 else "medium",
            "reason": "position_age_exceeds_review_window",
            "confidence": row.get("exit_readiness_score"),
            "paper_order_action": False,
        })
    for row in readiness.get("horizon_drift_candidates") or readiness.get("horizon_mismatch_candidates") or []:
        actions.append({
            "action": "Review horizon drift",
            "symbol": row.get("symbol"),
            "priority": "high",
            "reason": f"intended={row.get('intended_trade_style')} actual={row.get('actual_horizon_classification')}",
            "confidence": row.get("exit_readiness_score"),
            "paper_order_action": False,
        })
    for row in (opp.get("positions_with_rising_opportunity_cost") or [])[:5]:
        actions.append({
            "action": "Review opportunity cost",
            "symbol": row.get("symbol"),
            "priority": "medium",
            "reason": "opportunity_cost_or_return_decay_rising",
            "confidence": row.get("opportunity_cost_score"),
            "paper_order_action": False,
        })
    if not actions:
        actions.append({
            "action": "Monitor turnover",
            "symbol": "PORTFOLIO",
            "priority": "normal",
            "reason": audit.get("position_accumulation_diagnosis"),
            "confidence": 55,
            "paper_order_action": False,
        })
    if market_hours_audit.get("exact_first_blocker"):
        actions.append({
            "action": "Monitor automated multi-lane audit",
            "symbol": "MULTILANE",
            "priority": "medium",
            "reason": market_hours_audit.get("exact_first_blocker"),
            "confidence": 80,
            "paper_order_action": False,
        })
    return {
        "endpoint": "/api/copilot_turnover_action_center_v1",
        "status": "ok",
        "generated_at": _now_utc_iso(),
        "top_actions": actions[:8],
        "top_stale_review_candidates": (readiness.get("stale_review_candidates") or [])[:5],
        "top_horizon_drift_candidates": (readiness.get("horizon_drift_candidates") or readiness.get("horizon_mismatch_candidates") or [])[:5],
        "top_horizon_mismatch_candidates": (readiness.get("horizon_mismatch_candidates") or [])[:5],
        "top_replacement_candidates": (readiness.get("replacement_candidates") or [])[:5],
        "top_profit_protection_candidates": (readiness.get("profit_protection_candidates") or [])[:5],
        "top_opportunity_cost_warnings": (opp.get("positions_with_rising_opportunity_cost") or [])[:5],
        "historical_similarity_warnings": (hist.get("stale_positions_with_similar_historical_failure_patterns") or [])[:5],
        "turnover_pressure": audit.get("turnover_pressure"),
        "open_to_closed_ratio": audit.get("open_to_closed_ratio"),
        "broker_truth_records_remaining": broker_growth.get("records_remaining_to_official_threshold"),
        "broker_truth_milestone_status": broker_growth.get("milestones"),
        "paper_autopilot_mode_wiring_v1": mode_wiring,
        "horizon_persistence_diagnostics_v1": horizon_coverage,
        "capacity_lane_diagnostics_v1": capacity_lanes,
        "capacity_recycling_diagnostics_v1": recycling,
        "evidence_accumulation_capacity_v1": evidence_capacity,
        "portfolio_capacity_release_review_v1": {
            "positions_by_state": portfolio_release.get("positions_by_state"),
            "human_review_required": portfolio_release.get("human_review_required"),
            "position_data_status": portfolio_release.get("position_data_status", "AVAILABLE"),
        },
        "scalp_learning_bucket_v1": scalp_bucket,
        "alpaca_position_source_alignment_v1": source_alignment,
        "provider_data_knowledge_summary_v2": {
            "status": provider_v2.get("status"),
            "fmp_runtime_status": (provider_v2.get("fmp_runtime") or {}).get("status"),
            "api_budget_status": (provider_v2.get("api_budget") or {}).get("status"),
            "cache_health": (provider_v2.get("shared_cache") or {}).get("status"),
            "provider_roi_status": (provider_v2.get("knowledge_indexing_provider_roi") or {}).get("status"),
        },
        "equity_candidate_trace_summary_v2": {key: equity_lineage.get(key) for key in ("status", "rows_retained", "trace_coverage_pct", "silent_dropoff_count")},
        "equity_qualification_summary_v2": {key: equity_qualification.get(key) for key in ("status", "generated", "qualified", "paper_eligible", "paper_autopilot_handoff", "actual_root_cause")},
        "crypto_paper_summary_v2": {key: crypto_lane.get(key) for key in ("activation_state", "paper_crypto_enabled", "selected_universe", "day_trade_capacity_available", "short_swing_capacity_available", "activation_blockers")},
        "broker_truth_throughput_summary_v2": {key: throughput.get(key) for key in ("status", "equity_complete_truths", "crypto_complete_truths", "combined_broker_lifecycle_total")},
        "automated_market_hours_multilane_audit_v1": {key: market_hours_audit.get(key) for key in ("generated_at", "trigger", "session_state", "exact_first_blocker", "counts_by_lane_asset")},
        "copilot_behavior": "advisory_only_no_orders",
        "human_review_required": True,
        "advisory_only": True,
        **_safety_flags_v1(),
    }


