@router.get("/api/paper_autopilot_throughput_status_v1")
def paper_autopilot_throughput_status_v1():
    try:
        _ensure_paper_autopilot_started()
        control = PAPER_AUTOPILOT.control_status()
        status = PAPER_AUTOPILOT.status()
        trace = PAPER_AUTOPILOT.execution_trace() if hasattr(PAPER_AUTOPILOT, "execution_trace") else {}
        try:
            obs = OBSERVATION_LEARNING_THROUGHPUT_SUITE.status()
        except Exception:
            obs = {}
        try:
            suite3 = EXECUTION_MARKET_LEARNING_EXPANSION_SUITE.status(observation_payload=obs if isinstance(obs, dict) else {})
        except Exception:
            suite3 = {}
        current_max_new = int(_to_float(control.get("max_new_positions_per_cycle"), PAPER_THROUGHPUT_EXPANDED_MAX_NEW_PER_CYCLE))
        current_max_concurrent = int(_to_float(control.get("max_open_positions_total"), PAPER_THROUGHPUT_EXPANDED_MAX_CONCURRENT_POSITIONS))
        current_cooldown = int(_to_float(control.get("cooldown_after_close_seconds"), PAPER_THROUGHPUT_EXPANDED_COOLDOWN_SECONDS))
        projected_opened = _to_float(suite3.get("projected_trades_opened_per_day"), max(1, current_max_new * 6))
        projected_closed = _to_float(suite3.get("projected_trades_closed_per_day"), max(0.5, projected_opened * 0.28))
        projected_labels = _to_float(suite3.get("projected_labels_created_per_day"), max(_to_float(obs.get("labels_created_today"), 0.0), projected_closed * 3.0))
        learning_multiplier = _to_float(suite3.get("projected_learning_speed_multiplier"), 1.0 + min(1.0, current_max_new * 0.15))
        return {
            "enabled": bool(PAPER_THROUGHPUT_EXPANSION_ENABLED),
            "version": "1.0.0",
            "mode": "paper_only",
            "local_only": True,
            "writes_files": False,
            "api_calls_used": 0,
            "live_trading_changed": False,
            "broker_execution_changed": False,
            "production_rankings_changed": False,
            "production_weights_changed": False,
            "paper_autopilot_throughput_status_v1": True,
            "autopilot_enabled": bool(status.get("autopilot_enabled", False)),
            "paper_mode": str(status.get("paper_mode") or control.get("paper_mode") or ""),
            "current_max_new_per_cycle": current_max_new,
            "baseline_max_new_per_cycle": int(PAPER_THROUGHPUT_BASE_MAX_NEW_PER_CYCLE),
            "current_max_concurrent_positions": current_max_concurrent,
            "baseline_max_concurrent_positions": int(PAPER_THROUGHPUT_BASE_MAX_CONCURRENT_POSITIONS),
            "current_cooldown_seconds": current_cooldown,
            "baseline_cooldown_seconds": int(PAPER_THROUGHPUT_BASE_COOLDOWN_SECONDS),
            "soft_candidate_expansion_enabled": bool(control.get("soft_candidate_expansion_enabled", PAPER_THROUGHPUT_SOFT_CANDIDATE_EXPANSION_ENABLED)),
            "paper_entry_threshold_relief_points": _to_float(control.get("paper_entry_threshold_relief_points"), PAPER_THROUGHPUT_ENTRY_THRESHOLD_RELIEF_POINTS),
            "natural_exit_preservation_active": bool(PAPER_THROUGHPUT_PRESERVE_NATURAL_EXITS),
            "forced_early_exits_enabled": False,
            "artificial_max_hold_forced_closures_enabled": False,
            "max_stocks": int(_to_float(control.get("max_stocks"), 12)),
            "max_crypto": int(_to_float(control.get("max_crypto"), 8)),
            "paper_learning_capacity_expansion_v1": {
                "enabled": True,
                "target_stock_positions_default": 20,
                "target_stock_positions_upper_bound": 20,
                "horizon_capacity_pools": {"scalp": 4, "day_trade": 8, "swing_trade": 8, "total": 20},
                "suggested_horizon_mix": {"scalp": 3, "day_trade": 5, "swing_short_swing_max": 7},
            "paper_only": True,
            "quality_candidates_required": True,
            "duplicate_active_symbol_block_preserved": True,
            "market_session_gate_preserved": True,
            "broker_safeguards_preserved": True,
        },
            "open_positions_count": int(_to_float(status.get("open_positions_count"), 0.0)),
            "open_position_rows_count": int(_to_float(status.get("open_position_rows_count"), 0.0)),
            "open_positions_unique_count": int(_to_float(status.get("open_positions_unique_count"), 0.0)),
            "stale_internal_workflow_row_overhang": int(_to_float(status.get("stale_internal_workflow_row_overhang"), 0.0)),
            "paper_path_status": str(trace.get("final_blocker_reason") or trace.get("why_no_trade_today") or ""),
            "capacity_available": int(_to_float(trace.get("capacity_available"), 0.0)),
            "capacity_blocked": bool(trace.get("capacity_blocked", False)),
            "projected_trades_opened_per_day": round(projected_opened, 3),
            "projected_trades_closed_per_day": round(projected_closed, 3),
            "projected_labels_created_per_day": round(projected_labels, 3),
            "projected_learning_speed_multiplier": round(learning_multiplier, 3),
            "throughput_expansion_summary": (
                f"Paper-only throughput expanded from {PAPER_THROUGHPUT_BASE_MAX_NEW_PER_CYCLE} to {current_max_new} new entries/cycle, "
                f"from {PAPER_THROUGHPUT_BASE_MAX_CONCURRENT_POSITIONS} to {current_max_concurrent} concurrent positions, "
                f"with horizon-aware paper pools of scalp 4, day trade 8, and swing trade 8 within paper safety gates; exits remain natural by default."
            ),
            "last_updated_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        }
    except Exception as exc:
        return {
            "enabled": False,
            "version": "1.0.0",
            "mode": "paper_only",
            "api_calls_used": 0,
            "live_trading_changed": False,
            "paper_autopilot_throughput_status_v1": True,
            "current_max_new_per_cycle": 0,
            "current_max_concurrent_positions": 0,
            "current_cooldown_seconds": 0,
            "soft_candidate_expansion_enabled": False,
            "projected_trades_opened_per_day": 0.0,
            "projected_trades_closed_per_day": 0.0,
            "projected_labels_created_per_day": 0.0,
            "projected_learning_speed_multiplier": 1.0,
            "error": f"paper_autopilot_throughput_status_unavailable: {str(exc)[:140]}",
        }


def _paper_execution_trace_payload(run_result=None):
    try:
        _ensure_paper_autopilot_started()
        trace = _paper_autopilot_authoritative_trace_v3()
        broker_status = {}
        try:
            broker_status = ALPACA_PAPER_BROKER.safety_status()
        except Exception as exc:
            broker_status = {"last_alpaca_error_sanitized": f"alpaca_status_exception:{str(exc)[:120]}"}
        if isinstance(run_result, dict):
            trace["manual_cycle_result"] = dict(run_result)
            trace["orders_attempted"] = int(_to_float(run_result.get("orders_attempted"), trace.get("orders_attempted", 0)))
            trace["orders_submitted"] = int(_to_float(run_result.get("orders_submitted"), trace.get("orders_submitted", 0)))
            trace["orders_rejected"] = int(_to_float(run_result.get("orders_rejected"), trace.get("orders_rejected", 0)))
            if run_result.get("final_blocker_reason"):
                trace["final_blocker_reason"] = str(run_result.get("final_blocker_reason"))[:180]
            if run_result.get("last_alpaca_error_sanitized"):
                trace["last_alpaca_error_sanitized"] = str(run_result.get("last_alpaca_error_sanitized"))[:180]
        trace["paper_execution_trace_v1"] = True
        trace["alpaca_enabled"] = bool(trace.get("alpaca_enabled", broker_status.get("enabled", False)))
        trace["paper_mode_verified"] = bool(trace.get("paper_mode_verified", broker_status.get("paper_mode_verified", False)))
        trace["broker_execution_enabled"] = bool(trace.get("broker_execution_enabled", broker_status.get("broker_execution_enabled", False)))
        trace["account_preflight_ok"] = bool(broker_status.get("account_preflight_ok", False))
        trace["broker_execution_ready"] = bool(broker_status.get("broker_execution_ready", False))
        trace["last_alpaca_error_sanitized"] = str(
            trace.get("last_alpaca_error_sanitized")
            or broker_status.get("last_alpaca_error_sanitized")
            or ""
        )[:180]
        if trace.get("broker_execution_enabled") and not trace.get("account_preflight_ok") and trace.get("last_alpaca_error_sanitized"):
            trace["final_blocker_reason"] = f"alpaca_account_preflight_failed:{trace['last_alpaca_error_sanitized']}"[:180]
        trace["api_calls_used"] = 0
        trace["provider_calls_used"] = 0
        trace["broker_actions_used"] = 0
        trace["live_trading_changed"] = False
        trace["broker_live_endpoint_allowed"] = False
        trace["natural_exit_preserved"] = True
        trace["forced_early_exit_enabled"] = False
        trace["secrets_exposed"] = False
        return trace
    except Exception as exc:
        return {
            "paper_execution_trace_v1": True,
            "paper_worker_running": False,
            "alpaca_enabled": False,
            "paper_mode_verified": False,
            "broker_execution_enabled": False,
            "candidates_seen": 0,
            "eligible_candidates": 0,
            "selected_candidates": 0,
            "orders_attempted": 0,
            "orders_submitted": 0,
            "orders_rejected": 0,
            "final_blocker_reason": f"paper_execution_trace_unavailable:{str(exc)[:140]}",
            "per_candidate_decision_trace": [],
            "last_alpaca_error_sanitized": "",
            "api_calls_used": 0,
            "live_trading_changed": False,
            "broker_live_endpoint_allowed": False,
            "natural_exit_preserved": True,
            "forced_early_exit_enabled": False,
            "secrets_exposed": False,
        }


@router.get("/api/paper_execution_trace_v1")
def paper_execution_trace_v1():
    return _paper_execution_trace_payload()


