    hero_release_consistency_score = round(max(0.0, min(100.0, _to_float(hero_release.get("hero_release_consistency_score"), 0.0))), 2)
    candidate_to_position_consistency_score = round(max(0.0, min(100.0, (_to_float(workflow_readiness.get("portfolio_readiness_confidence"), 0.0) * 0.4) + (good_trade_repeatability_score * 0.6))), 2)
    position_to_sell_consistency_score = round(max(0.0, min(100.0, (sell_truthfulness_refinement_score * 0.5) + (hold_quality_score * 0.5))), 2)
    workflow_quality_score = round(max(0.0, min(100.0, (candidate_to_position_consistency_score * 0.5) + (position_to_sell_consistency_score * 0.5))), 2)
    out["quote_quality_consistency_suite"] = {"quote_quality_cycle_stability_score": quote_quality_cycle_stability_score}
