            entry_precision_v2_training_used_count = 0
            entry_precision_v2_confirmation_count = 0
            entry_precision_v2_pullback_count = 0
            entry_precision_v2_avoid_count = 0
            signal_quality_decision_counts = {}
            signal_quality_band_counts = {}
            signal_quality_score_total = 0.0
            signal_quality_score_count = 0
            signal_quality_reject_count = 0
            signal_quality_confirmation_count = 0
            learning_activation_distribution = {}
